window.QUIZ_DATA = {"Web":{"subject":"Web","variants":[{"variant":1,"questions":[{"n":1,"question":"Какой вариант правильно описывает семантическую структуру HTML-документа:","options":[{"letter":"A","text":"<div> является универсальным контейнером для размещения всего контента"},{"letter":"B","text":"<span> используется как основной тег, полностью определяющий структуру документа"},{"letter":"C","text":"<section> используется только для оформления внешнего вида"},{"letter":"D","text":"<header>, <main>, <footer> логически разделяют содержимое по его смыслу"},{"letter":"E","text":"<b> является основным семантическим элементом, определяющим структуру текста"}],"correct":"D","explanation":"Семантические теги <header>, <main>, <footer> делят страницу на смысловые блоки, в отличие от неймового <div>, который сам по себе ничего не сообщает о содержимом."},{"n":2,"question":"Основная цель декларации DOCTYPE:","options":[{"letter":"A","text":"Определяет механизм корректного подключения CSS-файлов к документу"},{"letter":"B","text":"Является инструментом для управления порядком выполнения JavaScript-кода"},{"letter":"C","text":"Запускает специальный синтаксис, позволяющий сокращать HTML-теги"},{"letter":"D","text":"Очищает кэш браузера и обеспечивает повторную загрузку нового контента"},{"letter":"E","text":"Сообщает браузеру, какому стандарту HTML соответствует документ"}],"correct":"E","explanation":"DOCTYPE — это объявление в начале документа, которое сообщает браузеру, по какому стандарту HTML нужно рендерить страницу (например, HTML5)."},{"n":3,"question":"В каком случае тег <article> используется правильно:","options":[{"letter":"A","text":"Используется для группировки и размещения элементов навигационного меню"},{"letter":"B","text":"Применяется для изменения визуального стиля и оформления страницы"},{"letter":"C","text":"Используется для обозначения независимого, смыслового блока контента"},{"letter":"D","text":"Служит контейнером для выполнения JavaScript-кода"},{"letter":"E","text":"Используется для оформления и структурирования пользовательских форм"}],"correct":"C","explanation":"Тег <article> предназначен для самостоятельного, законченного по смыслу блока контента — например, статьи или новости, которая имеет смысл сама по себе."},{"n":4,"question":"Суть каскадности CSS:","options":[{"letter":"A","text":"Все стили применяются случайным образом без какого-либо порядка"},{"letter":"B","text":"Учитываются только стили из внешних CSS-файлов"},{"letter":"C","text":"Применяются только inline-стили, остальные игнорируются"},{"letter":"D","text":"Определяется приоритет различных стилей и выбирается применяемый"},{"letter":"E","text":"CSS-код выполняется один раз и затем не изменяется"}],"correct":"D","explanation":"Каскадность (cascade) CSS — это механизм, определяющий, какой из конфликтующих стилей применится к элементу, на основе приоритета, специфичности и порядка объявления."},{"n":5,"question":"Особенность inline-стиля:","options":[{"letter":"A","text":"Имеет самый низкий приоритет среди всех стилей"},{"letter":"B","text":"Записывается только во внешнем CSS-файле и подключается к HTML"},{"letter":"C","text":"Применяется как универсальный стиль ко всем элементам сразу"},{"letter":"D","text":"Используется только внутри media query и зависит от размера экрана"},{"letter":"E","text":"Имеет самый высокий приоритет среди всех стилей"}],"correct":"E","explanation":"Инлайн-стиль, заданный через атрибут style прямо на элементе, имеет наивысший приоритет среди обычных стилей CSS (выше внешних и внутренних таблиц стилей)."},{"n":6,"question":"Основная функция тега <nav>:","options":[{"letter":"A","text":"Используется для хранения основного контента страницы"},{"letter":"B","text":"Применяется для отображения изображений и графического контента"},{"letter":"C","text":"Является специальным контейнером для выполнения JavaScript-кода"},{"letter":"D","text":"Используется для обработки форм и отправки данных на сервер"},{"letter":"E","text":"Группирует навигационные ссылки и направляет пользователя"}],"correct":"E","explanation":"Тег <nav> используется для группировки навигационных ссылок — меню, ведущего пользователя по основным разделам сайта."},{"n":7,"question":"Правильный порядок приоритета CSS (specificity):","options":[{"letter":"A","text":"Селекторы class имеют более высокий приоритет, чем id"},{"letter":"B","text":"Селекторы element имеют более высокий приоритет, чем id"},{"letter":"C","text":"Inline-стили имеют более низкий приоритет, чем class"},{"letter":"D","text":"Приоритет определяется как: inline > id > class > element"},{"letter":"E","text":"Селекторы id имеют более низкий приоритет, чем class"}],"correct":"D","explanation":"Специфичность CSS возрастает по правилу: element < class < id < inline-стиль. Поэтому правильный порядок приоритета — inline > id > class > element."},{"n":8,"question":"Для чего используется тег <main>:","options":[{"letter":"A","text":"Для хранения и управления всеми CSS-стилями"},{"letter":"B","text":"Для создания дополнительных меню и навигационных элементов"},{"letter":"C","text":"Является основным контейнером для выполнения JavaScript-кода"},{"letter":"D","text":"Отображает основной контент страницы и содержит главную информацию"},{"letter":"E","text":"Используется для загрузки и обработки дополнительных файлов"}],"correct":"D","explanation":"<main> — семантический тег, обозначающий основной, уникальный для страницы контент, не повторяющийся в шапке, подвале или сайдбаре."},{"n":9,"question":"Основная цель Flexbox:","options":[{"letter":"A","text":"Используется для автоматического изменения размера и сжатия изображений"},{"letter":"B","text":"Позволяет полностью изменить структуру HTML и добавлять новые элементы"},{"letter":"C","text":"Является системой для выполнения JavaScript-кода"},{"letter":"D","text":"Позволяет гибко размещать элементы и управлять их выравниванием"},{"letter":"E","text":"Используется для хранения файлов и связи с сервером"}],"correct":"D","explanation":"Flexbox — это CSS-модуль для гибкого размещения элементов в одном направлении (строка/столбец) с удобным управлением выравниванием, отступами и порядком."},{"n":10,"question":"Свойство display: none:","options":[{"letter":"A","text":"Делает элемент полностью видимым и отображает его на экране"},{"letter":"B","text":"Изменяет только цвет элемента, не влияя на другие свойства"},{"letter":"C","text":"Сохраняет место элемента, но делает его невидимым"},{"letter":"D","text":"Полностью удаляет элемент и исключает его из потока документа"},{"letter":"E","text":"Добавляет анимацию и эффекты движения к элементу"}],"correct":"D","explanation":"display: none полностью убирает элемент из потока документа — он не занимает места и не отображается, в отличие от visibility: hidden, которое лишь скрывает его визуально."},{"n":11,"question":"Разница между <section> и <div>:","options":[{"letter":"A","text":"Оба выполняют одинаковую функцию и не имеют никаких различий"},{"letter":"B","text":"<div> обладает полной семантической значимостью и является основным структурным элементом"},{"letter":"C","text":"<section> используется только как простой контейнер для визуального оформления"},{"letter":"D","text":"<div> предназначен только для отображения текстовой информации"},{"letter":"E","text":"<section> обозначает смысловой раздел, а <div> используется как нейтральный контейнер"}],"correct":"E","explanation":"<section> обозначает смысловой, тематически связанный раздел документа, тогда как <div> — нейтральный контейнер без какой-либо семантики, используемый только для стилизации или скрипта."},{"n":12,"question":"Для чего используется media query:","options":[{"letter":"A","text":"Для написания и управления выполнением JavaScript-кода"},{"letter":"B","text":"Для полного изменения HTML-структуры и добавления новых элементов"},{"letter":"C","text":"Для установления связи с сервером и обмена данными"},{"letter":"D","text":"Для изменения и адаптации стилей в зависимости от размера экрана"},{"letter":"E","text":"Для управления процессом хранения и загрузки файлов"}],"correct":"D","explanation":"Media query позволяет применять разные CSS-правила в зависимости от характеристик устройства — в первую очередь ширины экрана, что является основой адаптивной верстки."},{"n":13,"question":"Основной принцип responsive-дизайна:","options":[{"letter":"A","text":"Требует использования интерфейса одинакового размера для всех устройств"},{"letter":"B","text":"Основан только на разработке дизайна для desktop-устройств"},{"letter":"C","text":"Предполагает создание интерфейса только для мобильных устройств"},{"letter":"D","text":"Обеспечивает создание гибкого дизайна, адаптирующегося под разные размеры экранов"},{"letter":"E","text":"Основан исключительно на использовании технологии CSS Grid"}],"correct":"D","explanation":"Responsive-дизайн строится на создании гибкого макета, который подстраивается под разные размеры экрана с помощью относительных единиц, media queries и flexible-сеток."},{"n":14,"question":"Для чего нужен meta viewport:","options":[{"letter":"A","text":"Для правильного подключения CSS-файлов и управления стилями"},{"letter":"B","text":"Для выполнения JavaScript-кода и запуска скриптов"},{"letter":"C","text":"Для проверки корректности HTML-структуры и выявления ошибок"},{"letter":"D","text":"Для управления масштабом страницы и адаптации на мобильных устройствах"},{"letter":"E","text":"Является дополнительным тегом, используемым только для SEO-оптимизации"}],"correct":"D","explanation":"Meta-тег viewport управляет масштабом и шириной видимой области страницы на мобильных устройствах, без него страница рендерится в desktop-масштабе."},{"n":15,"question":"Особенность position: absolute:","options":[{"letter":"A","text":"Элемент остается в нормальном потоке документа и не меняет своего положения"},{"letter":"B","text":"Элемент располагается только внутри body и не зависит от других контейнеров"},{"letter":"C","text":"Элемент позиционируется относительно ближайшего позиционированного родителя"},{"letter":"D","text":"Свойство корректно работает только внутри flex-контейнера"},{"letter":"E","text":"Положение элемента нельзя изменить, он остается фиксированным"}],"correct":"C","explanation":"position: absolute позиционирует элемент относительно ближайшего предка с position, отличным от static (например, relative). Если такого предка нет — относительно документа."},{"n":16,"question":"Преимущество Grid layout:","options":[{"letter":"A","text":"Позволяет работать только с элементами, расположенными в одном направлении"},{"letter":"B","text":"Является системой расположения только для inline-элементов"},{"letter":"C","text":"Представляет собой мощный инструмент для управления двумерной разметкой"},{"letter":"D","text":"Требует обязательного использования JavaScript"},{"letter":"E","text":"Используется только для мобильных устройств"}],"correct":"C","explanation":"CSS Grid — это система, специально созданная для двумерной разметки: одновременного управления и строками, и столбцами, в отличие от Flexbox, который работает в одном измерении."},{"n":17,"question":"На что влияет z-index:","options":[{"letter":"A","text":"Изменяет цвет элемента и влияет только на визуальный стиль"},{"letter":"B","text":"Изменяет размер элемента, управляя его шириной и высотой"},{"letter":"C","text":"Изменяет шрифт и управляет отображением текста"},{"letter":"D","text":"Определяет порядок наложения элементов и то, какой из них находится сверху"},{"letter":"E","text":"Управляет анимациями и эффектами движения"}],"correct":"D","explanation":"z-index определяет порядок наложения элементов по оси Z — какой элемент окажется выше (видимее) других при перекрытии."},{"n":18,"question":"Преимущество Semantic HTML:","options":[{"letter":"A","text":"Увеличивает объем кода и усложняет его написание"},{"letter":"B","text":"Снижает скорость загрузки сайта"},{"letter":"C","text":"Улучшает SEO и accessibility, а также делает структуру более понятной"},{"letter":"D","text":"Делает использование CSS ненужным"},{"letter":"E","text":"Полностью исключает использование JavaScript"}],"correct":"C","explanation":"Семантический HTML делает структуру понятной как для людей, так и для поисковых систем и screen-readers, что улучшает SEO и доступность (accessibility)."},{"n":19,"question":"Разница между rem и em:","options":[{"letter":"A","text":"Это одинаковые единицы измерения без различий"},{"letter":"B","text":"rem зависит от родительского элемента, а em — независим"},{"letter":"C","text":"em зависит от корневого элемента, а rem — от родительского"},{"letter":"D","text":"rem зависит от корневого элемента, а em — от родительского элемента"},{"letter":"E","text":"В настоящее время используется только единица px"}],"correct":"D","explanation":"rem всегда рассчитывается от размера шрифта корневого элемента (html), а em — от размера шрифта родительского элемента, что делает rem более предсказуемым при вложенности."},{"n":20,"question":"Эффект свойства overflow: hidden:","options":[{"letter":"A","text":"Увеличивает размер контента и автоматически расширяет элемент"},{"letter":"B","text":"Добавляет полосу прокрутки для отображения лишнего контента"},{"letter":"C","text":"Скрывает часть контента, выходящую за пределы контейнера"},{"letter":"D","text":"Перемещает контент в другое место, формируя новую структуру"},{"letter":"E","text":"Изменяет цвет элемента и его визуальные характеристики"}],"correct":"C","explanation":"overflow: hidden обрезает и скрывает часть содержимого, которая выходит за границы контейнера, без добавления полос прокрутки."},{"n":21,"question":"Направление по умолчанию для display: flex:","options":[{"letter":"A","text":"Направление column, при котором все элементы располагаются в виде столбца"},{"letter":"B","text":"Используется режим reverse, который размещает элементы в обратном порядке"},{"letter":"C","text":"Режим, обеспечивающий двумерную разметку, как в Grid"},{"letter":"D","text":"Специальное свойство, полностью скрывающее элементы"},{"letter":"E","text":"По умолчанию используется направление row, при котором элементы располагаются в строку"}],"correct":"E","explanation":"По умолчанию flex-direction имеет значение row — flex-элементы располагаются в строку слева направо (в LTR-языках)."},{"n":22,"question":"Тег <aside>:","options":[{"letter":"A","text":"Используется как основной контейнер, содержащий главный контент страницы"},{"letter":"B","text":"Является специальным тегом для выполнения JavaScript-кода"},{"letter":"C","text":"Используется для отображения дополнительной информации или боковой панели"},{"letter":"D","text":"Контейнер для хранения и управления CSS-стилями"},{"letter":"E","text":"Используется для создания форм и ввода пользовательских данных"}],"correct":"C","explanation":"<aside> предназначен для контента, косвенно связанного с основным — например, боковой панели, рекламного блока или дополнительных ссылок."},{"n":23,"question":"Что такое CSS inheritance:","options":[{"letter":"A","text":"Ситуация, при которой стили полностью удаляются и не влияют на элементы"},{"letter":"B","text":"Процесс полного копирования стилей от одного элемента к другому"},{"letter":"C","text":"Понятие, описывающее автоматическое выполнение JavaScript-кода"},{"letter":"D","text":"Передача некоторых стилей от родительского элемента к дочерним"},{"letter":"E","text":"Обеспечивает автоматическое обновление HTML-структуры"}],"correct":"D","explanation":"CSS inheritance (наследование) — это передача значений некоторых свойств (например, color, font-family) от родительского элемента к дочерним, если они явно не переопределены."},{"n":24,"question":"Для чего используется max-width:","options":[{"letter":"A","text":"Для определения минимальной ширины элемента"},{"letter":"B","text":"Для изменения высоты элемента и управления вертикальным размером"},{"letter":"C","text":"Ограничивает максимальную ширину элемента и контролирует его расширение"},{"letter":"D","text":"Используется для изменения цвета и визуального стиля"},{"letter":"E","text":"Применяется для добавления анимаций и эффектов движения"}],"correct":"C","explanation":"max-width задаёт верхнюю границу ширины элемента: даже если родитель шире, элемент не будет расти больше указанного значения."},{"n":25,"question":"Подход Mobile-first:","options":[{"letter":"A","text":"Сначала создается desktop-версия, затем адаптируется под mobile"},{"letter":"B","text":"Основан на разработке дизайна только с помощью HTML без CSS"},{"letter":"C","text":"Сначала создается мобильный дизайн, затем адаптируется под большие экраны"},{"letter":"D","text":"Сложный метод, реализуемый только с помощью JavaScript"},{"letter":"E","text":"Основан на отказе от использования Grid"}],"correct":"C","explanation":"Mobile-first — подход, при котором стили сначала пишутся для маленьких экранов, а затем дополняются media query с min-width для больших экранов."},{"n":26,"question":"<figure> и <figcaption>:","options":[{"letter":"A","text":"Используются для написания и выполнения JavaScript-кода"},{"letter":"B","text":"Контейнеры для хранения и управления CSS-стилями"},{"letter":"C","text":"Используются для совместного отображения изображения и его описания"},{"letter":"D","text":"Предназначены для создания форм и ввода данных"},{"letter":"E","text":"Используются для организации навигационных ссылок"}],"correct":"C","explanation":"<figure> группирует медиа-контент (например, изображение), а <figcaption> внутри него добавляет подпись к этому контенту."},{"n":27,"question":"position: fixed:","options":[{"letter":"A","text":"Элемент перемещается при прокрутке страницы"},{"letter":"B","text":"Элемент фиксируется на экране и не двигается при прокрутке"},{"letter":"C","text":"Работает только внутри flex-контейнера"},{"letter":"D","text":"Используется только в grid-системе"},{"letter":"E","text":"Элемент полностью удаляется из документа"}],"correct":"B","explanation":"position: fixed закрепляет элемент относительно окна браузера — он остаётся на одном месте экрана даже при прокрутке страницы."},{"n":28,"question":"Для чего нужен CSS reset:","options":[{"letter":"A","text":"Для подключения и выполнения JavaScript-файлов"},{"letter":"B","text":"Для полного изменения HTML-структуры"},{"letter":"C","text":"Для удаления стандартных стилей браузера и обеспечения единообразия"},{"letter":"D","text":"Для уменьшения размера файлов и сжатия кода"},{"letter":"E","text":"Используется только для улучшения SEO"}],"correct":"C","explanation":"CSS reset сбрасывает встроенные стили браузера (отступы, размеры заголовков и т.д.), обеспечивая одинаковый стартовый вид элементов во всех браузерах."},{"n":29,"question":"<footer>:","options":[{"letter":"A","text":"Используется как основной раздел с главным контентом страницы"},{"letter":"B","text":"Основной контейнер для навигационных ссылок"},{"letter":"C","text":"Элемент для отображения нижней информационной части страницы"},{"letter":"D","text":"Специальный тег для выполнения JavaScript"},{"letter":"E","text":"Основной контейнер для управления CSS-стилями"}],"correct":"C","explanation":"<footer> — семантический тег для нижней части страницы или раздела, обычно содержащий контакты, копирайт и дополнительные ссылки."},{"n":30,"question":"Единица измерения vh:","options":[{"letter":"A","text":"Стандартная единица, полностью равная пикселям"},{"letter":"B","text":"Относительная единица, аналогичная em"},{"letter":"C","text":"Работает так же, как rem"},{"letter":"D","text":"Относительная единица, рассчитываемая от высоты экрана"},{"letter":"E","text":"Специальная единица, зависящая от длины контента"}],"correct":"D","explanation":"vh — относительная единица измерения, где 1vh равен 1% от высоты видимой области окна браузера (viewport height)."},{"n":31,"question":"Что такое breakpoint в responsive-дизайне:","options":[{"letter":"A","text":"Специальный метод, работающий как функция JavaScript"},{"letter":"B","text":"Обозначение для выявления ошибок в CSS"},{"letter":"C","text":"Тип HTML-тега для изменения структуры"},{"letter":"D","text":"Точка, при которой меняются стили в зависимости от размера экрана"},{"letter":"E","text":"Технический показатель размера файла"}],"correct":"D","explanation":"Breakpoint — это значение ширины экрана, при достижении которого срабатывает media query и стили страницы меняются для нового диапазона размеров."},{"n":32,"question":"Назначение свойства flex-wrap: wrap:","options":[{"letter":"A","text":"Удаляет элементы из контейнера"},{"letter":"B","text":"Удерживает все элементы в одной строке"},{"letter":"C","text":"Изменяет цвет элементов"},{"letter":"D","text":"Переносит элементы на следующую строку при необходимости"},{"letter":"E","text":"Изменяет высоту элементов"}],"correct":"D","explanation":"flex-wrap: wrap разрешает flex-элементам переноситься на новую строку, если они не помещаются по ширине контейнера в одну линию."},{"n":33,"question":"Наиболее правильная HTML-структура для navigation bar:","options":[{"letter":"A","text":"<div><p>link</p></div> используется для простых текстовых ссылок"},{"letter":"B","text":"<span><a></a></span> используется только для inline-элементов"},{"letter":"C","text":"<section><img></section> используется для графических элементов"},{"letter":"D","text":"<header><div></div></header> используется как общий контейнер"},{"letter":"E","text":"<nav><ul><li><a></a></li></ul></nav> является правильной структурой для навигации"}],"correct":"E","explanation":"Семантически правильная структура навигации — обёртка <nav>, содержащая список <ul> с пунктами <li>, внутри которых находятся ссылки <a>."},{"n":34,"question":"Когда чаще всего используется hamburger menu:","options":[{"letter":"A","text":"Для отображения полного меню на больших desktop-экранах"},{"letter":"B","text":"Является элементом, работающим только на стороне сервера"},{"letter":"C","text":"Используется при печати страницы"},{"letter":"D","text":"Применяется для компактного отображения меню на маленьких экранах"},{"letter":"E","text":"Используется только при отсутствии CSS"}],"correct":"D","explanation":"Hamburger-меню (значок из трёх линий) используется для компактного скрытия основного меню на маленьких экранах, разворачиваясь по нажатию."},{"n":35,"question":"Цель использования min-width:","options":[{"letter":"A","text":"Ограничивает максимальную ширину элемента"},{"letter":"B","text":"Управляет высотой элемента"},{"letter":"C","text":"Изменяет цвет и визуальный стиль"},{"letter":"D","text":"Определяет минимальную ширину элемента и ограничивает его сжатие"},{"letter":"E","text":"Добавляет анимации"}],"correct":"D","explanation":"min-width задаёт нижнюю границу ширины элемента — он не сможет сжаться меньше указанного значения, даже если контейнер уменьшается."},{"n":36,"question":"Что означает grid-template-columns: repeat(3, 1fr):","options":[{"letter":"A","text":"Создает несколько колонок шириной по 3 пикселя"},{"letter":"B","text":"Определяет структуру с одной колонкой"},{"letter":"C","text":"Создает сетку из трех равных по ширине колонок"},{"letter":"D","text":"Используется для создания трех строк"},{"letter":"E","text":"Удаляет все колонки"}],"correct":"C","explanation":"repeat(3, 1fr) — сокращённая запись, создающая три колонки одинаковой ширины (по 1 доле свободного пространства каждая) в CSS Grid."},{"n":37,"question":"Особенность sticky navigation:","options":[{"letter":"A","text":"Работает как absolute и не фиксируется"},{"letter":"B","text":"Полностью исчезает при прокрутке"},{"letter":"C","text":"Полностью фиксируется, как fixed"},{"letter":"D","text":"Фиксируется при достижении определенной точки и далее не двигается"},{"letter":"E","text":"Является устаревшим методом"}],"correct":"D","explanation":"Sticky-навигация (position: sticky) ведёт себя как обычный элемент потока, пока не достигнет заданной точки прокрутки, после чего фиксируется на экране."},{"n":38,"question":"Как записывается mobile-first media query:","options":[{"letter":"A","text":"Используется max-width и адаптация под маленькие экраны"},{"letter":"B","text":"Управляется только через JavaScript"},{"letter":"C","text":"Реализуется только через HTML"},{"letter":"D","text":"Используется min-width и адаптация под большие экраны"},{"letter":"E","text":"Записывается только через inline-стили"}],"correct":"D","explanation":"В mobile-first подходе базовые стили пишутся для мобильных экранов, а media query с min-width добавляют/переопределяют стили для больших экранов."},{"n":39,"question":"Что делает overflow-x: auto:","options":[{"letter":"A","text":"Полностью скрывает контент"},{"letter":"B","text":"Управляет высотой элемента"},{"letter":"C","text":"Отключает прокрутку"},{"letter":"D","text":"Добавляет горизонтальную прокрутку при необходимости"},{"letter":"E","text":"Изменяет цвет элемента"}],"correct":"D","explanation":"overflow-x: auto добавляет горизонтальную полосу прокрутки только тогда, когда содержимое действительно не вмещается по ширине контейнера."},{"n":40,"question":"Основная цель адаптивной навигации:","options":[{"letter":"A","text":"Используется только для уменьшения размера кода"},{"letter":"B","text":"Удаляет необходимость использования JavaScript"},{"letter":"C","text":"Используется только для улучшения SEO"},{"letter":"D","text":"Применяется только для визуального оформления"},{"letter":"E","text":"Обеспечивает удобную навигацию на различных устройствах"}],"correct":"E","explanation":"Адаптивная навигация подстраивается под разные устройства (desktop, планшет, мобильный), обеспечивая пользователю удобный доступ к разделам сайта на любом экране."}]},{"variant":2,"questions":[{"n":1,"question":"Как правильно объявить переменную в JavaScript?","options":[{"letter":"A","text":"let x = 10;"},{"letter":"B","text":"variable x = 10;"},{"letter":"C","text":"define x = 10;"},{"letter":"D","text":"int x := 10;"},{"letter":"E","text":"var: x = 10;"}],"correct":"A","explanation":"В современном JavaScript переменные объявляются ключевыми словами let, const или var с последующим присваиванием значения: let x = 10;."},{"n":2,"question":"Что относится к типу \"string\" в JavaScript?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"\"Hello World\""},{"letter":"C","text":"null"},{"letter":"D","text":"undefined"},{"letter":"E","text":"12345"}],"correct":"B","explanation":"Тип string в JavaScript представляет текстовые данные, заключённые в кавычки: \"Hello World\" — это строка."},{"n":3,"question":"Каков результат typeof null?","options":[{"letter":"A","text":"object"},{"letter":"B","text":"null"},{"letter":"C","text":"string"},{"letter":"D","text":"boolean"},{"letter":"E","text":"undefined"}],"correct":"A","explanation":"typeof null возвращает \"object\" — это известная историческая особенность (баг) JavaScript, сохранённая для обратной совместимости."},{"n":4,"question":"Какой оператор проверяет равенство и тип одновременно?","options":[{"letter":"A","text":"="},{"letter":"B","text":"=="},{"letter":"C","text":"==="},{"letter":"D","text":"!="},{"letter":"E","text":"<>"}],"correct":"C","explanation":"Оператор === (строгое равенство) сравнивает значения без приведения типов — равенство считается истинным только если совпадают и значение, и тип данных."},{"n":5,"question":"Что в JavaScript является значением false (falsy)?","options":[{"letter":"A","text":"\"0\""},{"letter":"B","text":"[]"},{"letter":"C","text":"{}"},{"letter":"D","text":"0"},{"letter":"E","text":"\"false\""}],"correct":"D","explanation":"В JavaScript к falsy-значениям относятся: 0, \"\", null, undefined, NaN и false. Число 0 — falsy, в отличие от строки \"0\" или пустых [] и {}, которые truthy."},{"n":6,"question":"В чем разница между let и var?","options":[{"letter":"A","text":"let имеет блочную область видимости"},{"letter":"B","text":"var работает только внутри функции"},{"letter":"C","text":"var работает только в блоке"},{"letter":"D","text":"let работает только глобально"},{"letter":"E","text":"let используется только с const"}],"correct":"A","explanation":"let имеет блочную область видимости (доступна только внутри {}), а var — функциональную, что часто приводит к неожиданному поведению при использовании var в циклах и условиях."},{"n":7,"question":"Как объявляется массив в JavaScript?","options":[{"letter":"A","text":"array = {}"},{"letter":"B","text":"arr = <>"},{"letter":"C","text":"let arr = []"},{"letter":"D","text":"list = ()"},{"letter":"E","text":"array = set()"}],"correct":"C","explanation":"Массив объявляется с помощью квадратных скобок: let arr = [];. Это создаёт пустой массив, готовый для добавления элементов."},{"n":8,"question":"Когда появляется undefined?","options":[{"letter":"A","text":"Когда переменная является строкой"},{"letter":"B","text":"Когда переменной не присвоено значение"},{"letter":"C","text":"Когда переменная равна null"},{"letter":"D","text":"Когда переменная булевая"},{"letter":"E","text":"Когда переменная является числом"}],"correct":"B","explanation":"undefined появляется, когда переменной объявлена, но не присвоено значение — JavaScript автоматически даёт ей это значение по умолчанию."},{"n":9,"question":"Что такое NaN?","options":[{"letter":"A","text":"Not a Name"},{"letter":"B","text":"Not a Number"},{"letter":"C","text":"Negative and Null"},{"letter":"D","text":"Null and Number"},{"letter":"E","text":"New assigned Number"}],"correct":"B","explanation":"NaN — сокращение от \"Not a Number\" (не число). Это специальное значение, возвращаемое при невозможных математических операциях, например 0/0 или parseInt(\"abc\")."},{"n":10,"question":"Верное утверждение о переменной const:","options":[{"letter":"A","text":"Можно изменить"},{"letter":"B","text":"Автоматически становится числом"},{"letter":"C","text":"Можно переобъявить"},{"letter":"D","text":"Только внутри функции"},{"letter":"E","text":"Значение не изменяется"}],"correct":"E","explanation":"Переменная, объявленная через const, не может быть переприсвоена после инициализации — попытка изменить её значение вызовет ошибку."},{"n":11,"question":"Какой оператор является условным в JavaScript?","options":[{"letter":"A","text":"if"},{"letter":"B","text":"loop"},{"letter":"C","text":"repeat"},{"letter":"D","text":"while"},{"letter":"E","text":"switcher"}],"correct":"A","explanation":"if — это ключевое слово условного оператора в JavaScript, выполняющее блок кода только при истинности заданного условия."},{"n":12,"question":"Блок, который выполняется, если условие не выполнено:","options":[{"letter":"A","text":"else"},{"letter":"B","text":"if"},{"letter":"C","text":"else if"},{"letter":"D","text":"condition"},{"letter":"E","text":"else if else"}],"correct":"A","explanation":"Блок else выполняется только тогда, когда условие в предшествующем if оказалось ложным (false)."},{"n":13,"question":"Когда останавливается цикл while?","options":[{"letter":"A","text":"Когда переменная удаляется"},{"letter":"B","text":"Когда условие становится false"},{"letter":"C","text":"Когда код заканчивается"},{"letter":"D","text":"Когда массив заканчивается"},{"letter":"E","text":"Когда вызывается функция"}],"correct":"B","explanation":"Цикл while проверяет условие перед каждой итерацией и останавливается, как только условие становится false."},{"n":14,"question":"Правильный синтаксис цикла for:","options":[{"letter":"A","text":"for(i<10;i++)"},{"letter":"B","text":"for(let i=0; i<10; i++)"},{"letter":"C","text":"loop(i=0;i<10;i++)"},{"letter":"D","text":"for i=0 to 10"},{"letter":"E","text":"for(i=0;i<10)"}],"correct":"B","explanation":"Корректный синтаксис for включает три части в круглых скобках через точку с запятой: for(let i=0; i<10; i++) { } — инициализация, условие, шаг."},{"n":15,"question":"Что делает оператор break?","options":[{"letter":"A","text":"Продолжает выполнение кода"},{"letter":"B","text":"Запускает цикл"},{"letter":"C","text":"Удаляет переменную"},{"letter":"D","text":"Останавливает цикл"},{"letter":"E","text":"Вызывает функцию"}],"correct":"D","explanation":"Оператор break немедленно прерывает выполнение текущего цикла (или switch), передавая управление коду после него."},{"n":16,"question":"Оператор continue:","options":[{"letter":"A","text":"Завершает цикл"},{"letter":"B","text":"Переходит к следующей итерации"},{"letter":"C","text":"Удаляет переменную"},{"letter":"D","text":"Останавливает выполнение кода"},{"letter":"E","text":"Закрывает функцию"}],"correct":"B","explanation":"continue не завершает цикл целиком, а пропускает оставшуюся часть текущей итерации и переходит к следующей."},{"n":17,"question":"default в switch:","options":[{"letter":"A","text":"Объявление переменной"},{"letter":"B","text":"Написание функции"},{"letter":"C","text":"Выполняется, если ни один case не подошел"},{"letter":"D","text":"Создание массива"},{"letter":"E","text":"Создание цикла"}],"correct":"C","explanation":"Блок default в switch выполняется, если значение выражения не совпало ни с одним из указанных case — это аналог else в условных конструкциях."},{"n":18,"question":"Особенность do...while:","options":[{"letter":"A","text":"Никогда не выполняется"},{"letter":"B","text":"Обязательно выполняется хотя бы один раз"},{"letter":"C","text":"Используется только для массивов"},{"letter":"D","text":"Условие проверяется заранее"},{"letter":"E","text":"Несколько условий"}],"correct":"B","explanation":"Цикл do...while проверяет условие после выполнения тела, поэтому тело гарантированно выполняется хотя бы один раз, независимо от условия."},{"n":19,"question":"Определение функции:","options":[{"letter":"A","text":"define myFunc()"},{"letter":"B","text":"function myFunc()"},{"letter":"C","text":"method myFunc()"},{"letter":"D","text":"func myFunc()"},{"letter":"E","text":"function:myFunc()"}],"correct":"B","explanation":"Функция объявляется ключевым словом function, после которого идёт имя и список параметров в скобках: function myFunc() { }."},{"n":20,"question":"Arrow function:","options":[{"letter":"A","text":"() => {}"},{"letter":"B","text":"func => ()"},{"letter":"C","text":"function => ()"},{"letter":"D","text":"-> ()"},{"letter":"E","text":"=> function()"}],"correct":"A","explanation":"Стрелочная функция (arrow function) записывается как список параметров, символ => и тело: () => {}. Это компактный синтаксис функций, появившийся в ES6."},{"n":21,"question":"Вызов функции:","options":[{"letter":"A","text":"test:function()"},{"letter":"B","text":"call test"},{"letter":"C","text":"test()"},{"letter":"D","text":"function test"},{"letter":"E","text":"test = function"}],"correct":"C","explanation":"Чтобы вызвать функцию, после её имени ставятся круглые скобки (с аргументами или без): test();. Без скобок это просто ссылка на саму функцию."},{"n":22,"question":"Оператор return:","options":[{"letter":"A","text":"Повторяет код"},{"letter":"B","text":"Продолжает выполнение функции"},{"letter":"C","text":"Возвращает значение"},{"letter":"D","text":"Удаляет переменную"},{"letter":"E","text":"Запускает цикл"}],"correct":"C","explanation":"Оператор return завершает выполнение функции и передаёт указанное значение обратно в точку вызова."},{"n":23,"question":"addEventListener:","options":[{"letter":"A","text":"Создает HTML"},{"letter":"B","text":"Изменяет CSS"},{"letter":"C","text":"Обрабатывает события"},{"letter":"D","text":"Объявляет переменную"},{"letter":"E","text":"Читает файл"}],"correct":"C","explanation":"addEventListener — метод DOM, который назначает функцию-обработчик для реакции на конкретное событие (клик, ввод, загрузка и т.д.) у элемента."},{"n":24,"question":"Событие click:","options":[{"letter":"A","text":"При нажатии клавиши"},{"letter":"B","text":"При прокрутке"},{"letter":"C","text":"При движении мыши"},{"letter":"D","text":"При нажатии на элемент"},{"letter":"E","text":"При загрузке страницы"}],"correct":"D","explanation":"Событие click срабатывает в момент, когда пользователь нажимает на элемент (мышью или касанием на сенсорном экране)."},{"n":25,"question":"Что такое DOM?","options":[{"letter":"A","text":"Data Object Model"},{"letter":"B","text":"Document Object Model"},{"letter":"C","text":"Dynamic Object Method"},{"letter":"D","text":"Data Oriented Map"},{"letter":"E","text":"Document Oriented Module"}],"correct":"B","explanation":"DOM расшифровывается как Document Object Model — программное представление HTML-документа в виде древовидной структуры объектов."},{"n":26,"question":"Как получить доступ к свойству объекта?","options":[{"letter":"A","text":"obj->prop"},{"letter":"B","text":"obj.prop"},{"letter":"C","text":"obj::prop"},{"letter":"D","text":"obj:prop"},{"letter":"E","text":"obj[prop()]"}],"correct":"B","explanation":"Точечная нотация obj.prop — стандартный способ обращения к свойству объекта по его известному имени."},{"n":27,"question":"Как получить свойство объекта динамически?","options":[{"letter":"A","text":"obj.prop"},{"letter":"B","text":"obj[\"prop\"]"},{"letter":"C","text":"obj:prop"},{"letter":"D","text":"obj->prop"},{"letter":"E","text":"obj::prop"}],"correct":"B","explanation":"Когда имя свойства неизвестно заранее или хранится в переменной, используется скобочная нотация: obj[\"prop\"] или obj[variableName]."},{"n":28,"question":"На какой структуре основан формат JSON?","options":[{"letter":"A","text":"Синтаксис HTML"},{"letter":"B","text":"Правила CSS"},{"letter":"C","text":"Пары ключ-значение"},{"letter":"D","text":"Бинарная структура"},{"letter":"E","text":"Набор функций"}],"correct":"C","explanation":"Формат JSON основан на парах ключ-значение, аналогичных объектам JavaScript: {\"key\": \"value\"}."},{"n":29,"question":"Что делает метод JSON.parse()?","options":[{"letter":"A","text":"Преобразует объект в строку"},{"letter":"B","text":"Удаляет переменную"},{"letter":"C","text":"Создает HTML-код"},{"letter":"D","text":"Преобразует JSON-текст в объект"},{"letter":"E","text":"Добавляет CSS-стили"}],"correct":"D","explanation":"JSON.parse() принимает строку в формате JSON и преобразует её в реальный JavaScript-объект, с которым можно работать в коде."},{"n":30,"question":"Что делает JSON.stringify()?","options":[{"letter":"A","text":"Преобразует JSON в массив"},{"letter":"B","text":"Преобразует в функцию"},{"letter":"C","text":"Преобразует объект в строку в формате JSON"},{"letter":"D","text":"Создает DOM-элемент"},{"letter":"E","text":"Преобразует в число"}],"correct":"C","explanation":"JSON.stringify() выполняет обратную операцию — превращает JavaScript-объект в текстовую строку формата JSON, удобную для передачи или хранения."},{"n":31,"question":"Когда происходит событие submit у формы?","options":[{"letter":"A","text":"При прокрутке"},{"letter":"B","text":"При нажатии клавиши"},{"letter":"C","text":"При закрытии страницы"},{"letter":"D","text":"При движении курсора"},{"letter":"E","text":"При отправке формы"}],"correct":"E","explanation":"Событие submit у формы срабатывает в момент её отправки — например, при нажатии кнопки типа submit внутри <form>."},{"n":32,"question":"Для чего используется preventDefault()?","options":[{"letter":"A","text":"Изменяет HTML-структуру"},{"letter":"B","text":"Удаляет CSS"},{"letter":"C","text":"Сохраняет переменную"},{"letter":"D","text":"Останавливает действие по умолчанию"},{"letter":"E","text":"Выполняет API-запрос"}],"correct":"D","explanation":"preventDefault() отменяет стандартное действие браузера для данного события — например, отправку формы или переход по ссылке."},{"n":33,"question":"Что возвращает event.target?","options":[{"letter":"A","text":"Все элементы"},{"letter":"B","text":"DOM-дерево"},{"letter":"C","text":"Конкретный элемент, на котором произошло событие"},{"letter":"D","text":"CSS-стиль"},{"letter":"E","text":"Функцию"}],"correct":"C","explanation":"event.target — свойство объекта события, которое содержит ссылку на конкретный DOM-элемент, на котором это событие фактически произошло."},{"n":34,"question":"Что делает метод classList.add()?","options":[{"letter":"A","text":"Удаляет класс"},{"letter":"B","text":"Удаляет DOM-элемент"},{"letter":"C","text":"Добавляет переменную"},{"letter":"D","text":"Вызывает функцию"},{"letter":"E","text":"Добавляет класс"}],"correct":"E","explanation":"classList.add() добавляет указанный CSS-класс к элементу, не затрагивая уже существующие классы."},{"n":35,"question":"Что делает метод classList.remove()?","options":[{"letter":"A","text":"Удаляет элемент"},{"letter":"B","text":"Создает CSS"},{"letter":"C","text":"Изменяет HTML"},{"letter":"D","text":"Добавляет атрибут"},{"letter":"E","text":"Удаляет класс"}],"correct":"E","explanation":"classList.remove() удаляет указанный класс из списка классов элемента, если он там присутствует."},{"n":36,"question":"Как определяется объект в JavaScript?","options":[{"letter":"A","text":"let obj = []"},{"letter":"B","text":"let obj = ()"},{"letter":"C","text":"let obj = <>"},{"letter":"D","text":"let obj = newArray()"},{"letter":"E","text":"let obj = {}"}],"correct":"E","explanation":"Объект в JavaScript создаётся с помощью фигурных скобок: let obj = {};. Это создаёт пустой объект, в который можно добавлять свойства."},{"n":37,"question":"Какой метод используется для получения DOM-элемента?","options":[{"letter":"A","text":"findElement()"},{"letter":"B","text":"getNode()"},{"letter":"C","text":"select()"},{"letter":"D","text":"query()"},{"letter":"E","text":"getElementById()"}],"correct":"E","explanation":"getElementById() — классический метод поиска элемента в DOM по его уникальному атрибуту id, возвращающий ровно один элемент или null."},{"n":38,"question":"Что делает querySelector?","options":[{"letter":"A","text":"Выбирает только id"},{"letter":"B","text":"Выбирает только class"},{"letter":"C","text":"Выбирает только тег"},{"letter":"D","text":"Возвращает все элементы"},{"letter":"E","text":"Находит элемент по CSS-селектору"}],"correct":"E","explanation":"querySelector находит и возвращает первый элемент, соответствующий указанному CSS-селектору (по тегу, классу, id или их комбинации)."},{"n":39,"question":"Для чего используется innerHTML?","options":[{"letter":"A","text":"Изменяет CSS"},{"letter":"B","text":"Сохраняет переменную"},{"letter":"C","text":"Читает файл"},{"letter":"D","text":"Отправляет запрос на сервер"},{"letter":"E","text":"Изменяет HTML-содержимое"}],"correct":"E","explanation":"innerHTML позволяет читать или полностью заменять HTML-содержимое внутри элемента, включая вложенные теги."},{"n":40,"question":"Свойство value относится к какому элементу?","options":[{"letter":"A","text":"div"},{"letter":"B","text":"span"},{"letter":"C","text":"body"},{"letter":"D","text":"script"},{"letter":"E","text":"input"}],"correct":"E","explanation":"Свойство value хранит текущее введённое значение и относится к элементам формы — в первую очередь к <input>, а также к <textarea> и <select>."}]},{"variant":3,"questions":[{"n":1,"question":"Выберите вариант, правильно описывающий основное различие между innerText и innerHTML:","options":[{"letter":"A","text":"Свойство innerText предназначено для управления CSS-стилями и не связано с HTML-структурой"},{"letter":"B","text":"Свойство innerHTML полностью считывает HTML-код внутри элемента и позволяет его изменять"},{"letter":"C","text":"innerText и innerHTML работают одинаково и не имеют различий"},{"letter":"D","text":"innerHTML обрабатывает только простой текст и игнорирует HTML-теги"},{"letter":"E","text":"innerText полностью обрабатывает HTML-структуру и интерпретирует теги"}],"correct":"B","explanation":"innerHTML возвращает и позволяет изменять полное HTML-содержимое элемента, включая теги, тогда как innerText работает только с видимым текстом без разметки."},{"n":2,"question":"Определите основную цель метода setAttribute:","options":[{"letter":"A","text":"Используется для добавления нового атрибута к HTML-элементу или изменения значения существующего"},{"letter":"B","text":"Применяется как функция для динамического изменения CSS-стилей"},{"letter":"C","text":"Является механизмом для хранения переменных JavaScript"},{"letter":"D","text":"Используется для полного удаления элементов из DOM"},{"letter":"E","text":"Применяется для определения и выполнения новых функций"}],"correct":"A","explanation":"setAttribute(name, value) устанавливает значение указанного атрибута элемента — создаёт новый атрибут, если его не было, либо обновляет существующий."},{"n":3,"question":"Что возвращает метод getAttribute:","options":[{"letter":"A","text":"Возвращает полный DOM-объект со всеми свойствами элемента"},{"letter":"B","text":"Возвращает значение указанного атрибута в виде строки (string)"},{"letter":"C","text":"Возвращает текущие значения CSS-стилей"},{"letter":"D","text":"Возвращает JavaScript-функцию"},{"letter":"E","text":"Возвращает массив значений"}],"correct":"B","explanation":"getAttribute(name) возвращает значение атрибута элемента в виде строки или null, если такого атрибута нет."},{"n":4,"question":"Определите функцию метода createElement():","options":[{"letter":"A","text":"Используется для объявления новой переменной в JavaScript"},{"letter":"B","text":"Применяется для полного удаления элементов из HTML-документа"},{"letter":"C","text":"Позволяет динамически создавать новый HTML-элемент в DOM"},{"letter":"D","text":"Автоматически генерирует CSS-файлы"},{"letter":"E","text":"Используется для отправки запросов к внешним API"}],"correct":"C","explanation":"createElement(tagName) создаёт новый, пока не подключённый к документу DOM-узел заданного тега — его нужно дополнительно вставить в дерево, например через appendChild."},{"n":5,"question":"Основная функция метода appendChild():","options":[{"letter":"A","text":"Изменяет стиль элемента и добавляет новые CSS-свойства"},{"letter":"B","text":"Добавляет новый DOM-элемент в конец выбранного элемента"},{"letter":"C","text":"Объединяет переменные и создает новое значение"},{"letter":"D","text":"Вызывает определенную функцию"},{"letter":"E","text":"Полностью удаляет элемент"}],"correct":"B","explanation":"appendChild() вставляет переданный узел последним дочерним элементом внутрь элемента, на котором метод вызван."},{"n":6,"question":"Что делает метод removeChild():","options":[{"letter":"A","text":"Изменяет CSS-свойства элемента"},{"letter":"B","text":"Удаляет указанный дочерний элемент"},{"letter":"C","text":"Используется для удаления переменных"},{"letter":"D","text":"Автоматически перестраивает HTML-структуру"},{"letter":"E","text":"Добавляет новый класс"}],"correct":"B","explanation":"removeChild(node) удаляет указанный дочерний узел из родительского элемента, на котором вызван метод."},{"n":7,"question":"Какова основная цель валидации формы:","options":[{"letter":"A","text":"Уменьшение объема HTML-кода"},{"letter":"B","text":"Проверка корректности данных, введенных пользователем"},{"letter":"C","text":"Автоматическое улучшение CSS-стилей"},{"letter":"D","text":"Установление связи с сервером через API"},{"letter":"E","text":"Управление процессом сохранения файлов"}],"correct":"B","explanation":"Валидация формы проверяет, что введённые пользователем данные соответствуют ожидаемому формату и требованиям, прежде чем форма будет отправлена."},{"n":8,"question":"Определите функцию атрибута required:","options":[{"letter":"A","text":"Автоматически определяет переменные"},{"letter":"B","text":"Требует обязательного заполнения поля формы"},{"letter":"C","text":"Используется для добавления CSS-стилей"},{"letter":"D","text":"Позволяет динамически изменять DOM"},{"letter":"E","text":"Запускает API-запрос"}],"correct":"B","explanation":"Атрибут required делает поле формы обязательным для заполнения — браузер не даст отправить форму, пока оно пустое."},{"n":9,"question":"Основная функция атрибута pattern:","options":[{"letter":"A","text":"Определяет структуру HTML-тегов"},{"letter":"B","text":"Проверяет введенное значение с помощью регулярного выражения"},{"letter":"C","text":"Используется для управления CSS-стилями"},{"letter":"D","text":"Применяется для определения функций JavaScript"},{"letter":"E","text":"Используется для вызова API"}],"correct":"B","explanation":"Атрибут pattern задаёт регулярное выражение, с которым должно совпадать введённое значение поля, чтобы форма прошла валидацию."},{"n":10,"question":"Какую проверку выполняет input type=\"email\":","options":[{"letter":"A","text":"Проверяет числовые значения"},{"letter":"B","text":"Проверяет соответствие формату email"},{"letter":"C","text":"Проверяет корректность URL"},{"letter":"D","text":"Проверяет структуру JSON"},{"letter":"E","text":"Проверяет CSS-стили"}],"correct":"B","explanation":"input type=\"email\" встроенно проверяет, что введённый текст соответствует формату электронной почты (наличие @, домена и т.п.)."},{"n":11,"question":"Выберите правильный способ регистрации события в JavaScript:","options":[{"letter":"A","text":"Метод addClick() является основным способом управления событиями"},{"letter":"B","text":"Функция listen() автоматически отслеживает все события"},{"letter":"C","text":"Метод addEventListener() позволяет назначить конкретное событие элементу"},{"letter":"D","text":"onClick() используется только для изменения CSS"},{"letter":"E","text":"clickEvent() обрабатывает все события сразу"}],"correct":"C","explanation":"addEventListener() позволяет назначить конкретный обработчик для конкретного типа события на элементе, причём можно добавить несколько обработчиков одного события."},{"n":12,"question":"Когда срабатывает событие onchange:","options":[{"letter":"A","text":"Сразу при нажатии клавиши"},{"letter":"B","text":"Когда значение элемента изменилось и он потерял фокус"},{"letter":"C","text":"При полной загрузке страницы"},{"letter":"D","text":"Во время прокрутки"},{"letter":"E","text":"При каждом движении курсора"}],"correct":"B","explanation":"Событие change срабатывает, когда значение поля было изменено пользователем и поле потеряло фокус (в отличие от input, которое срабатывает на каждое изменение сразу)."},{"n":13,"question":"Определите характеристику события keydown:","options":[{"letter":"A","text":"Работает только при нажатии кнопки мыши"},{"letter":"B","text":"Срабатывает в момент нажатия клавиши"},{"letter":"C","text":"Выполняется только при прокрутке"},{"letter":"D","text":"Вызывается при изменении CSS"},{"letter":"E","text":"Работает только при отправке формы"}],"correct":"B","explanation":"keydown срабатывает в момент физического нажатия клавиши, до появления символа на экране (в отличие от keyup, который срабатывает при отпускании)."},{"n":14,"question":"Для чего используется localStorage:","options":[{"letter":"A","text":"Для полного изменения HTML-структуры"},{"letter":"B","text":"Позволяет хранить данные в браузере длительное время"},{"letter":"C","text":"Используется только для хранения CSS"},{"letter":"D","text":"Необходим для выполнения API-запросов"},{"letter":"E","text":"Применяется для создания DOM-элементов"}],"correct":"B","explanation":"localStorage позволяет сохранять данные в браузере пользователя, которые остаются доступны даже после закрытия и повторного открытия страницы."},{"n":15,"question":"Что делает метод localStorage.setItem():","options":[{"letter":"A","text":"Создает новую DOM-структуру"},{"letter":"B","text":"Устанавливает CSS-свойства"},{"letter":"C","text":"Сохраняет данные в формате ключ-значение (key-value)"},{"letter":"D","text":"Выполняет API-запрос"},{"letter":"E","text":"Полностью удаляет старые данные"}],"correct":"C","explanation":"localStorage.setItem(key, value) сохраняет данные в виде пары ключ-значение, где оба параметра автоматически приводятся к строке."},{"n":16,"question":"Что возвращает localStorage.getItem():","options":[{"letter":"A","text":"Полную копию HTML-кода"},{"letter":"B","text":"Ранее сохраненное значение в виде строки (string)"},{"letter":"C","text":"Значения CSS"},{"letter":"D","text":"DOM-объект"},{"letter":"E","text":"Функцию"}],"correct":"B","explanation":"localStorage.getItem(key) возвращает ранее сохранённое значение по указанному ключу в виде строки, либо null, если ключ не найден."},{"n":17,"question":"Что делает метод localStorage.clear():","options":[{"letter":"A","text":"Удаляет только один элемент"},{"letter":"B","text":"Удаляет все сохраненные данные в браузере"},{"letter":"C","text":"Изменяет CSS-стили"},{"letter":"D","text":"Перестраивает DOM"},{"letter":"E","text":"Добавляет API"}],"correct":"B","explanation":"localStorage.clear() полностью очищает хранилище — удаляет абсолютно все сохранённые пары ключ-значение для текущего домена."},{"n":18,"question":"Правильно опишите разницу между null и undefined:","options":[{"letter":"A","text":"undefined — переменной не присвоено значение, а null — намеренно заданное пустое значение"},{"letter":"B","text":"Они полностью одинаковы"},{"letter":"C","text":"Оба относятся только к типу string"},{"letter":"D","text":"Оба относятся только к типу number"},{"letter":"E","text":"undefined всегда считается объектом"}],"correct":"A","explanation":"undefined означает, что переменной не присвоено никакого значения, тогда как null — это значение, которое разработчик явно установил как «пустое» или «отсутствующее»."},{"n":19,"question":"Каков результат typeof NaN:","options":[{"letter":"A","text":"Возвращает тип NaN"},{"letter":"B","text":"Определяется как тип number"},{"letter":"C","text":"Относится к string"},{"letter":"D","text":"Определяется как object"},{"letter":"E","text":"Возвращает undefined"}],"correct":"B","explanation":"Несмотря на то что NaN означает «не число», typeof NaN возвращает \"number\" — NaN формально относится к числовому типу данных."},{"n":20,"question":"Каков результат parseInt(\"10px\"):","options":[{"letter":"A","text":"Остается строкой \"10px\""},{"letter":"B","text":"Возвращает 0"},{"letter":"C","text":"Извлекает число и возвращает значение 10"},{"letter":"D","text":"Возвращает NaN"},{"letter":"E","text":"Возвращает undefined"}],"correct":"C","explanation":"parseInt() извлекает из строки начальную числовую часть и игнорирует остальные символы: parseInt(\"10px\") возвращает целое число 10."},{"n":21,"question":"Каков результат parseFloat(\"10.5px\"):","options":[{"letter":"A","text":"Возвращает 0"},{"letter":"B","text":"Возвращает NaN"},{"letter":"C","text":"Извлекает десятичное число и возвращает 10.5"},{"letter":"D","text":"Возвращает строку \"10.5\""},{"letter":"E","text":"Возвращает undefined"}],"correct":"C","explanation":"parseFloat() работает аналогично parseInt(), но извлекает дробное число: parseFloat(\"10.5px\") возвращает 10.5."},{"n":22,"question":"Каков результат isNaN(\"abc\"):","options":[{"letter":"A","text":"Возвращает false"},{"letter":"B","text":"Возвращает true, так как значение не является числом"},{"letter":"C","text":"Возвращает строку \"NaN\""},{"letter":"D","text":"Возвращает undefined"},{"letter":"E","text":"Возвращает 0"}],"correct":"B","explanation":"isNaN(value) проверяет, можно ли значение интерпретировать как число; для строки \"abc\", которая не является числом, функция возвращает true."},{"n":23,"question":"Каков результат Number(\"123\"):","options":[{"letter":"A","text":"Остается строкой \"123\""},{"letter":"B","text":"Преобразуется в число 123"},{"letter":"C","text":"Возвращает NaN"},{"letter":"D","text":"Возвращает undefined"},{"letter":"E","text":"Преобразуется в boolean"}],"correct":"B","explanation":"Number(\"123\") преобразует строку, содержащую корректное числовое представление, в реальное числовое значение 123."},{"n":24,"question":"Каков результат Boolean(\"\"):","options":[{"letter":"A","text":"Возвращает строку \"false\""},{"letter":"B","text":"Возвращает false, так как строка пустая"},{"letter":"C","text":"Возвращает true"},{"letter":"D","text":"Возвращает null"},{"letter":"E","text":"Возвращает undefined"}],"correct":"B","explanation":"Boolean(\"\") возвращает false, так как пустая строка относится к falsy-значениям в JavaScript."},{"n":25,"question":"Каков результат Boolean(\"text\"):","options":[{"letter":"A","text":"Возвращает null"},{"letter":"B","text":"Возвращает true, так как значение существует"},{"letter":"C","text":"Возвращает false"},{"letter":"D","text":"Возвращает 0"},{"letter":"E","text":"Возвращает undefined"}],"correct":"B","explanation":"Boolean(\"text\") возвращает true, так как любая непустая строка считается truthy-значением, независимо от её содержимого."},{"n":26,"question":"Определите, что не является циклом:","options":[{"letter":"A","text":"while — цикл, выполняющийся, пока условие истинно"},{"letter":"B","text":"if — оператор проверки условия, но не цикл"},{"letter":"C","text":"for — цикл с заданным диапазоном"},{"letter":"D","text":"do...while — цикл, выполняющийся минимум один раз"},{"letter":"E","text":"forEach — метод обхода массива"}],"correct":"B","explanation":"if — это условный оператор, который выполняет проверку и ветвление кода, но не выполняет повторяющихся итераций, поэтому циклом не является."},{"n":27,"question":"Где используется метод forEach:","options":[{"letter":"A","text":"В HTML-структуре"},{"letter":"B","text":"Для поэлементной обработки массива"},{"letter":"C","text":"Для управления CSS"},{"letter":"D","text":"В API-запросах"},{"letter":"E","text":"В структуре объектов"}],"correct":"B","explanation":"forEach() используется для последовательной обработки каждого элемента массива, выполняя переданную функцию для каждого из них без создания нового массива."},{"n":28,"question":"Что возвращает метод map():","options":[{"letter":"A","text":"undefined"},{"letter":"B","text":"Новый массив"},{"letter":"C","text":"object"},{"letter":"D","text":"null"},{"letter":"E","text":"boolean"}],"correct":"B","explanation":"map() создаёт и возвращает новый массив, применяя переданную функцию к каждому элементу исходного массива — исходный массив не изменяется."},{"n":29,"question":"Какова функция метода filter():","options":[{"letter":"A","text":"Возвращает одно значение"},{"letter":"B","text":"Создает новый массив с элементами, удовлетворяющими условию"},{"letter":"C","text":"Устанавливает CSS-свойства"},{"letter":"D","text":"Удаляет HTML-элементы"},{"letter":"E","text":"Создает объект"}],"correct":"B","explanation":"filter() возвращает новый массив, содержащий только те элементы исходного массива, для которых функция-условие вернула true."},{"n":30,"question":"Что делает метод reduce():","options":[{"letter":"A","text":"Добавляет CSS-свойства"},{"letter":"B","text":"Объединяет элементы массива в один результат"},{"letter":"C","text":"Создает DOM-элементы"},{"letter":"D","text":"Изменяет HTML-структуру"},{"letter":"E","text":"Удаляет функции"}],"correct":"B","explanation":"reduce() последовательно обрабатывает элементы массива, сводя их к единому результату (например, сумме) с помощью функции-аккумулятора."},{"n":31,"question":"Какова функция метода setTimeout:","options":[{"letter":"A","text":"Выполняет API-запрос"},{"letter":"B","text":"Выполняет код один раз через заданное время"},{"letter":"C","text":"Создает цикл"},{"letter":"D","text":"Изменяет CSS"},{"letter":"E","text":"Удаляет переменную"}],"correct":"B","explanation":"setTimeout(fn, delay) запускает переданную функцию один раз после указанной задержки в миллисекундах."},{"n":32,"question":"Что делает метод setInterval:","options":[{"letter":"A","text":"Выполняется один раз"},{"letter":"B","text":"Повторно выполняет код через заданные интервалы времени"},{"letter":"C","text":"Удаляет функцию"},{"letter":"D","text":"Создает DOM"},{"letter":"E","text":"Изменяет переменную"}],"correct":"B","explanation":"setInterval(fn, delay) запускает переданную функцию повторно через равные промежутки времени, пока не будет вызван clearInterval()."},{"n":33,"question":"Какова функция метода clearInterval:","options":[{"letter":"A","text":"Создает DOM"},{"letter":"B","text":"Останавливает ранее установленный интервал"},{"letter":"C","text":"Удаляет CSS"},{"letter":"D","text":"Добавляет API"},{"letter":"E","text":"Сохраняет переменную"}],"correct":"B","explanation":"clearInterval(id) останавливает ранее запущенный через setInterval повторяющийся таймер, используя идентификатор, возвращённый setInterval."},{"n":34,"question":"Что показывает document.readyState:","options":[{"letter":"A","text":"Показывает ошибки JavaScript"},{"letter":"B","text":"Показывает состояние загрузки документа"},{"letter":"C","text":"Показывает состояние CSS"},{"letter":"D","text":"Показывает HTML-код"},{"letter":"E","text":"Показывает ответ API"}],"correct":"B","explanation":"document.readyState отражает текущую стадию загрузки документа: \"loading\", \"interactive\" или \"complete\"."},{"n":35,"question":"Когда срабатывает событие window.onload:","options":[{"letter":"A","text":"При запуске JavaScript"},{"letter":"B","text":"После полной загрузки всех ресурсов"},{"letter":"C","text":"При загрузке CSS"},{"letter":"D","text":"При вызове API"},{"letter":"E","text":"При изменении DOM"}],"correct":"B","explanation":"window.onload срабатывает только после того, как полностью загружены не только HTML и DOM, но и все внешние ресурсы — изображения, стили, скрипты."},{"n":36,"question":"Что возвращает document.querySelectorAll:","options":[{"letter":"A","text":"string"},{"letter":"B","text":"Коллекцию элементов типа NodeList"},{"letter":"C","text":"object"},{"letter":"D","text":"Один элемент"},{"letter":"E","text":"undefined"}],"correct":"B","explanation":"document.querySelectorAll() возвращает статическую коллекцию NodeList со всеми элементами, соответствующими CSS-селектору, даже если их несколько или ноль."},{"n":37,"question":"Определите разницу между NodeList и Array:","options":[{"letter":"A","text":"NodeList не является полноценным массивом и не поддерживает некоторые методы массива"},{"letter":"B","text":"Полностью одинаковы"},{"letter":"C","text":"Array используется только для DOM"},{"letter":"D","text":"NodeList — это только объект"},{"letter":"E","text":"NodeList — это только функция"}],"correct":"A","explanation":"NodeList не является полноценным массивом — у него отсутствуют многие методы массивов (map, filter и т.п.), хотя его можно перебрать через forEach или преобразовать в массив."},{"n":38,"question":"Что такое event bubbling:","options":[{"letter":"A","text":"Событие полностью удаляется"},{"letter":"B","text":"Событие распространяется от вложенного элемента к родительским"},{"letter":"C","text":"Изменяется CSS"},{"letter":"D","text":"Останавливается функция"},{"letter":"E","text":"Удаляется DOM"}],"correct":"B","explanation":"Event bubbling — механизм, при котором событие, возникшее на вложенном элементе, последовательно «всплывает» вверх через всех его родителей до корня документа."},{"n":39,"question":"Какова функция метода stopPropagation():","options":[{"letter":"A","text":"Изменяет HTML"},{"letter":"B","text":"Останавливает распространение события вверх по DOM"},{"letter":"C","text":"Удаляет CSS"},{"letter":"D","text":"Останавливает API"},{"letter":"E","text":"Удаляет переменную"}],"correct":"B","explanation":"stopPropagation() прерывает дальнейшее распространение (всплытие) события вверх по дереву DOM, не давая родительским обработчикам сработать."},{"n":40,"question":"Когда используется event.preventDefault():","options":[{"letter":"A","text":"При создании DOM"},{"letter":"B","text":"Для предотвращения действия по умолчанию (например, отправки формы)"},{"letter":"C","text":"При добавлении CSS"},{"letter":"D","text":"При объявлении переменной"},{"letter":"E","text":"При вызове API"}],"correct":"B","explanation":"event.preventDefault() отменяет стандартное поведение браузера для события — например, предотвращает реальную отправку формы или переход по ссылке."}]},{"variant":4,"questions":[{"n":1,"question":"Определите основную функцию метода closest():","options":[{"letter":"A","text":"Находит ближайший родительский элемент, соответствующий селектору"},{"letter":"B","text":"Возвращает все элементы документа"},{"letter":"C","text":"Автоматически применяет CSS-стили"},{"letter":"D","text":"Удаляет элементы из DOM"},{"letter":"E","text":"Находит все вложенные элементы одновременно"}],"correct":"A","explanation":"closest(selector) ищет вверх по дереву DOM, начиная с самого элемента, и возвращает первого предка (включая сам элемент), соответствующего селектору."},{"n":2,"question":"Функция метода matches():","options":[{"letter":"A","text":"Проверяет корректность HTML-кода"},{"letter":"B","text":"Определяет, соответствует ли элемент заданному селектору"},{"letter":"C","text":"Проверяет структуру API-ответов"},{"letter":"D","text":"Сравнивает значения переменных"},{"letter":"E","text":"Проверяет CSS-стили"}],"correct":"B","explanation":"matches(selector) проверяет, соответствует ли сам элемент указанному CSS-селектору, возвращая true или false, без поиска по дереву."},{"n":3,"question":"Основное назначение свойства dataset:","options":[{"letter":"A","text":"Полностью изменяет DOM-структуру"},{"letter":"B","text":"Используется для подключения к API"},{"letter":"C","text":"Удаляет HTML-элементы"},{"letter":"D","text":"Управляет CSS-стилями"},{"letter":"E","text":"Позволяет читать и изменять data-атрибуты"}],"correct":"E","explanation":"Свойство dataset предоставляет удобный доступ на чтение и запись ко всем data-* атрибутам элемента как к обычным свойствам объекта."},{"n":4,"question":"Как правильно получить атрибут data-id=\"5\":","options":[{"letter":"A","text":"Через element.id"},{"letter":"B","text":"Через element.getId()"},{"letter":"C","text":"Через element.attr"},{"letter":"D","text":"Через element.dataset.id"},{"letter":"E","text":"Через element.data"}],"correct":"D","explanation":"Атрибут data-id=\"5\" доступен через element.dataset.id — название атрибута без префикса data- становится именем свойства в объекте dataset."},{"n":5,"question":"Разница между input.value и getAttribute(\"value\"):","options":[{"letter":"A","text":"Полностью одинаковы"},{"letter":"B","text":"getAttribute возвращает только числовые значения"},{"letter":"C","text":"value связано только со стилями"},{"letter":"D","text":"getAttribute работает только с DOM"},{"letter":"E","text":"value — текущее значение, getAttribute — начальное значение"}],"correct":"E","explanation":"input.value возвращает текущее, актуальное значение поля (которое пользователь может изменить), а getAttribute(\"value\") — исходное значение, заданное в HTML при загрузке страницы."},{"n":6,"question":"Функция form.reset():","options":[{"letter":"A","text":"Сбрасывает форму к исходному состоянию"},{"letter":"B","text":"Удаляет все CSS-стили"},{"letter":"C","text":"Пересоздает DOM"},{"letter":"D","text":"Удаляет переменные"},{"letter":"E","text":"Отправляет API-запрос"}],"correct":"A","explanation":"form.reset() возвращает все поля формы к их первоначальным значениям, заданным в HTML-атрибутах, как если бы страница только загрузилась."},{"n":7,"question":"Что происходит при нажатии кнопки submit:","options":[{"letter":"A","text":"Автоматически меняются CSS-стили"},{"letter":"B","text":"Полностью удаляются DOM-элементы"},{"letter":"C","text":"Данные формы отправляются на сервер"},{"letter":"D","text":"JavaScript полностью останавливается"},{"letter":"E","text":"Все переменные удаляются"}],"correct":"C","explanation":"При нажатии кнопки submit (без отмены через preventDefault) браузер собирает данные формы и отправляет их на сервер согласно атрибутам action и method."},{"n":8,"question":"Функция атрибута action в HTML form:","options":[{"letter":"A","text":"Подключает CSS"},{"letter":"B","text":"Определяет адрес сервера для отправки формы"},{"letter":"C","text":"Используется для JavaScript"},{"letter":"D","text":"Изменяет DOM"},{"letter":"E","text":"Отключает API"}],"correct":"B","explanation":"Атрибут action в форме указывает URL-адрес сервера, на который будут отправлены введённые данные при сабмите."},{"n":9,"question":"Что означает method=\"POST\":","options":[{"letter":"A","text":"Данные отправляются через URL"},{"letter":"B","text":"Работает так же, как GET"},{"letter":"C","text":"Используется как CSS-метод"},{"letter":"D","text":"Используется как DOM-метод"},{"letter":"E","text":"Данные отправляются в body запроса"}],"correct":"E","explanation":"method=\"POST\" означает, что данные формы передаются в теле HTTP-запроса (body), а не в URL, что подходит для отправки больших объёмов или конфиденциальных данных."},{"n":10,"question":"Особенность метода GET:","options":[{"letter":"A","text":"Данные передаются через URL параметры"},{"letter":"B","text":"Передает данные через body"},{"letter":"C","text":"Работает только с JSON"},{"letter":"D","text":"Передает данные через CSS"},{"letter":"E","text":"Отключает API"}],"correct":"A","explanation":"Метод GET передаёт данные через параметры URL-адреса (после знака ?), что делает их видимыми в адресной строке и ограниченными по длине."},{"n":11,"question":"Функция ключевого слова async:","options":[{"letter":"A","text":"Позволяет создавать асинхронную функцию"},{"letter":"B","text":"Добавляет CSS-стили"},{"letter":"C","text":"Удаляет DOM-элементы"},{"letter":"D","text":"Изменяет HTML"},{"letter":"E","text":"Объявляет переменные"}],"correct":"A","explanation":"Ключевое слово async перед функцией делает её асинхронной — она автоматически возвращает Promise и позволяет использовать внутри await."},{"n":12,"question":"Когда используется await:","options":[{"letter":"A","text":"При работе с DOM"},{"letter":"B","text":"В HTML-коде"},{"letter":"C","text":"Для ожидания результата внутри async-функции"},{"letter":"D","text":"В любом месте вне API"},{"letter":"E","text":"В CSS"}],"correct":"C","explanation":"await используется только внутри async-функций и приостанавливает её выполнение до тех пор, пока Promise не будет выполнен (resolved), не блокируя при этом остальной код."},{"n":13,"question":"Определение Promise:","options":[{"letter":"A","text":"Специальный тип переменной"},{"letter":"B","text":"DOM-элемент"},{"letter":"C","text":"HTML-тег"},{"letter":"D","text":"Объект, представляющий результат асинхронной операции"},{"letter":"E","text":"CSS-функция"}],"correct":"D","explanation":"Promise — это объект, представляющий результат асинхронной операции, который может находиться в одном из трёх состояний: pending, fulfilled или rejected."},{"n":14,"question":"Функция метода then():","options":[{"letter":"A","text":"Обрабатывает результат Promise"},{"letter":"B","text":"Устанавливает CSS"},{"letter":"C","text":"Создает DOM"},{"letter":"D","text":"Удаляет переменные"},{"letter":"E","text":"Обрабатывает ошибки"}],"correct":"A","explanation":"Метод then() регистрирует функцию-обработчик, которая выполнится с результатом Promise после его успешного завершения (resolve)."},{"n":15,"question":"Назначение catch():","options":[{"letter":"A","text":"Удаляет CSS"},{"letter":"B","text":"Обрабатывает ошибки асинхронных операций"},{"letter":"C","text":"Создает DOM"},{"letter":"D","text":"Сохраняет переменные"},{"letter":"E","text":"Изменяет HTML"}],"correct":"B","explanation":"Метод catch() перехватывает и обрабатывает ошибку, если Promise завершился отказом (reject), предотвращая «падение» необработанного исключения."},{"n":16,"question":"Основная функция fetch():","options":[{"letter":"A","text":"Создает HTML"},{"letter":"B","text":"Удаляет DOM"},{"letter":"C","text":"Отправляет HTTP-запрос к серверу"},{"letter":"D","text":"Объявляет переменные"},{"letter":"E","text":"Загружает CSS"}],"correct":"C","explanation":"fetch() — встроенный метод для отправки HTTP-запросов к серверу или API, возвращающий Promise с объектом ответа."},{"n":17,"question":"Что возвращает response.json():","options":[{"letter":"A","text":"Строку"},{"letter":"B","text":"Число"},{"letter":"C","text":"Логическое значение"},{"letter":"D","text":"Преобразует JSON в JavaScript-объект"},{"letter":"E","text":"Неизвестное значение"}],"correct":"D","explanation":"response.json() читает тело HTTP-ответа и парсит его как JSON, возвращая Promise, который разрешается в JavaScript-объект."},{"n":18,"question":"Как работает this в arrow function:","options":[{"letter":"A","text":"Всегда равно window"},{"letter":"B","text":"Возвращает null"},{"letter":"C","text":"Возвращает undefined"},{"letter":"D","text":"Использует значение из внешнего контекста"},{"letter":"E","text":"Создает собственный контекст"}],"correct":"D","explanation":"Стрелочные функции не создают собственный контекст this — они берут this из окружающего (лексического) кода, где функция была определена."},{"n":19,"question":"Что означает ключевое слово this:","options":[{"letter":"A","text":"Значение переменной"},{"letter":"B","text":"CSS-свойство"},{"letter":"C","text":"Текущий объект"},{"letter":"D","text":"HTML-код"},{"letter":"E","text":"Ответ API"}],"correct":"C","explanation":"Ключевое слово this ссылается на объект, в контексте которого выполняется текущий код — обычно на объект, через который вызван метод."},{"n":20,"question":"Функция метода bind():","options":[{"letter":"A","text":"Удаляет DOM"},{"letter":"B","text":"Привязывает значение this к конкретному объекту"},{"letter":"C","text":"Добавляет CSS"},{"letter":"D","text":"Создает HTML"},{"letter":"E","text":"Удаляет переменные"}],"correct":"B","explanation":"bind() создаёт новую функцию с жёстко зафиксированным значением this, которое не изменится независимо от того, как и откуда эта функция будет вызвана впоследствии."},{"n":21,"question":"Основная функция метода call():","options":[{"letter":"A","text":"Используется для установки CSS-свойств"},{"letter":"B","text":"Удаляет DOM-элементы"},{"letter":"C","text":"Изменяет HTML-структуру"},{"letter":"D","text":"Сохраняет переменные"},{"letter":"E","text":"Вызывает функцию с заданным контекстом"}],"correct":"E","explanation":"call(thisArg, ...args) вызывает функцию немедленно, явно задавая значение this и передавая аргументы по отдельности через запятую."},{"n":22,"question":"Особенность метода apply():","options":[{"letter":"A","text":"Изменяет CSS-стили"},{"letter":"B","text":"Создает DOM-элементы"},{"letter":"C","text":"Удаляет HTML-код"},{"letter":"D","text":"Изменяет переменные"},{"letter":"E","text":"Принимает аргументы функции в виде массива"}],"correct":"E","explanation":"apply(thisArg, argsArray) работает как call(), но принимает аргументы функции единым массивом, а не списком через запятую."},{"n":23,"question":"Для чего используется оператор spread (...):","options":[{"letter":"A","text":"Добавляет CSS-свойства"},{"letter":"B","text":"Создает HTML-структуру"},{"letter":"C","text":"Удаляет DOM-элементы"},{"letter":"D","text":"Выполняет API-запросы"},{"letter":"E","text":"Разворачивает элементы массива или объекта"}],"correct":"E","explanation":"Spread-оператор (...) разворачивает (распаковывает) элементы массива или объекта в отдельные значения — например, при передаче аргументов или копировании."},{"n":24,"question":"Для чего используется оператор rest (...):","options":[{"letter":"A","text":"Удаляет CSS-стили"},{"letter":"B","text":"Изменяет HTML-код"},{"letter":"C","text":"Создает DOM-элементы"},{"letter":"D","text":"Отключает API"},{"letter":"E","text":"Собирает оставшиеся аргументы в массив"}],"correct":"E","explanation":"Rest-оператор (...) в параметрах функции, наоборот, собирает все оставшиеся переданные аргументы в единый массив."},{"n":25,"question":"Что означает destructuring:","options":[{"letter":"A","text":"Используется как CSS-метод"},{"letter":"B","text":"Используется как HTML-тег"},{"letter":"C","text":"Процесс удаления DOM-элементов"},{"letter":"D","text":"Удаление переменных"},{"letter":"E","text":"Способ извлечения значений из объекта или массива"}],"correct":"E","explanation":"Деструктуризация (destructuring) — синтаксис, позволяющий извлечь отдельные значения из массива или объекта и присвоить их переменным в одной строке."},{"n":26,"question":"Что делает let {a} = obj:","options":[{"letter":"A","text":"Полностью удаляет объект obj"},{"letter":"B","text":"Устанавливает CSS-стиль"},{"letter":"C","text":"Создает DOM-элемент"},{"letter":"D","text":"Изменяет HTML-структуру"},{"letter":"E","text":"Извлекает значение свойства a из объекта obj"}],"correct":"E","explanation":"let {a} = obj извлекает значение свойства a из объекта obj и записывает его в переменную с тем же именем a."},{"n":27,"question":"Как пишется template string:","options":[{"letter":"A","text":"В двойных кавычках"},{"letter":"B","text":"В одинарных кавычках"},{"letter":"C","text":"Внутри HTML-тега"},{"letter":"D","text":"В скобках"},{"letter":"E","text":"В обратных кавычках"}],"correct":"E","explanation":"Шаблонные строки (template strings) в JavaScript записываются в обратных кавычках (`) и позволяют встраивать выражения через синтаксис ${}."},{"n":28,"question":"Разница между localStorage и sessionStorage:","options":[{"letter":"A","text":"Полностью одинаковы"},{"letter":"B","text":"sessionStorage сохраняется навсегда"},{"letter":"C","text":"localStorage хранится только временно"},{"letter":"D","text":"Оба удаляются одновременно"},{"letter":"E","text":"sessionStorage хранится только в пределах одной сессии"}],"correct":"E","explanation":"Главное отличие: sessionStorage хранит данные только до закрытия вкладки/браузера (в рамках одной сессии), а localStorage сохраняет данные постоянно, без срока действия."},{"n":29,"question":"Что НЕ используется в JSON:","options":[{"letter":"A","text":"string"},{"letter":"B","text":"number"},{"letter":"C","text":"object"},{"letter":"D","text":"array"},{"letter":"E","text":"function"}],"correct":"E","explanation":"Формат JSON поддерживает строки, числа, объекты, массивы, булевы значения и null — функции (function) сериализовать в JSON невозможно."},{"n":30,"question":"Когда срабатывает DOMContentLoaded:","options":[{"letter":"A","text":"После полной загрузки всех ресурсов"},{"letter":"B","text":"После загрузки CSS"},{"letter":"C","text":"После получения API-ответа"},{"letter":"D","text":"После остановки JavaScript"},{"letter":"E","text":"После полной загрузки HTML и готовности DOM"}],"correct":"E","explanation":"DOMContentLoaded срабатывает сразу после того, как HTML полностью загружен и распарсен в DOM, не дожидаясь загрузки изображений, стилей и других внешних ресурсов."},{"n":31,"question":"Функция атрибута defer:","options":[{"letter":"A","text":"Удаляет CSS"},{"letter":"B","text":"Изменяет HTML"},{"letter":"C","text":"Удаляет DOM"},{"letter":"D","text":"Останавливает API"},{"letter":"E","text":"Выполняет JavaScript после загрузки HTML"}],"correct":"E","explanation":"Атрибут defer указывает браузеру выполнить подключённый скрипт только после полной загрузки и разбора HTML-документа, сохраняя при этом порядок выполнения скриптов."},{"n":32,"question":"Особенность атрибута async:","options":[{"letter":"A","text":"Изменяет CSS"},{"letter":"B","text":"Удаляет HTML"},{"letter":"C","text":"Создает DOM"},{"letter":"D","text":"Отключает API"},{"letter":"E","text":"Загружает JS независимо и выполняет сразу после готовности"}],"correct":"E","explanation":"Атрибут async загружает скрипт параллельно с разбором HTML и выполняет его сразу, как только загрузка завершится, без гарантии порядка относительно других скриптов."},{"n":33,"question":"Что такое event delegation:","options":[{"letter":"A","text":"CSS-метод"},{"letter":"B","text":"HTML-тег"},{"letter":"C","text":"Удаление DOM-элементов"},{"letter":"D","text":"API-вызов"},{"letter":"E","text":"Назначение обработчика события родительскому элементу для дочерних"}],"correct":"E","explanation":"Event delegation — техника назначения одного обработчика событий на родительский элемент вместо множества обработчиков на каждый дочерний элемент, с использованием event bubbling."},{"n":34,"question":"Что проверяет метод includes():","options":[{"letter":"A","text":"CSS-свойства"},{"letter":"B","text":"HTML-структуру"},{"letter":"C","text":"DOM-элементы"},{"letter":"D","text":"API-ответ"},{"letter":"E","text":"Наличие элемента в массиве или строке"}],"correct":"E","explanation":"includes() проверяет наличие конкретного значения или подстроки в массиве или строке соответственно, возвращая true или false."},{"n":35,"question":"Функция метода startsWith():","options":[{"letter":"A","text":"Добавляет CSS"},{"letter":"B","text":"Удаляет DOM"},{"letter":"C","text":"Изменяет HTML"},{"letter":"D","text":"Вызывает API"},{"letter":"E","text":"Проверяет, начинается ли строка с указанного значения"}],"correct":"E","explanation":"startsWith() проверяет, начинается ли строка с указанной подстроки, возвращая логическое значение."},{"n":36,"question":"Что проверяет endsWith():","options":[{"letter":"A","text":"CSS-свойства"},{"letter":"B","text":"HTML-структуру"},{"letter":"C","text":"DOM-элементы"},{"letter":"D","text":"API-ответ"},{"letter":"E","text":"Проверяет, заканчивается ли строка указанным значением"}],"correct":"E","explanation":"endsWith() проверяет, заканчивается ли строка указанной подстрокой, возвращая true или false."},{"n":37,"question":"Функция метода trim():","options":[{"letter":"A","text":"Удаляет CSS"},{"letter":"B","text":"Создает DOM"},{"letter":"C","text":"Изменяет HTML"},{"letter":"D","text":"Вызывает API"},{"letter":"E","text":"Удаляет пробелы в строке"}],"correct":"E","explanation":"trim() удаляет пробельные символы с начала и конца строки, не затрагивая пробелы внутри неё."},{"n":38,"question":"Функция метода split():","options":[{"letter":"A","text":"Делит CSS-свойства"},{"letter":"B","text":"Удаляет DOM"},{"letter":"C","text":"Создает HTML"},{"letter":"D","text":"Вызывает API"},{"letter":"E","text":"Разбивает строку на массив"}],"correct":"E","explanation":"split(separator) разбивает строку на массив подстрок по указанному разделителю."},{"n":39,"question":"Что делает метод join():","options":[{"letter":"A","text":"Добавляет CSS"},{"letter":"B","text":"Создает DOM"},{"letter":"C","text":"Удаляет HTML"},{"letter":"D","text":"Вызывает API"},{"letter":"E","text":"Объединяет элементы массива в строку"}],"correct":"E","explanation":"join(separator) выполняет обратную операцию — объединяет все элементы массива в единую строку, вставляя между ними указанный разделитель."},{"n":40,"question":"Основная роль JavaScript:","options":[{"letter":"A","text":"Создание дизайна"},{"letter":"B","text":"Написание HTML"},{"letter":"C","text":"Настройка сервера"},{"letter":"D","text":"Создание CSS-файлов"},{"letter":"E","text":"Добавление интерактивности и поведения"}],"correct":"E","explanation":"Основная роль JavaScript на веб-странице — добавление интерактивности и динамического поведения: обработка событий, изменение DOM, работа с данными, в отличие от HTML (структура) и CSS (внешний вид)."}]},{"variant":5,"questions":[{"n":1,"question":"Выберите вариант, правильно описывающий семантическую структуру HTML-документа:","options":[{"letter":"A","text":"<div> универсальный контейнер для всего контента"},{"letter":"B","text":"<span> определяет основную структуру документа"},{"letter":"C","text":"<section> используется только для стилей"},{"letter":"D","text":"<header>, <main>, <footer> логически разделяют контент"},{"letter":"E","text":"<b> является структурным элементом"}],"correct":"D","explanation":"Семантические теги <header>, <main>, <footer> логически делят содержимое страницы по смыслу, в отличие от неймовых <div> и <span>."},{"n":2,"question":"Что делает метод closest()?","options":[{"letter":"A","text":"Возвращает все элементы"},{"letter":"B","text":"Находит ближайший родительский элемент"},{"letter":"C","text":"Изменяет CSS-стили"},{"letter":"D","text":"Удаляет DOM"},{"letter":"E","text":"Выбирает дочерние элементы"}],"correct":"B","explanation":"closest(selector) находит ближайшего предка элемента (включая сам элемент), соответствующего переданному CSS-селектору."},{"n":3,"question":"Что проверяет метод matches()?","options":[{"letter":"A","text":"HTML-структуру"},{"letter":"B","text":"Значение переменной"},{"letter":"C","text":"API-ответ"},{"letter":"D","text":"Соответствие селектору"},{"letter":"E","text":"CSS-свойства"}],"correct":"D","explanation":"matches(selector) проверяет, соответствует ли элемент указанному CSS-селектору, возвращая булево значение."},{"n":4,"question":"Для чего используется dataset?","options":[{"letter":"A","text":"Хранение CSS"},{"letter":"B","text":"Удаление HTML"},{"letter":"C","text":"Хранение пользовательских данных (data-атрибутов)"},{"letter":"D","text":"Вызов API"},{"letter":"E","text":"Изменение DOM"}],"correct":"C","explanation":"dataset предоставляет удобный способ хранения и доступа к пользовательским data-атрибутам элемента непосредственно из JavaScript."},{"n":5,"question":"Когда происходит повторный рендер компонента в React?","options":[{"letter":"A","text":"Только при изменении DOM"},{"letter":"B","text":"При изменении CSS"},{"letter":"C","text":"При изменении state или props"},{"letter":"D","text":"При вызове useEffect"},{"letter":"E","text":"Всегда автоматически"}],"correct":"C","explanation":"Компонент React перерисовывается (re-render), когда меняется его state или входящие props — это базовый механизм реактивности React."},{"n":6,"question":"Что происходит, если dependency array в useEffect пустой?","options":[{"letter":"A","text":"Выполняется при каждом рендере"},{"letter":"B","text":"Выполняется только один раз"},{"letter":"C","text":"При изменении props"},{"letter":"D","text":"При изменении state"},{"letter":"E","text":"Никогда не выполняется"}],"correct":"B","explanation":"Пустой массив зависимостей [] в useEffect означает, что эффект выполнится только один раз — сразу после первого рендера компонента (аналог componentDidMount)."},{"n":7,"question":"Что происходит, если неправильно использовать key в React?","options":[{"letter":"A","text":"Ломается CSS"},{"letter":"B","text":"Останавливается API"},{"letter":"C","text":"Ошибки в diffing DOM"},{"letter":"D","text":"Удаляется state"},{"letter":"E","text":"Компонент не загружается"}],"correct":"C","explanation":"Неправильный key (например, индекс массива при изменении порядка элементов) приводит к ошибкам в алгоритме сравнения (diffing) Virtual DOM — React может неверно сопоставить старые и новые элементы."},{"n":8,"question":"Является ли useState асинхронным?","options":[{"letter":"A","text":"Полностью синхронный"},{"letter":"B","text":"Только на сервере"},{"letter":"C","text":"Обновляется асинхронно"},{"letter":"D","text":"Только внутри useEffect"},{"letter":"E","text":"Зависит от DOM"}],"correct":"C","explanation":"Обновление состояния через useState происходит асинхронно — React группирует обновления для оптимизации производительности, поэтому новое значение не всегда доступно сразу после вызова setter-функции."},{"n":9,"question":"Что означает immutable props?","options":[{"letter":"A","text":"Props не изменяются"},{"letter":"B","text":"Изменяются только на сервере"},{"letter":"C","text":"Изменяются в useEffect"},{"letter":"D","text":"Можно изменять props"},{"letter":"E","text":"Props всегда JSON"}],"correct":"A","explanation":"Props в React являются неизменяемыми (immutable) — дочерний компонент не должен и не может напрямую изменять props, полученные от родителя."},{"n":10,"question":"Преимущество Virtual DOM:","options":[{"letter":"A","text":"Ускорение CSS"},{"letter":"B","text":"Генерация HTML"},{"letter":"C","text":"Оптимизация рендера"},{"letter":"D","text":"Ускорение API"},{"letter":"E","text":"Обработка JSON"}],"correct":"C","explanation":"Virtual DOM позволяет React сравнивать предыдущее и новое состояние интерфейса в памяти и обновлять реальный DOM только там, где есть отличия, что ускоряет рендеринг."},{"n":11,"question":"Для чего нужен event loop в Node.js?","options":[{"letter":"A","text":"Создание HTML"},{"letter":"B","text":"Обработка CSS"},{"letter":"C","text":"Управление асинхронными операциями"},{"letter":"D","text":"Изменение DOM"},{"letter":"E","text":"Хранение API"}],"correct":"C","explanation":"Event loop в Node.js управляет выполнением асинхронных операций (таймеры, I/O, callbacks), позволяя однопоточному Node.js не блокироваться на долгих операциях."},{"n":12,"question":"Что такое callback hell?","options":[{"letter":"A","text":"Ошибка CSS"},{"letter":"B","text":"Ошибка HTML"},{"letter":"C","text":"Многоуровневые вложенные callback-функции"},{"letter":"D","text":"Ошибка API"},{"letter":"E","text":"Ошибка DOM"}],"correct":"C","explanation":"Callback hell — ситуация, когда множество вложенных друг в друга callback-функций делает асинхронный код труднореализуемым для чтения и поддержки."},{"n":13,"question":"Что такое Promise chaining?","options":[{"letter":"A","text":"Удаление Promise"},{"letter":"B","text":"Цепочка методов then()"},{"letter":"C","text":"Сохранение Promise"},{"letter":"D","text":"Остановка Promise"},{"letter":"E","text":"Загрузка Promise"}],"correct":"B","explanation":"Promise chaining — это последовательное связывание нескольких вызовов .then(), где результат одного передаётся в следующий, упрощая работу с цепочкой асинхронных операций."},{"n":14,"question":"Когда используется async/await?","options":[{"letter":"A","text":"При написании CSS"},{"letter":"B","text":"При создании HTML"},{"letter":"C","text":"Для упрощения асинхронного кода"},{"letter":"D","text":"При изменении DOM"},{"letter":"E","text":"При обработке JSON"}],"correct":"C","explanation":"async/await — синтаксический сахар над Promise, который позволяет писать асинхронный код в линейном, похожем на синхронный стиле, упрощая читаемость."},{"n":15,"question":"Порядок middleware в Express:","options":[{"letter":"A","text":"Случайный"},{"letter":"B","text":"Через CSS"},{"letter":"C","text":"В порядке написания"},{"letter":"D","text":"Через JSON"},{"letter":"E","text":"Через API"}],"correct":"C","explanation":"В Express middleware-функции выполняются строго в том порядке, в котором они были подключены через app.use() или назначены маршруту."},{"n":16,"question":"Назначение JWT:","options":[{"letter":"A","text":"Хранение CSS"},{"letter":"B","text":"Защита HTML"},{"letter":"C","text":"Аутентификация"},{"letter":"D","text":"Защита DOM"},{"letter":"E","text":"Удаление API"}],"correct":"C","explanation":"JWT (JSON Web Token) используется для аутентификации — он позволяет серверу проверить личность пользователя без хранения сессии на сервере."},{"n":17,"question":"Защита от SQL Injection:","options":[{"letter":"A","text":"CSS-фильтр"},{"letter":"B","text":"Prepared statements"},{"letter":"C","text":"HTML-escape"},{"letter":"D","text":"JSON parse"},{"letter":"E","text":"DOM sanitize"}],"correct":"B","explanation":"Prepared statements (подготовленные выражения) отделяют SQL-код от пользовательских данных, что не позволяет встроить вредоносный SQL внутрь запроса — это основная защита от SQL Injection."},{"n":18,"question":"Защита от XSS:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Санитизация ввода"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Защита от XSS строится на санитизации (очистке) пользовательского ввода — удалении или экранировании потенциально опасного HTML/JS перед его выводом на страницу."},{"n":19,"question":"Когда возникает ошибка CORS?","options":[{"letter":"A","text":"Ошибка CSS"},{"letter":"B","text":"Ошибка HTML"},{"letter":"C","text":"При запросе к другому домену с ограничением доступа"},{"letter":"D","text":"API отсутствует"},{"letter":"E","text":"Ошибка JSON"}],"correct":"C","explanation":"Ошибка CORS возникает, когда веб-страница пытается сделать запрос к другому домену (origin), а сервер не разрешил такой межсайтовый доступ через соответствующие заголовки."},{"n":20,"question":"Разница между controlled и uncontrolled компонентами:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Управление через state"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Controlled-компоненты управляют значением поля через React state (источник истины — state), а uncontrolled — через сам DOM, без прямого контроля React над текущим значением."},{"n":21,"question":"Назначение _id в MongoDB:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Уникальный идентификатор"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Поле _id в MongoDB автоматически генерируется и служит уникальным идентификатором каждого документа в коллекции."},{"n":22,"question":"Что такое REST stateless?","options":[{"letter":"A","text":"Нет CSS"},{"letter":"B","text":"Нет HTML"},{"letter":"C","text":"Сервер не хранит состояние"},{"letter":"D","text":"Нет API"},{"letter":"E","text":"Нет DOM"}],"correct":"C","explanation":"Stateless в контексте REST означает, что сервер не хранит информацию о состоянии клиента между запросами — каждый запрос должен содержать всю необходимую информацию самостоятельно."},{"n":23,"question":"Ошибка HTTP 500:","options":[{"letter":"A","text":"Ошибка клиента"},{"letter":"B","text":"Перенаправление"},{"letter":"C","text":"Ошибка сервера"},{"letter":"D","text":"Нет соединения"},{"letter":"E","text":"Ошибка JSON"}],"correct":"C","explanation":"HTTP-код 500 (Internal Server Error) сигнализирует об ошибке на стороне сервера, а не клиента, обычно вызванной необработанным исключением в коде backend."},{"n":24,"question":"Git rebase vs merge:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Переписывание истории vs объединение"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"git merge сохраняет историю обоих веток и создаёт коммит слияния, а git rebase переписывает историю, переносит коммиты текущей ветки поверх другой, делая историю линейной."},{"n":25,"question":"Lifting state up:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Поднятие состояния вверх"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Lifting state up («поднятие состояния») — паттерн React, при котором общее состояние перемещается в ближайший общий родительский компонент, чтобы несколько дочерних компонентов могли его использовать."},{"n":26,"question":"Назначение useMemo:","options":[{"letter":"A","text":"Сохранение CSS"},{"letter":"B","text":"Сохранение HTML"},{"letter":"C","text":"Кэширование вычислений"},{"letter":"D","text":"Сохранение API"},{"letter":"E","text":"Сохранение DOM"}],"correct":"C","explanation":"useMemo кэширует (мемоизирует) результат вычисления, пересчитывая его только при изменении указанных зависимостей, что избегает повторных дорогих вычислений при каждом рендере."},{"n":27,"question":"Что делает useCallback?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Кэширует функцию"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"useCallback кэширует саму функцию между рендерами, предотвращая создание новой ссылки на функцию при каждом рендере, что особенно важно при передаче callback'ов в дочерние компоненты."},{"n":28,"question":"Throttling vs Debouncing:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Управление частотой вызовов"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"И throttling, и debouncing управляют частотой вызова функции в ответ на частые события (скролл, ресайз, ввод текста), но по-разному ограничивают её выполнение во времени."},{"n":29,"question":"Назначение salt в bcrypt:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Повышает безопасность хеширования"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Salt в bcrypt — случайная строка, добавляемая к паролю перед хешированием, которая делает хеши уникальными даже для одинаковых паролей и защищает от атак по готовым таблицам (rainbow tables)."},{"n":30,"question":"Почему HTTPS безопасен?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Использует шифрование"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"HTTPS безопасен благодаря шифрованию (TLS/SSL) трафика между клиентом и сервером, что защищает данные от перехвата и подмены третьими лицами."},{"n":31,"question":"React Fragment:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Обертка без дополнительного DOM-элемента"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"React.Fragment позволяет группировать несколько элементов в JSX без создания дополнительного, видимого в DOM обёрточного элемента (как, например, лишний <div>)."},{"n":32,"question":"Lazy loading:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Повышение производительности"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Lazy loading откладывает загрузку компонента, изображения или модуля до момента, когда они реально понадобятся, что снижает начальное время загрузки и повышает производительность."},{"n":33,"question":"Преимущество CDN:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Быстрая доставка контента"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"CDN (Content Delivery Network) распределяет копии контента по серверам в разных географических точках, обеспечивая более быструю доставку контента пользователям ближайшего сервера."},{"n":34,"question":"Rate limiting:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Ограничение количества запросов"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Rate limiting ограничивает количество запросов, которое клиент может отправить за определённый промежуток времени, защищая сервер от перегрузки и злоупотреблений."},{"n":35,"question":"Почему state в React нельзя изменять напрямую?","options":[{"letter":"A","text":"Влияет на CSS"},{"letter":"B","text":"Ломает HTML"},{"letter":"C","text":"React не отслеживает изменения"},{"letter":"D","text":"Останавливает API"},{"letter":"E","text":"Удаляет DOM"}],"correct":"C","explanation":"Прямое изменение state в React не вызывает повторный рендер, потому что React определяет изменения, сравнивая ссылки на объекты, а не их внутреннее содержимое — поэтому состояние нужно обновлять только через setState/setter."},{"n":36,"question":"Почему setState не обновляется сразу?","options":[{"letter":"A","text":"CSS задерживается"},{"letter":"B","text":"HTML не обновляется"},{"letter":"C","text":"Используется batching (группировка обновлений)"},{"letter":"D","text":"API задерживается"},{"letter":"E","text":"DOM удаляется"}],"correct":"C","explanation":"setState (как и useState setter) часто работает асинхронно из-за batching — React группирует несколько обновлений состояния в одно для оптимизации производительности рендеринга."},{"n":37,"question":"React reconciliation:","options":[{"letter":"A","text":"Сравнение CSS"},{"letter":"B","text":"Удаление HTML"},{"letter":"C","text":"Сравнение Virtual DOM"},{"letter":"D","text":"Вызов API"},{"letter":"E","text":"Обработка JSON"}],"correct":"C","explanation":"Reconciliation — процесс, при котором React сравнивает новое и предыдущее дерево Virtual DOM, вычисляя минимальный набор изменений для применения к реальному DOM."},{"n":38,"question":"useEffect cleanup:","options":[{"letter":"A","text":"При изменении CSS"},{"letter":"B","text":"При загрузке HTML"},{"letter":"C","text":"При вызове API"},{"letter":"D","text":"При размонтировании или изменении зависимостей"},{"letter":"E","text":"При каждом рендере"}],"correct":"D","explanation":"Функция очистки (cleanup), возвращаемая из useEffect, вызывается при размонтировании компонента или перед повторным запуском эффекта из-за изменения зависимостей."},{"n":39,"question":"StrictMode:","options":[{"letter":"A","text":"Проверка CSS"},{"letter":"B","text":"Проверка HTML"},{"letter":"C","text":"Обнаружение ошибок"},{"letter":"D","text":"Защита API"},{"letter":"E","text":"Удаление DOM"}],"correct":"C","explanation":"StrictMode — инструмент разработки React, который помогает обнаруживать потенциальные проблемы в коде (устаревшие API, побочные эффекты), дважды вызывая некоторые функции в режиме разработки."},{"n":40,"question":"Что такое non-blocking I/O в Node.js:","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Не блокирует основной поток"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Non-blocking I/O в Node.js означает, что операции ввода-вывода (чтение файлов, сетевые запросы) выполняются асинхронно, не останавливая основной поток выполнения программы."}]},{"variant":6,"questions":[{"n":1,"question":"Для чего используется тег <article> в HTML5?","options":[{"letter":"A","text":"Для задания стилей"},{"letter":"B","text":"Для отдельного независимого контента"},{"letter":"C","text":"Для написания скриптов"},{"letter":"D","text":"Для отображения изображений"},{"letter":"E","text":"Для создания форм"}],"correct":"B","explanation":"Тег <article> в HTML5 используется для самостоятельного, независимого блока контента, который имеет смысл сам по себе — например, статьи или поста."},{"n":2,"question":"Для чего используется тег <aside>?","options":[{"letter":"A","text":"Основной контент"},{"letter":"B","text":"Навигация"},{"letter":"C","text":"Дополнительная информация"},{"letter":"D","text":"Скрипты"},{"letter":"E","text":"CSS"}],"correct":"C","explanation":"<aside> предназначен для дополнительной, не основной информации — боковой панели, ссылок «похожие материалы» и подобного контента."},{"n":3,"question":"Для чего нужен display: flex в CSS?","options":[{"letter":"A","text":"Окрашивание текста"},{"letter":"B","text":"Скрытие контейнера"},{"letter":"C","text":"Гибкое расположение элементов"},{"letter":"D","text":"Анимации"},{"letter":"E","text":"Изменение шрифта"}],"correct":"C","explanation":"display: flex включает Flexbox-модель для элемента-контейнера, позволяя гибко располагать его прямых потомков в строку или столбец."},{"n":4,"question":"Как работает position: absolute?","options":[{"letter":"A","text":"По потоку документа"},{"letter":"B","text":"Относительно экрана"},{"letter":"C","text":"Относительно ближайшего позиционированного родителя"},{"letter":"D","text":"Только относительно body"},{"letter":"E","text":"Как fixed"}],"correct":"C","explanation":"position: absolute позиционирует элемент относительно ближайшего предка с заданным position (relative, absolute, fixed), а не относительно body по умолчанию."},{"n":5,"question":"Какое значение typeof null в JavaScript?","options":[{"letter":"A","text":"null"},{"letter":"B","text":"undefined"},{"letter":"C","text":"object"},{"letter":"D","text":"number"},{"letter":"E","text":"string"}],"correct":"C","explanation":"typeof null возвращает \"object\" — это известная историческая особенность языка JavaScript, сохранённая для совместимости со старым кодом."},{"n":6,"question":"Что делает оператор ===?","options":[{"letter":"A","text":"Сравнивает только значение"},{"letter":"B","text":"Сравнивает только тип"},{"letter":"C","text":"Сравнивает и тип, и значение"},{"letter":"D","text":"Сложение"},{"letter":"E","text":"Вычитание"}],"correct":"C","explanation":"Оператор === проверяет строгое равенство — совпадение и значения, и типа данных одновременно, без неявного приведения типов."},{"n":7,"question":"Что делает Array.map()?","options":[{"letter":"A","text":"Фильтрует"},{"letter":"B","text":"Изменяет"},{"letter":"C","text":"Возвращает новый массив"},{"letter":"D","text":"Удаляет"},{"letter":"E","text":"Добавляет"}],"correct":"C","explanation":"Array.map() применяет переданную функцию к каждому элементу массива и возвращает новый массив с результатами, не изменяя исходный."},{"n":8,"question":"Что делает Array.filter()?","options":[{"letter":"A","text":"Возвращает всё"},{"letter":"B","text":"Возвращает элементы по условию"},{"letter":"C","text":"Один элемент"},{"letter":"D","text":"Новый объект"},{"letter":"E","text":"Удаляет"}],"correct":"B","explanation":"Array.filter() возвращает новый массив, включающий только те элементы, для которых функция-условие вернула true."},{"n":9,"question":"Что происходит при Promise.resolve()?","options":[{"letter":"A","text":"Вызывается catch"},{"letter":"B","text":"Вызывается then"},{"letter":"C","text":"Только finally"},{"letter":"D","text":"reject"},{"letter":"E","text":"Останавливается"}],"correct":"B","explanation":"Promise.resolve() мгновенно создаёт уже выполненный (fulfilled) Promise, поэтому привязанный к нему обработчик then() будет вызван."},{"n":10,"question":"Что всегда возвращает async-функция?","options":[{"letter":"A","text":"string"},{"letter":"B","text":"number"},{"letter":"C","text":"Promise"},{"letter":"D","text":"object"},{"letter":"E","text":"array"}],"correct":"C","explanation":"Функция, объявленная с async, всегда неявно возвращает Promise, даже если внутри неё стоит обычный return с простым значением."},{"n":11,"question":"Что такое DOM?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Модель структуры документа"},{"letter":"D","text":"API"},{"letter":"E","text":"JSON"}],"correct":"C","explanation":"DOM (Document Object Model) — это программная модель, представляющая структуру HTML-документа в виде дерева объектов, доступных для изменения через JavaScript."},{"n":12,"question":"Для чего нужен addEventListener?","options":[{"letter":"A","text":"Изменение CSS"},{"letter":"B","text":"Прослушивание событий"},{"letter":"C","text":"Написание HTML"},{"letter":"D","text":"Вызов API"},{"letter":"E","text":"Удаление DOM"}],"correct":"B","explanation":"addEventListener позволяет назначить функцию-обработчик, которая будет выполняться (прослушивать) при возникновении указанного события на элементе."},{"n":13,"question":"Что делает localStorage?","options":[{"letter":"A","text":"Временное хранение"},{"letter":"B","text":"Хранение на сервере"},{"letter":"C","text":"Постоянное хранение в браузере"},{"letter":"D","text":"Хранение API"},{"letter":"E","text":"Хранение DOM"}],"correct":"C","explanation":"localStorage сохраняет данные в браузере на постоянной основе — они остаются доступны даже после закрытия и повторного открытия браузера."},{"n":14,"question":"В чем отличие sessionStorage?","options":[{"letter":"A","text":"Хранится навсегда"},{"letter":"B","text":"Хранится только в рамках сессии"},{"letter":"C","text":"На сервере"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"Отличие sessionStorage от localStorage в том, что данные в sessionStorage хранятся только в рамках текущей сессии (вкладки) и удаляются при её закрытии."},{"n":15,"question":"Для чего используется fetch()?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"HTTP-запрос"},{"letter":"D","text":"DOM"},{"letter":"E","text":"Только JSON"}],"correct":"C","explanation":"fetch() используется для отправки HTTP-запросов к серверу и получения ответа в виде Promise, причём ответ может быть в любом формате, не только JSON."},{"n":16,"question":"Что делает JSON.parse()?","options":[{"letter":"A","text":"Объект → строка"},{"letter":"B","text":"Строка → объект"},{"letter":"C","text":"Массив → строка"},{"letter":"D","text":"HTML"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"JSON.parse() преобразует строку в формате JSON в реальный объект JavaScript, с которым можно работать в коде."},{"n":17,"question":"Что делает JSON.stringify()?","options":[{"letter":"A","text":"Строка → объект"},{"letter":"B","text":"Объект → строка"},{"letter":"C","text":"Массив → число"},{"letter":"D","text":"HTML"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"JSON.stringify() выполняет обратное преобразование — превращает объект JavaScript в строку формата JSON."},{"n":18,"question":"Что возвращает forEach?","options":[{"letter":"A","text":"Новый массив"},{"letter":"B","text":"undefined"},{"letter":"C","text":"object"},{"letter":"D","text":"number"},{"letter":"E","text":"string"}],"correct":"B","explanation":"Метод forEach() всегда возвращает undefined — он предназначен для выполнения побочных действий на каждом элементе, а не для создания нового массива."},{"n":19,"question":"Что делает setTimeout?","options":[{"letter":"A","text":"Выполняет сразу"},{"letter":"B","text":"Выполняет с задержкой"},{"letter":"C","text":"Повторяет"},{"letter":"D","text":"Удаляет"},{"letter":"E","text":"Останавливает"}],"correct":"B","explanation":"setTimeout() запускает переданную функцию один раз после заданной задержки в миллисекундах, а не повторяет её выполнение."},{"n":20,"question":"Что делает setInterval?","options":[{"letter":"A","text":"Один раз"},{"letter":"B","text":"Выполняется повторно"},{"letter":"C","text":"Удаляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"setInterval() запускает переданную функцию повторно, через равные промежутки времени, до момента вызова clearInterval()."},{"n":21,"question":"Что такое CSS specificity?","options":[{"letter":"A","text":"Скорость"},{"letter":"B","text":"Приоритет (вес стилей)"},{"letter":"C","text":"Цвет"},{"letter":"D","text":"Анимация"},{"letter":"E","text":"Шрифт"}],"correct":"B","explanation":"CSS specificity (специфичность) — это система приоритетов, определяющая, какое из конфликтующих правил CSS будет применено к элементу, на основе «веса» селекторов."},{"n":22,"question":"Что делает z-index?","options":[{"letter":"A","text":"Изменяет цвет"},{"letter":"B","text":"Управляет слоями (наложением элементов)"},{"letter":"C","text":"Размер"},{"letter":"D","text":"Шрифт"},{"letter":"E","text":"Анимация"}],"correct":"B","explanation":"z-index управляет порядком наложения (слоями) позиционированных элементов — какой из перекрывающихся элементов будет отображаться выше других."},{"n":23,"question":"Для чего используется media query?","options":[{"letter":"A","text":"API"},{"letter":"B","text":"Адаптивный дизайн"},{"letter":"C","text":"HTML"},{"letter":"D","text":"DOM"},{"letter":"E","text":"JSON"}],"correct":"B","explanation":"Media query — основной инструмент адаптивного (responsive) дизайна, позволяющий применять разные стили в зависимости от характеристик устройства, обычно ширины экрана."},{"n":24,"question":"Что делает overflow: hidden?","options":[{"letter":"A","text":"Показывает содержимое"},{"letter":"B","text":"Скрывает содержимое"},{"letter":"C","text":"Вращает"},{"letter":"D","text":"Увеличивает"},{"letter":"E","text":"Уменьшает"}],"correct":"B","explanation":"overflow: hidden скрывает часть содержимого, которая выходит за границы своего контейнера, без появления полос прокрутки."},{"n":25,"question":"Что делает Git commit?","options":[{"letter":"A","text":"Удаляет"},{"letter":"B","text":"Сохраняет изменения"},{"letter":"C","text":"Добавляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"Команда git commit фиксирует (сохраняет) текущие изменения в локальном репозитории с описывающим сообщением."},{"n":26,"question":"Что делает Git push?","options":[{"letter":"A","text":"Локальное сохранение"},{"letter":"B","text":"Загружает в репозиторий"},{"letter":"C","text":"Удаляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git push отправляет локальные коммиты в удалённый репозиторий (например, на GitHub), делая их видимыми для других участников проекта."},{"n":27,"question":"Что делает Git pull?","options":[{"letter":"A","text":"Удаляет"},{"letter":"B","text":"Получает изменения"},{"letter":"C","text":"Добавляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git pull получает и объединяет изменения из удалённого репозитория с текущей локальной веткой."},{"n":28,"question":"Для чего нужна branch (ветка)?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Параллельная разработка"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Ветка (branch) в Git позволяет вести параллельную разработку отдельных функций, не затрагивая основную (стабильную) версию кода."},{"n":29,"question":"Когда возникает merge conflict?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"При изменении одного и того же файла"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Merge conflict возникает, когда два изменения затрагивают одну и ту же часть одного файла в разных ветках, и Git не может автоматически определить, какое изменение оставить."},{"n":30,"question":"Что такое debugging?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Поиск ошибок"},{"letter":"C","text":"API"},{"letter":"D","text":"DOM"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"Debugging — процесс поиска и устранения ошибок (багов) в коде, обычно с помощью анализа сообщений об ошибках, логов и отладчика."},{"n":31,"question":"Для чего нужен console.log?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Вывод логов"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"console.log() выводит переданные значения в консоль браузера или среды выполнения — основной инструмент для отладки и отслеживания значений переменных."},{"n":32,"question":"Для чего нужен try...catch?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Обработка ошибок"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"try...catch предоставляет механизм обработки ошибок: код в блоке try выполняется, а при возникновении исключения управление передаётся в блок catch без остановки программы."},{"n":33,"question":"Что такое NaN?","options":[{"letter":"A","text":"Number"},{"letter":"B","text":"Некорректное числовое значение"},{"letter":"C","text":"String"},{"letter":"D","text":"Object"},{"letter":"E","text":"Array"}],"correct":"B","explanation":"NaN означает некорректное числовое значение — результат математической операции, которую невозможно выразить как число, например 0/0 или Number(\"текст\")."},{"n":34,"question":"Что проверяет isNaN?","options":[{"letter":"A","text":"String"},{"letter":"B","text":"Number"},{"letter":"C","text":"Значение не является числом"},{"letter":"D","text":"Object"},{"letter":"E","text":"Array"}],"correct":"C","explanation":"isNaN(value) проверяет, является ли переданное значение не-числом, возвращая true, если значение нельзя интерпретировать как корректное число."},{"n":35,"question":"Что делает parseInt?","options":[{"letter":"A","text":"String → integer"},{"letter":"B","text":"Integer → string"},{"letter":"C","text":"Array → number"},{"letter":"D","text":"HTML"},{"letter":"E","text":"CSS"}],"correct":"A","explanation":"parseInt() преобразует строку в целое число, извлекая числовую часть с начала строки и игнорируя оставшиеся нечисловые символы."},{"n":36,"question":"Что делает parseFloat?","options":[{"letter":"A","text":"String → float"},{"letter":"B","text":"Float → string"},{"letter":"C","text":"Array"},{"letter":"D","text":"HTML"},{"letter":"E","text":"CSS"}],"correct":"A","explanation":"parseFloat() преобразует строку в дробное число (с плавающей точкой), аналогично parseInt(), но сохраняя десятичную часть."},{"n":37,"question":"Что делает Boolean()?","options":[{"letter":"A","text":"Number"},{"letter":"B","text":"Преобразует в boolean"},{"letter":"C","text":"String"},{"letter":"D","text":"Array"},{"letter":"E","text":"Object"}],"correct":"B","explanation":"Boolean() преобразует переданное значение в логический тип true/false, основываясь на правилах truthy/falsy в JavaScript."},{"n":38,"question":"Разница между null и undefined:","options":[{"letter":"A","text":"Одинаковы"},{"letter":"B","text":"null — намеренно пустое значение, undefined — не определено"},{"letter":"C","text":"Только number"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"null — это значение, которое разработчик явно присваивает переменной для обозначения «намеренно пустого» значения, а undefined означает, что переменной вообще не присвоено значение."},{"n":39,"question":"Особенность стрелочной функции:","options":[{"letter":"A","text":"Нет this"},{"letter":"B","text":"Лексический this"},{"letter":"C","text":"DOM"},{"letter":"D","text":"API"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"Особенность стрелочной функции — лексический this: она не создаёт собственный контекст this, а заимствует его из окружающего кода, где была определена."},{"n":40,"question":"Для чего используется template literal?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Удобное добавление переменных в строку"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Шаблонный литерал (template literal), записываемый в обратных кавычках, позволяет удобно вставлять переменные и выражения прямо в строку через синтаксис ${expression}."}]},{"variant":7,"questions":[{"n":1,"question":"Для чего используется тег <nav> в HTML?","options":[{"letter":"A","text":"Для отображения изображений"},{"letter":"B","text":"Для навигационных ссылок"},{"letter":"C","text":"Для написания скриптов"},{"letter":"D","text":"Для подключения CSS"},{"letter":"E","text":"Для создания форм"}],"correct":"B","explanation":"Тег <nav> используется для группировки навигационных ссылок, ведущих по основным разделам сайта."},{"n":2,"question":"Для чего используется тег <figure>?","options":[{"letter":"A","text":"Только текст"},{"letter":"B","text":"Формы"},{"letter":"C","text":"Медиа-контент и его описание"},{"letter":"D","text":"Скрипты"},{"letter":"E","text":"CSS"}],"correct":"C","explanation":"<figure> предназначен для группировки медиа-контента (изображения, видео, диаграммы) вместе с его описанием через вложенный <figcaption>."},{"n":3,"question":"Для чего нужен display: grid в CSS?","options":[{"letter":"A","text":"Изменение цвета"},{"letter":"B","text":"Анимации"},{"letter":"C","text":"Создание сеточного layout"},{"letter":"D","text":"Изменение шрифта"},{"letter":"E","text":"Скрытие элементов"}],"correct":"C","explanation":"display: grid включает CSS Grid — модуль, специально созданный для создания двумерной (строки + столбцы) сеточной разметки страницы."},{"n":4,"question":"Как работает position: fixed?","options":[{"letter":"A","text":"Относительно родителя"},{"letter":"B","text":"По потоку документа"},{"letter":"C","text":"Фиксируется на экране"},{"letter":"D","text":"Только внутри body"},{"letter":"E","text":"Как absolute"}],"correct":"C","explanation":"position: fixed закрепляет элемент относительно окна браузера — он остаётся в одном и том же месте экрана даже при прокрутке страницы."},{"n":5,"question":"Какой результат NaN === NaN в JavaScript?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"undefined"},{"letter":"D","text":"null"},{"letter":"E","text":"error"}],"correct":"B","explanation":"NaN — единственное значение в JavaScript, которое не равно даже самому себе: NaN === NaN всегда возвращает false. Для проверки используют isNaN() или Number.isNaN()."},{"n":6,"question":"В чем разница между == и ===?","options":[{"letter":"A","text":"Одинаковы"},{"letter":"B","text":"=== сравнивает только значение"},{"letter":"C","text":"== сравнивает только тип"},{"letter":"D","text":"=== сравнивает и тип, и значение"},{"letter":"E","text":"== проверяет ошибки"}],"correct":"D","explanation":"=== проверяет равенство значения и типа одновременно (строгое сравнение), тогда как == сначала приводит типы операндов друг к другу и затем сравнивает значения."},{"n":7,"question":"Что делает Array.reduce()?","options":[{"letter":"A","text":"Удаляет массив"},{"letter":"B","text":"Сводит массив к одному значению"},{"letter":"C","text":"Копирует"},{"letter":"D","text":"Сортирует"},{"letter":"E","text":"Фильтрует"}],"correct":"B","explanation":"Array.reduce() последовательно обрабатывает все элементы массива с помощью функции-аккумулятора, сводя их к одному итоговому значению (например, сумме или объекту)."},{"n":8,"question":"Что возвращает Array.find()?","options":[{"letter":"A","text":"Все элементы"},{"letter":"B","text":"Новый массив"},{"letter":"C","text":"Первый подходящий элемент"},{"letter":"D","text":"Всегда undefined"},{"letter":"E","text":"Объект"}],"correct":"C","explanation":"Array.find() возвращает первый элемент массива, удовлетворяющий условию в переданной функции, и останавливает поиск, найдя его."},{"n":9,"question":"Что происходит при Promise.reject()?","options":[{"letter":"A","text":"Вызывается then"},{"letter":"B","text":"Вызывается catch"},{"letter":"C","text":"Только finally"},{"letter":"D","text":"resolve"},{"letter":"E","text":"Остановка"}],"correct":"B","explanation":"Promise.reject() создаёт уже отклонённый Promise, поэтому связанный с ним обработчик catch() будет вызван (а не then())."},{"n":10,"question":"Когда выполняется блок finally?","options":[{"letter":"A","text":"Только при resolve"},{"letter":"B","text":"Только при reject"},{"letter":"C","text":"Всегда"},{"letter":"D","text":"Иногда"},{"letter":"E","text":"Никогда"}],"correct":"C","explanation":"Блок finally в конструкции try/catch/finally выполняется всегда — независимо от того, было ли исключение, был ли вызван catch, или код в try завершился успешно."},{"n":11,"question":"Что такое DOM tree?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"JSON"},{"letter":"C","text":"Дерево структуры HTML-документа"},{"letter":"D","text":"API"},{"letter":"E","text":"Script"}],"correct":"C","explanation":"DOM tree — это представление HTML-документа в виде иерархического дерева узлов (элементов, текста, атрибутов), с которым работает JavaScript."},{"n":12,"question":"Что делает removeEventListener?","options":[{"letter":"A","text":"Добавляет событие"},{"letter":"B","text":"Удаляет событие"},{"letter":"C","text":"Изменяет CSS"},{"letter":"D","text":"Пишет HTML"},{"letter":"E","text":"Вызывает API"}],"correct":"B","explanation":"removeEventListener удаляет ранее назначенный обработчик события с элемента — важно передать ту же функцию и тип события, что использовались при добавлении."},{"n":13,"question":"Для чего используются cookies?","options":[{"letter":"A","text":"Хранение CSS"},{"letter":"B","text":"Обмен данными с сервером"},{"letter":"C","text":"HTML"},{"letter":"D","text":"DOM"},{"letter":"E","text":"Удаление API"}],"correct":"B","explanation":"Cookies — это небольшие данные, сохраняемые браузером и автоматически отправляемые на сервер с каждым запросом, что позволяет серверу «помнить» клиента между запросами."},{"n":14,"question":"Особенность session cookie:","options":[{"letter":"A","text":"Хранится навсегда"},{"letter":"B","text":"Удаляется после завершения сессии"},{"letter":"C","text":"Только на сервере"},{"letter":"D","text":"JSON"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"Session cookie (cookie без явного срока действия) хранится только до завершения текущей сессии браузера — обычно до его закрытия."},{"n":15,"question":"Для чего используется axios?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"HTTP-запросы"},{"letter":"D","text":"DOM"},{"letter":"E","text":"Только JSON"}],"correct":"C","explanation":"Axios — популярная JavaScript-библиотека для выполнения HTTP-запросов из браузера или Node.js, упрощающая работу по сравнению с базовым fetch()."},{"n":16,"question":"Что делает HTTP GET?","options":[{"letter":"A","text":"Удаляет данные"},{"letter":"B","text":"Получает данные"},{"letter":"C","text":"Обновляет данные"},{"letter":"D","text":"Добавляет данные"},{"letter":"E","text":"Безопасность"}],"correct":"B","explanation":"HTTP-метод GET предназначен для запроса (получения) данных с сервера, без изменения состояния на стороне сервера."},{"n":17,"question":"Что делает HTTP POST?","options":[{"letter":"A","text":"Чтение"},{"letter":"B","text":"Удаление"},{"letter":"C","text":"Добавление новых данных"},{"letter":"D","text":"Копирование"},{"letter":"E","text":"Просмотр"}],"correct":"C","explanation":"HTTP-метод POST используется для отправки новых данных на сервер — например, для создания новой записи или отправки формы."},{"n":18,"question":"Для чего используется for...of?","options":[{"letter":"A","text":"Объекты"},{"letter":"B","text":"Массивы / итерация"},{"letter":"C","text":"DOM"},{"letter":"D","text":"API"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"Конструкция for...of предназначена для перебора итерируемых структур — массивов, строк и других коллекций — получая непосредственно значения элементов."},{"n":19,"question":"Что делает clearTimeout?","options":[{"letter":"A","text":"Повторяет"},{"letter":"B","text":"Останавливает таймер"},{"letter":"C","text":"Выполняет"},{"letter":"D","text":"Добавляет"},{"letter":"E","text":"Удаляет всё"}],"correct":"B","explanation":"clearTimeout(id) отменяет ранее запланированный через setTimeout вызов функции, если он ещё не успел сработать."},{"n":20,"question":"Что делает clearInterval?","options":[{"letter":"A","text":"Один раз"},{"letter":"B","text":"Останавливает интервал"},{"letter":"C","text":"Повторяет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"clearInterval(id) останавливает повторяющееся выполнение функции, запущенное через setInterval, используя идентификатор таймера."},{"n":21,"question":"Для чего используется CSS margin?","options":[{"letter":"A","text":"Внутренний отступ"},{"letter":"B","text":"Внешний отступ"},{"letter":"C","text":"Цвет"},{"letter":"D","text":"Шрифт"},{"letter":"E","text":"Анимация"}],"correct":"B","explanation":"CSS-свойство margin задаёт внешний отступ — пространство снаружи границы элемента, между ним и соседними элементами."},{"n":22,"question":"Для чего используется CSS padding?","options":[{"letter":"A","text":"Внешний отступ"},{"letter":"B","text":"Внутренний отступ"},{"letter":"C","text":"Слой"},{"letter":"D","text":"Цвет"},{"letter":"E","text":"Размер"}],"correct":"B","explanation":"CSS-свойство padding задаёт внутренний отступ — пространство внутри границы элемента, между его краем и содержимым."},{"n":23,"question":"Что такое responsive design?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Адаптация под разные экраны"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Responsive design (адаптивный дизайн) — подход к верстке, при котором интерфейс автоматически подстраивается под разные размеры экранов и устройств."},{"n":24,"question":"Что делает overflow: scroll?","options":[{"letter":"A","text":"Скрывает"},{"letter":"B","text":"Добавляет прокрутку"},{"letter":"C","text":"Увеличивает"},{"letter":"D","text":"Уменьшает"},{"letter":"E","text":"Удаляет"}],"correct":"B","explanation":"overflow: scroll всегда добавляет полосы прокрутки к контейнеру (даже если контент помещается), в отличие от overflow: auto, которое добавляет их только при необходимости."},{"n":25,"question":"Что делает Git clone?","options":[{"letter":"A","text":"Удаляет"},{"letter":"B","text":"Создает копию"},{"letter":"C","text":"Добавляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git clone создаёт полную локальную копию удалённого репозитория, включая всю историю коммитов и ветки."},{"n":26,"question":"Что показывает Git status?","options":[{"letter":"A","text":"Историю"},{"letter":"B","text":"Состояние изменений"},{"letter":"C","text":"Удаление"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git status показывает текущее состояние рабочей директории: какие файлы изменены, добавлены в индекс (staged) или не отслеживаются Git."},{"n":27,"question":"Что делает Git log?","options":[{"letter":"A","text":"Удаляет"},{"letter":"B","text":"Показывает историю"},{"letter":"C","text":"Добавляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git log выводит историю коммитов текущей ветки в хронологическом порядке, включая автора, дату и сообщение каждого коммита."},{"n":28,"question":"Что делает Git checkout (branch)?","options":[{"letter":"A","text":"Удаляет"},{"letter":"B","text":"Переключает ветку"},{"letter":"C","text":"Добавляет"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"B","explanation":"git checkout <branch> переключает рабочую директорию на указанную ветку, обновляя файлы в соответствии с её последним состоянием."},{"n":29,"question":"Как решается конфликт в Git?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Ручное исправление"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Конфликт слияния в Git обычно разрешается вручную: разработчик открывает конфликтующий файл, выбирает или комбинирует нужные изменения и фиксирует результат отдельным коммитом."},{"n":30,"question":"Что такое testing?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Проверка ошибок"},{"letter":"C","text":"API"},{"letter":"D","text":"DOM"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"Тестирование (testing) — процесс проверки кода на корректность работы и поиска ошибок до того, как они попадут в продакшн."},{"n":31,"question":"Для чего используется console.error?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Вывод ошибок"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"console.error() выводит сообщение в консоль как ошибку — обычно подсвечивается красным цветом и используется специально для логирования проблем, в отличие от обычного console.log()."},{"n":32,"question":"Что делает блок try?","options":[{"letter":"A","text":"Ловит ошибки"},{"letter":"B","text":"Проверяет код"},{"letter":"C","text":"Выполняет код"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Блок try содержит код, который потенциально может выбросить исключение; именно этот код пытается выполниться первым в конструкции try...catch."},{"n":33,"question":"Что такое Infinity?","options":[{"letter":"A","text":"Число"},{"letter":"B","text":"Бесконечное значение"},{"letter":"C","text":"String"},{"letter":"D","text":"Object"},{"letter":"E","text":"Array"}],"correct":"B","explanation":"Infinity — специальное числовое значение в JavaScript, представляющее бесконечность, возникающее, например, при делении положительного числа на ноль."},{"n":34,"question":"Что делает Number()?","options":[{"letter":"A","text":"String"},{"letter":"B","text":"Преобразует в число"},{"letter":"C","text":"Boolean"},{"letter":"D","text":"Object"},{"letter":"E","text":"Array"}],"correct":"B","explanation":"Number() преобразует переданное значение (строку, булево и др.) в числовой тип данных."},{"n":35,"question":"Что делает toString()?","options":[{"letter":"A","text":"Число"},{"letter":"B","text":"Преобразует в строку"},{"letter":"C","text":"Array"},{"letter":"D","text":"HTML"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"toString() преобразует значение любого типа (число, объект, массив) в его строковое представление."},{"n":36,"question":"Что возвращает Math.random()?","options":[{"letter":"A","text":"Integer"},{"letter":"B","text":"Случайное число"},{"letter":"C","text":"String"},{"letter":"D","text":"Object"},{"letter":"E","text":"Array"}],"correct":"B","explanation":"Math.random() возвращает псевдослучайное число с плавающей точкой в диапазоне от 0 (включительно) до 1 (не включая)."},{"n":37,"question":"Какое значение является false?","options":[{"letter":"A","text":"\"0\""},{"letter":"B","text":"1"},{"letter":"C","text":"0"},{"letter":"D","text":"\"true\""},{"letter":"E","text":"{}"}],"correct":"C","explanation":"Среди значений 0 — это единственное falsy-значение в списке: оно автоматически приводится к false в логическом контексте, в отличие от непустых строк \"true\"/\"0\" и объектов."},{"n":38,"question":"Когда появляется undefined?","options":[{"letter":"A","text":"Переменная без значения"},{"letter":"B","text":"При null"},{"letter":"C","text":"При 0"},{"letter":"D","text":"String"},{"letter":"E","text":"Array"}],"correct":"A","explanation":"undefined появляется автоматически, когда переменная объявлена, но ей не присвоено никакое значение."},{"n":39,"question":"Особенность function declaration:","options":[{"letter":"A","text":"Нет hoisting"},{"letter":"B","text":"Есть hoisting"},{"letter":"C","text":"DOM"},{"letter":"D","text":"API"},{"letter":"E","text":"CSS"}],"correct":"B","explanation":"Function declaration (объявление функции через ключевое слово function) поднимается (hoisting) в начало своей области видимости, поэтому такую функцию можно вызвать до её определения в коде."},{"n":40,"question":"Что делает spread operator (...)?","options":[{"letter":"A","text":"CSS"},{"letter":"B","text":"HTML"},{"letter":"C","text":"Расширяет массив/объект"},{"letter":"D","text":"API"},{"letter":"E","text":"DOM"}],"correct":"C","explanation":"Spread-оператор (...) разворачивает элементы массива или свойства объекта в отдельные значения — например, при копировании, объединении или передаче как аргументов функции."}]},{"variant":8,"questions":[{"n":1,"question":"Что означает понятие Continuous Integration в процессе CI/CD?","options":[{"letter":"A","text":"Систематическое объединение изменений кода и автоматическое тестирование"},{"letter":"B","text":"Временная остановка сервера и его перезапуск"},{"letter":"C","text":"Полная переработка интерфейсной части приложения"},{"letter":"D","text":"Ручное обновление и сохранение базы данных"},{"letter":"E","text":"Удаление системных файлов и их повторная установка"}],"correct":"A","explanation":"Continuous Integration — практика, при которой разработчики часто объединяют изменения кода в общую ветку, а система автоматически прогоняет тесты на каждое такое объединение."},{"n":2,"question":"Что означает Incremental backup?","options":[{"letter":"A","text":"Полное копирование всех данных заново"},{"letter":"B","text":"Сохранение копий только системных файлов"},{"letter":"C","text":"Пошаговое копирование только последних изменений"},{"letter":"D","text":"Ручное сохранение выбранных файлов"},{"letter":"E","text":"Простое копирование файлов без архивации"}],"correct":"C","explanation":"Incremental backup сохраняет только те данные, которые изменились с момента последнего любого бэкапа (полного или инкрементного), что экономит время и место."},{"n":3,"question":"Что такое Full backup?","options":[{"letter":"A","text":"Копирование только части данных"},{"letter":"B","text":"Отдельное сохранение базы данных"},{"letter":"C","text":"Полное создание копии всей информации"},{"letter":"D","text":"Сохранение только программного кода"},{"letter":"E","text":"Резервирование только API-конфигураций"}],"correct":"C","explanation":"Full backup создаёт полную копию всех данных целиком, независимо от того, что менялось с прошлого раза — самый надёжный, но и самый медленный/объёмный вид бэкапа."},{"n":4,"question":"Что означает понятие Disaster Recovery?","options":[{"letter":"A","text":"Обновление программного кода"},{"letter":"B","text":"Полная переработка пользовательского интерфейса"},{"letter":"C","text":"Стратегия восстановления системы после аварии"},{"letter":"D","text":"Анализ производительности API"},{"letter":"E","text":"Полное удаление избыточных данных"}],"correct":"C","explanation":"Disaster Recovery — комплекс мер и план действий по восстановлению работы системы после серьёзного сбоя, аварии или катастрофы."},{"n":5,"question":"Для чего нужен rollback при деплое?","options":[{"letter":"A","text":"Полное удаление старого кода"},{"letter":"B","text":"Временная остановка сервера для проверки"},{"letter":"C","text":"Возврат к предыдущей версии при ошибке"},{"letter":"D","text":"Полная переработка структуры API"},{"letter":"E","text":"Улучшение визуального интерфейса"}],"correct":"C","explanation":"Rollback при деплое позволяет быстро вернуться к предыдущей, стабильно работавшей версии приложения, если новая версия оказалась нерабочей."},{"n":6,"question":"Что такое Blue-Green deployment?","options":[{"letter":"A","text":"Метод обновления дизайна системы"},{"letter":"B","text":"Перестройка структуры API"},{"letter":"C","text":"Механизм безопасного обновления через две среды"},{"letter":"D","text":"Изменение стиля написания кода"},{"letter":"E","text":"Изменение формата хранения данных"}],"correct":"C","explanation":"Blue-Green deployment использует две идентичные среды (\"blue\" и \"green\"): новая версия разворачивается в неактивной среде, и трафик переключается на неё только после успешной проверки."},{"n":7,"question":"В чём особенность Canary deployment?","options":[{"letter":"A","text":"Обновление сразу для всех пользователей"},{"letter":"B","text":"Полное отключение API и перезапуск"},{"letter":"C","text":"Постепенное тестирование на небольшой группе пользователей"},{"letter":"D","text":"Полная остановка выполнения кода"},{"letter":"E","text":"Перезагрузка сервера"}],"correct":"C","explanation":"Canary deployment постепенно направляет новую версию небольшой части пользователей, чтобы обнаружить проблемы до того, как обновление получат все пользователи."},{"n":8,"question":"Основная цель системы мониторинга?","options":[{"letter":"A","text":"Автоматическое написание кода"},{"letter":"B","text":"Динамическое изменение интерфейса"},{"letter":"C","text":"Контроль состояния системы и выявление ошибок"},{"letter":"D","text":"Удаление и переустановка API"},{"letter":"E","text":"Долгосрочное хранение данных"}],"correct":"C","explanation":"Основная цель системы мониторинга — непрерывно следить за состоянием системы (нагрузка, доступность, ошибки) и своевременно сигнализировать о проблемах."},{"n":9,"question":"Для чего используются log-файлы?","options":[{"letter":"A","text":"Ускорение процесса написания кода"},{"letter":"B","text":"Визуальные элементы интерфейса"},{"letter":"C","text":"Запись ошибок и истории действий"},{"letter":"D","text":"Автоматическое создание API"},{"letter":"E","text":"Перезапуск сервера"}],"correct":"C","explanation":"Лог-файлы записывают историю событий, действий и ошибок системы, что критически важно для последующей диагностики и расследования инцидентов."},{"n":10,"question":"Для чего используется Docker?","options":[{"letter":"A","text":"Создание и редактирование дизайна"},{"letter":"B","text":"Запуск инструментов тестирования API"},{"letter":"C","text":"Контейнеризация и изоляция приложений"},{"letter":"D","text":"Оптимизация и сокращение кода"},{"letter":"E","text":"Полное удаление файлов"}],"correct":"C","explanation":"Docker используется для контейнеризации приложений — упаковки кода со всеми зависимостями в изолированный, переносимый контейнер, работающий одинаково на любой машине."},{"n":11,"question":"Какую функцию выполняет Kubernetes?","options":[{"letter":"A","text":"Автоматическое написание кода"},{"letter":"B","text":"Обработка элементов интерфейса"},{"letter":"C","text":"Управление и масштабирование контейнеров"},{"letter":"D","text":"Удаление API-сервисов"},{"letter":"E","text":"Архивация данных"}],"correct":"C","explanation":"Kubernetes — система оркестрации, которая управляет развёртыванием, масштабированием и восстановлением множества контейнеров в кластере."},{"n":12,"question":"Что означает SLA?","options":[{"letter":"A","text":"Стандарт формата кода"},{"letter":"B","text":"Тип структуры API"},{"letter":"C","text":"Соглашение об уровне обслуживания"},{"letter":"D","text":"Набор элементов интерфейса"},{"letter":"E","text":"Формат имени сервера"}],"correct":"C","explanation":"SLA (Service Level Agreement) — соглашение об уровне обслуживания, формально определяющее гарантированные параметры качества сервиса (например, доступность 99.9%)."},{"n":13,"question":"Что такое Uptime?","options":[{"letter":"A","text":"Общая длина кода"},{"letter":"B","text":"Показатель производительности API"},{"letter":"C","text":"Время непрерывной работы системы"},{"letter":"D","text":"Объём данных"},{"letter":"E","text":"Качество интерфейса"}],"correct":"C","explanation":"Uptime показывает, сколько времени система непрерывно проработала без сбоев и недоступности — ключевая метрика надёжности сервиса."},{"n":14,"question":"Что такое Smoke testing?","options":[{"letter":"A","text":"Полное тестирование всех функций"},{"letter":"B","text":"Визуальное тестирование интерфейса"},{"letter":"C","text":"Быстрая проверка основных функций"},{"letter":"D","text":"Полное тестирование API"},{"letter":"E","text":"Аппаратное тестирование сервера"}],"correct":"C","explanation":"Smoke testing — быстрая, поверхностная проверка ключевых функций системы после деплоя, чтобы убедиться, что критически важные части работают, прежде чем переходить к детальному тестированию."},{"n":15,"question":"Когда применяется Sanity testing?","options":[{"letter":"A","text":"При полном тестировании системы"},{"letter":"B","text":"В процессе написания кода"},{"letter":"C","text":"Короткая проверка после изменений"},{"letter":"D","text":"При создании структуры API"},{"letter":"E","text":"При изменении дизайна"}],"correct":"C","explanation":"Sanity testing применяется после небольших изменений или исправлений, чтобы быстро убедиться, что конкретная функциональность работает корректно, без полного регрессионного прогона."},{"n":16,"question":"Что означает Black-box testing?","options":[{"letter":"A","text":"Полный анализ структуры кода"},{"letter":"B","text":"Проверка работы сервера"},{"letter":"C","text":"Тестирование без знания внутренней логики"},{"letter":"D","text":"Удаление API-сервисов"},{"letter":"E","text":"Способ создания интерфейса"}],"correct":"C","explanation":"Black-box testing — тестирование, при котором проверяющий не знает внутреннего устройства кода и оценивает систему только по входным и выходным данным."},{"n":17,"question":"Особенность White-box testing?","options":[{"letter":"A","text":"Метод тестирования интерфейса"},{"letter":"B","text":"Проверка API-ответов"},{"letter":"C","text":"Тестирование с доступом к внутреннему коду"},{"letter":"D","text":"Временная остановка сервера"},{"letter":"E","text":"Метод хранения данных"}],"correct":"C","explanation":"White-box testing, в отличие от black-box, проводится с полным доступом и знанием внутренней структуры и логики кода."},{"n":18,"question":"Как проводится Exploratory testing?","options":[{"letter":"A","text":"По строгому плану"},{"letter":"B","text":"Через написание кода"},{"letter":"C","text":"Свободное исследование и экспериментирование"},{"letter":"D","text":"Через автоматическое API-тестирование"},{"letter":"E","text":"При создании интерфейса"}],"correct":"C","explanation":"Exploratory testing — неформальный подход, при котором тестировщик свободно исследует приложение без заранее написанного строгого сценария, ориентируясь на интуицию и опыт."},{"n":19,"question":"Что такое Test case?","options":[{"letter":"A","text":"Часть кода"},{"letter":"B","text":"Элемент API"},{"letter":"C","text":"Сценарий тестирования"},{"letter":"D","text":"Параметр сервера"},{"letter":"E","text":"Формат файла"}],"correct":"C","explanation":"Test case — это конкретный сценарий тестирования: набор входных данных, шагов выполнения и ожидаемого результата для проверки определённой функции."},{"n":20,"question":"Что означает Test suite?","options":[{"letter":"A","text":"Один тест"},{"letter":"B","text":"API-сервис"},{"letter":"C","text":"Полный набор тестов"},{"letter":"D","text":"Компонент интерфейса"},{"letter":"E","text":"Блок кода"}],"correct":"C","explanation":"Test suite — это полный набор (коллекция) связанных тестовых случаев (test case), объединённых для совместного запуска."},{"n":21,"question":"Для чего нужна система bug tracking?","options":[{"letter":"A","text":"Для процесса написания кода"},{"letter":"B","text":"Для проектирования интерфейса"},{"letter":"C","text":"Для регистрации и отслеживания ошибок"},{"letter":"D","text":"Для удаления API-сервисов"},{"letter":"E","text":"Для хранения данных"}],"correct":"C","explanation":"Система bug tracking предназначена для регистрации, отслеживания статуса и приоритизации найденных ошибок (багов) на протяжении всего их жизненного цикла."},{"n":22,"question":"К какому типу инструмента относится Jira?","options":[{"letter":"A","text":"Среда программирования"},{"letter":"B","text":"Тип сервера"},{"letter":"C","text":"Система управления задачами и ошибками"},{"letter":"D","text":"Инструмент API"},{"letter":"E","text":"Тип фреймворка"}],"correct":"C","explanation":"Jira — популярная система управления задачами, проектами и отслеживанием ошибок (issue/bug tracking), широко используемая в Agile-командах."},{"n":23,"question":"Что относится к системе контроля версий?","options":[{"letter":"A","text":"Docker"},{"letter":"B","text":"Kubernetes"},{"letter":"C","text":"Git"},{"letter":"D","text":"Jenkins"},{"letter":"E","text":"Postman"}],"correct":"C","explanation":"Git — это распределённая система контроля версий, предназначенная для отслеживания изменений в коде и совместной работы команды над одним проектом."},{"n":24,"question":"Что означает Git commit?","options":[{"letter":"A","text":"Полное удаление кода"},{"letter":"B","text":"Создание API"},{"letter":"C","text":"Сохранение изменений"},{"letter":"D","text":"Остановка сервера"},{"letter":"E","text":"Изменение интерфейса"}],"correct":"C","explanation":"Git commit фиксирует текущий набор изменений в локальном репозитории, создавая новую точку в истории проекта с описывающим сообщением."},{"n":25,"question":"Для чего используется Git merge?","options":[{"letter":"A","text":"Удаление кода"},{"letter":"B","text":"Тестирование API"},{"letter":"C","text":"Объединение разных веток"},{"letter":"D","text":"Подключение сервера"},{"letter":"E","text":"Сохранение данных"}],"correct":"C","explanation":"Git merge объединяет изменения из одной ветки в другую, создавая (при необходимости) коммит слияния, сохраняющий историю обеих веток."},{"n":26,"question":"Что означает понятие branch?","options":[{"letter":"A","text":"Ошибка в коде"},{"letter":"B","text":"Метод API"},{"letter":"C","text":"Отдельная ветка или версия кода"},{"letter":"D","text":"Элемент интерфейса"},{"letter":"E","text":"Тип сервера"}],"correct":"C","explanation":"Branch (ветка) в Git — это независимая линия разработки, позволяющая вносить изменения параллельно с основной веткой без риска её повредить."},{"n":27,"question":"Для чего используется pull request?","options":[{"letter":"A","text":"Удаление кода"},{"letter":"B","text":"Вызов API"},{"letter":"C","text":"Запрос на объединение изменений"},{"letter":"D","text":"Отключение сервера"},{"letter":"E","text":"Сохранение данных"}],"correct":"C","explanation":"Pull request — формальный запрос на слияние изменений из одной ветки в другую, обычно сопровождающийся code review перед окончательным merge."},{"n":28,"question":"Когда возникает merge conflict?","options":[{"letter":"A","text":"Когда нет кода"},{"letter":"B","text":"Когда API не работает"},{"letter":"C","text":"При противоречивых изменениях в одном файле"},{"letter":"D","text":"При изменении интерфейса"},{"letter":"E","text":"При включении сервера"}],"correct":"C","explanation":"Merge conflict возникает, когда два набора изменений затрагивают одну и ту же часть одного файла в разных ветках, и Git не может определить, какой вариант оставить автоматически."},{"n":29,"question":"Что такое staging environment?","options":[{"letter":"A","text":"Реальная рабочая среда"},{"letter":"B","text":"Среда разработки"},{"letter":"C","text":"Тестовая среда, похожая на production"},{"letter":"D","text":"API-сервер"},{"letter":"E","text":"Режим интерфейса"}],"correct":"C","explanation":"Staging environment — тестовая среда, максимально приближенная по конфигурации к production, используемая для финальной проверки перед реальным релизом."},{"n":30,"question":"Что такое production environment?","options":[{"letter":"A","text":"Среда тестирования"},{"letter":"B","text":"Среда разработки API"},{"letter":"C","text":"Среда, используемая реальными пользователями"},{"letter":"D","text":"Режим интерфейса"},{"letter":"E","text":"Место хранения кода"}],"correct":"C","explanation":"Production environment — это реальная рабочая среда, с которой непосредственно взаимодействуют конечные пользователи приложения."},{"n":31,"question":"Что означает hotfix?","options":[{"letter":"A","text":"Плановое обновление"},{"letter":"B","text":"Изменение API"},{"letter":"C","text":"Срочное исправление ошибки"},{"letter":"D","text":"Обновление интерфейса"},{"letter":"E","text":"Установка сервера"}],"correct":"C","explanation":"Hotfix — срочное исправление критической ошибки, выпускаемое в production вне обычного цикла планового релиза."},{"n":32,"question":"Для чего используется load balancer?","options":[{"letter":"A","text":"Для написания кода"},{"letter":"B","text":"Для создания интерфейса"},{"letter":"C","text":"Для распределения трафика между серверами"},{"letter":"D","text":"Для удаления API"},{"letter":"E","text":"Для хранения данных"}],"correct":"C","explanation":"Load balancer распределяет входящий сетевой трафик между несколькими серверами, предотвращая перегрузку одного сервера и повышая отказоустойчивость системы."},{"n":33,"question":"Что такое reverse proxy?","options":[{"letter":"A","text":"Клиентское приложение"},{"letter":"B","text":"Тип API"},{"letter":"C","text":"Промежуточная система, направляющая запросы к серверу"},{"letter":"D","text":"Элемент интерфейса"},{"letter":"E","text":"Структура кода"}],"correct":"C","explanation":"Reverse proxy — промежуточный сервер, который принимает запросы от клиентов и перенаправляет их к нужному backend-серверу, скрывая внутреннюю структуру инфраструктуры."},{"n":34,"question":"Для чего используется SSL-сертификат?","options":[{"letter":"A","text":"Для написания кода"},{"letter":"B","text":"Для создания API"},{"letter":"C","text":"Для обеспечения безопасного соединения"},{"letter":"D","text":"Для создания интерфейса"},{"letter":"E","text":"Для остановки сервера"}],"correct":"C","explanation":"SSL-сертификат обеспечивает шифрование данных при передаче между клиентом и сервером, гарантируя безопасное (HTTPS) соединение."},{"n":35,"question":"Что означает HTTPS?","options":[{"letter":"A","text":"Обычный HTTP"},{"letter":"B","text":"Формат API"},{"letter":"C","text":"Безопасный протокол HTTP"},{"letter":"D","text":"Режим интерфейса"},{"letter":"E","text":"Структура кода"}],"correct":"C","explanation":"HTTPS — это защищённая версия протокола HTTP, в которой данные передаются в зашифрованном виде с помощью TLS/SSL."},{"n":36,"question":"Что определяет retention policy?","options":[{"letter":"A","text":"Время написания кода"},{"letter":"B","text":"Время работы API"},{"letter":"C","text":"Срок хранения резервных копий"},{"letter":"D","text":"Производительность сервера"},{"letter":"E","text":"Тип интерфейса"}],"correct":"C","explanation":"Retention policy определяет, как долго резервные копии (бэкапы) должны храниться, прежде чем их можно удалить или перезаписать."},{"n":37,"question":"В чём особенность snapshot backup?","options":[{"letter":"A","text":"Не создаёт полную копию"},{"letter":"B","text":"Сохраняет только API"},{"letter":"C","text":"Сохраняет состояние системы на определённый момент времени"},{"letter":"D","text":"Изменяет код"},{"letter":"E","text":"Удаляет файлы"}],"correct":"C","explanation":"Snapshot backup фиксирует состояние всей системы (диска, базы данных) на конкретный момент времени, позволяя позже вернуться именно к этому состоянию."},{"n":38,"question":"Для чего нужен failover механизм?","options":[{"letter":"A","text":"Для написания кода"},{"letter":"B","text":"Для изменения интерфейса"},{"letter":"C","text":"Для переключения на резервную систему при сбое основной"},{"letter":"D","text":"Для тестирования API"},{"letter":"E","text":"Для удаления данных"}],"correct":"C","explanation":"Failover-механизм автоматически переключает нагрузку на резервную (запасную) систему в случае выхода из строя основной, минимизируя время простоя."},{"n":39,"question":"Что обеспечивает high availability?","options":[{"letter":"A","text":"Качество кода"},{"letter":"B","text":"Дизайн интерфейса"},{"letter":"C","text":"Непрерывную работу системы"},{"letter":"D","text":"Скорость API"},{"letter":"E","text":"Размер файлов"}],"correct":"C","explanation":"High availability (высокая доступность) описывает способность системы оставаться работоспособной и доступной для пользователей практически непрерывно, минимизируя время простоя."},{"n":40,"question":"Что такое horizontal scaling?","options":[{"letter":"A","text":"Увеличение мощности одного сервера"},{"letter":"B","text":"Изменение кода"},{"letter":"C","text":"Масштабирование за счёт добавления новых серверов"},{"letter":"D","text":"Удаление API"},{"letter":"E","text":"Изменение интерфейса"}],"correct":"C","explanation":"Horizontal scaling (горизонтальное масштабирование) увеличивает производительность системы за счёт добавления новых серверов, а не увеличения мощности одного существующего."}]},{"variant":9,"questions":[{"n":1,"question":"Какова основная цель CI процесса?","options":[{"letter":"A","text":"Создание интерфейса"},{"letter":"B","text":"Объединение и проверка изменений кода"},{"letter":"C","text":"Удаление данных"},{"letter":"D","text":"Остановка сервера"},{"letter":"E","text":"Написание API"}],"correct":"B","explanation":"Главная цель процесса CI — регулярно объединять изменения кода от разных разработчиков в общую ветку и автоматически проверять их с помощью тестов."},{"n":2,"question":"Что означает Continuous Delivery?","options":[{"letter":"A","text":"Ручное тестирование кода"},{"letter":"B","text":"Полная остановка системы"},{"letter":"C","text":"Автоматическая доставка кода в готовом состоянии"},{"letter":"D","text":"Обновление интерфейса"},{"letter":"E","text":"Копирование данных"}],"correct":"C","explanation":"Continuous Delivery подразумевает, что код после прохождения всех проверок автоматически готовится к доставке (релизу) в любой момент, обычно требуя лишь финального подтверждения для выкладки."},{"n":3,"question":"Для чего нужен Backup?","options":[{"letter":"A","text":"Для написания кода"},{"letter":"B","text":"Для создания интерфейса"},{"letter":"C","text":"Для защиты и восстановления данных"},{"letter":"D","text":"Для создания API"},{"letter":"E","text":"Для выключения сервера"}],"correct":"C","explanation":"Backup (резервное копирование) создаётся для защиты данных от потери и возможности их восстановления в случае сбоя, ошибки или атаки."},{"n":4,"question":"Как работает Differential backup?","options":[{"letter":"A","text":"Копирует все данные"},{"letter":"B","text":"Сохраняет изменения после последнего полного backup"},{"letter":"C","text":"Сохраняет только код"},{"letter":"D","text":"Копирует только API"},{"letter":"E","text":"Удаляет файлы"}],"correct":"B","explanation":"Differential backup сохраняет все изменения, накопленные с момента последнего полного (full) бэкапа — в отличие от incremental, который сравнивает с последним бэкапом любого типа."},{"n":5,"question":"Что такое Deployment?","options":[{"letter":"A","text":"Процесс написания кода"},{"letter":"B","text":"Тестирование системы"},{"letter":"C","text":"Размещение приложения на сервере"},{"letter":"D","text":"Создание интерфейса"},{"letter":"E","text":"Удаление данных"}],"correct":"C","explanation":"Deployment — это процесс размещения и запуска готового приложения на сервере, делающий его доступным для пользователей."},{"n":6,"question":"Когда используется Rollback?","options":[{"letter":"A","text":"Когда система работает правильно"},{"letter":"B","text":"При изменении интерфейса"},{"letter":"C","text":"Для возврата к предыдущей версии при ошибке"},{"letter":"D","text":"При написании API"},{"letter":"E","text":"При удалении кода"}],"correct":"C","explanation":"Rollback используется, когда после деплоя обнаруживается ошибка — он позволяет быстро откатиться к предыдущей, стабильно работавшей версии приложения."},{"n":7,"question":"Для чего полезен Canary release?","options":[{"letter":"A","text":"Обновление сразу для всех пользователей"},{"letter":"B","text":"Постепенное тестирование обновления"},{"letter":"C","text":"Остановка сервера"},{"letter":"D","text":"Удаление кода"},{"letter":"E","text":"Изменение интерфейса"}],"correct":"B","explanation":"Canary release полезен тем, что позволяет постепенно протестировать новое обновление на небольшой группе пользователей, прежде чем выкатывать его на всех."},{"n":8,"question":"Что делает система Monitoring?","options":[{"letter":"A","text":"Пишет код"},{"letter":"B","text":"Создаёт UI"},{"letter":"C","text":"Отслеживает работу системы"},{"letter":"D","text":"Отключает API"},{"letter":"E","text":"Сохраняет файлы"}],"correct":"C","explanation":"Система Monitoring непрерывно отслеживает работу системы — её производительность, доступность и возникающие ошибки — для своевременного реагирования на проблемы."},{"n":9,"question":"Что такое Logging?","options":[{"letter":"A","text":"Компиляция кода"},{"letter":"B","text":"Создание интерфейса"},{"letter":"C","text":"Запись действий системы"},{"letter":"D","text":"Создание API"},{"letter":"E","text":"Выключение сервера"}],"correct":"C","explanation":"Logging — это запись действий и событий системы в журнал (лог), что используется для последующего анализа поведения системы и расследования инцидентов."},{"n":10,"question":"Что такое Containerization?","options":[{"letter":"A","text":"Сжатие кода"},{"letter":"B","text":"Запуск приложения в контейнере"},{"letter":"C","text":"Создание интерфейса"},{"letter":"D","text":"Удаление API"},{"letter":"E","text":"Удаление данных"}],"correct":"B","explanation":"Containerization — это запуск приложения вместе со всеми его зависимостями в изолированном, переносимом контейнере (например, с помощью Docker)."},{"n":11,"question":"Какова основная функция Kubernetes?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Управление контейнерами"},{"letter":"C","text":"Создание UI"},{"letter":"D","text":"Удаление API"},{"letter":"E","text":"Хранение данных"}],"correct":"B","explanation":"Основная функция Kubernetes — оркестрация: автоматическое управление развёртыванием, масштабированием и восстановлением контейнеров в кластере."},{"n":12,"question":"Что означает SLA?","options":[{"letter":"A","text":"Структура кода"},{"letter":"B","text":"Тип API"},{"letter":"C","text":"Соглашение об уровне обслуживания"},{"letter":"D","text":"Элемент UI"},{"letter":"E","text":"Тип сервера"}],"correct":"C","explanation":"SLA (Service Level Agreement) — это формальное соглашение об уровне обслуживания, фиксирующее гарантированные параметры качества сервиса."},{"n":13,"question":"Что означает Uptime?","options":[{"letter":"A","text":"Объём кода"},{"letter":"B","text":"Количество API"},{"letter":"C","text":"Время работы системы"},{"letter":"D","text":"Качество интерфейса"},{"letter":"E","text":"Размер файла"}],"correct":"C","explanation":"Uptime отражает суммарное время непрерывной, бесперебойной работы системы — чем выше этот показатель, тем надёжнее сервис."},{"n":14,"question":"Что такое Smoke test?","options":[{"letter":"A","text":"Полное тестирование"},{"letter":"B","text":"Быстрая проверка основных функций"},{"letter":"C","text":"Тест UI"},{"letter":"D","text":"Тест API"},{"letter":"E","text":"Тест сервера"}],"correct":"B","explanation":"Smoke test — это быстрая проверка ключевых, самых важных функций системы сразу после деплоя или сборки, перед более глубоким тестированием."},{"n":15,"question":"Когда проводится Sanity test?","options":[{"letter":"A","text":"При полном тестировании"},{"letter":"B","text":"При написании кода"},{"letter":"C","text":"После изменений"},{"letter":"D","text":"При создании API"},{"letter":"E","text":"При изменении UI"}],"correct":"C","explanation":"Sanity test проводится после внесения изменений в код, чтобы быстро убедиться, что затронутая функциональность по-прежнему работает корректно."},{"n":16,"question":"Особенность Black-box testing?","options":[{"letter":"A","text":"Знание кода"},{"letter":"B","text":"Проверка внутренней структуры"},{"letter":"C","text":"Тестирование без знания внутренней логики"},{"letter":"D","text":"Написание API"},{"letter":"E","text":"Создание UI"}],"correct":"C","explanation":"Особенность Black-box testing — тестирование системы без знания её внутренней реализации, основываясь только на входных данных и ожидаемых результатах."},{"n":17,"question":"Что такое White-box testing?","options":[{"letter":"A","text":"UI тест"},{"letter":"B","text":"API тест"},{"letter":"C","text":"Тестирование с пониманием внутреннего кода"},{"letter":"D","text":"Остановка сервера"},{"letter":"E","text":"Хранение данных"}],"correct":"C","explanation":"White-box testing предполагает тестирование с полным пониманием и доступом к внутреннему коду системы, что позволяет проверять конкретные пути выполнения."},{"n":18,"question":"Как проходит Exploratory testing?","options":[{"letter":"A","text":"По плану"},{"letter":"B","text":"Автоматически"},{"letter":"C","text":"Через свободное исследование"},{"letter":"D","text":"Тест API"},{"letter":"E","text":"Изменение UI"}],"correct":"C","explanation":"Exploratory testing проходит через свободное, неструктурированное исследование приложения тестировщиком, без заранее зафиксированного плана действий."},{"n":19,"question":"Что такое Test case?","options":[{"letter":"A","text":"Код"},{"letter":"B","text":"API"},{"letter":"C","text":"Сценарий тестирования"},{"letter":"D","text":"Сервер"},{"letter":"E","text":"Файл"}],"correct":"C","explanation":"Test case — это конкретный, документированный сценарий тестирования с определёнными входными данными, шагами и ожидаемым результатом."},{"n":20,"question":"Что такое Test suite?","options":[{"letter":"A","text":"Один тест"},{"letter":"B","text":"API"},{"letter":"C","text":"Набор тестов"},{"letter":"D","text":"UI"},{"letter":"E","text":"Код"}],"correct":"C","explanation":"Test suite — это набор тестов (нескольких test case), объединённых вместе для совместного запуска и анализа результатов."},{"n":21,"question":"Для чего нужен Bug tracking?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Создание интерфейса"},{"letter":"C","text":"Отслеживание ошибок"},{"letter":"D","text":"Удаление API"},{"letter":"E","text":"Хранение данных"}],"correct":"C","explanation":"Bug tracking необходим для систематического отслеживания обнаруженных ошибок: их статуса, приоритета и истории исправления."},{"n":22,"question":"Что такое Jira?","options":[{"letter":"A","text":"IDE"},{"letter":"B","text":"Сервер"},{"letter":"C","text":"Система управления проектами"},{"letter":"D","text":"API"},{"letter":"E","text":"Фреймворк"}],"correct":"C","explanation":"Jira — это система управления проектами и задачами, широко применяемая для отслеживания багов и организации работы команд разработки."},{"n":23,"question":"Пример Version control:","options":[{"letter":"A","text":"Docker"},{"letter":"B","text":"Jenkins"},{"letter":"C","text":"Git"},{"letter":"D","text":"Postman"},{"letter":"E","text":"Kubernetes"}],"correct":"C","explanation":"Git — классический пример системы контроля версий (version control), предназначенной для отслеживания истории изменений кода."},{"n":24,"question":"Что означает Commit?","options":[{"letter":"A","text":"Удаление кода"},{"letter":"B","text":"Создание API"},{"letter":"C","text":"Сохранение изменений"},{"letter":"D","text":"Остановка сервера"},{"letter":"E","text":"Изменение UI"}],"correct":"C","explanation":"Commit в Git фиксирует и сохраняет текущий набор изменений файлов в истории репозитория."},{"n":25,"question":"Для чего нужен Merge?","options":[{"letter":"A","text":"Удаление кода"},{"letter":"B","text":"Тестирование API"},{"letter":"C","text":"Объединение веток"},{"letter":"D","text":"Подключение сервера"},{"letter":"E","text":"Хранение данных"}],"correct":"C","explanation":"Merge нужен для объединения изменений из разных веток Git в одну, синхронизируя параллельную работу разных участников."},{"n":26,"question":"Что такое Branch?","options":[{"letter":"A","text":"Ошибка"},{"letter":"B","text":"API"},{"letter":"C","text":"Отдельная версия кода"},{"letter":"D","text":"UI"},{"letter":"E","text":"Сервер"}],"correct":"C","explanation":"Branch (ветка) представляет собой отдельную, независимую линию разработки кода, отделённую от основной версии проекта."},{"n":27,"question":"Цель Pull request?","options":[{"letter":"A","text":"Удаление кода"},{"letter":"B","text":"Вызов API"},{"letter":"C","text":"Запрос на объединение изменений"},{"letter":"D","text":"Отключение сервера"},{"letter":"E","text":"Хранение данных"}],"correct":"C","explanation":"Цель Pull request — формально запросить слияние изменений из одной ветки в другую, как правило, после code review от коллег."},{"n":28,"question":"Когда возникает Merge conflict?","options":[{"letter":"A","text":"Нет кода"},{"letter":"B","text":"Не работает API"},{"letter":"C","text":"При конфликтующих изменениях в одном файле"},{"letter":"D","text":"Изменение UI"},{"letter":"E","text":"При запуске сервера"}],"correct":"C","explanation":"Merge conflict возникает, когда в одном и том же файле есть конфликтующие, несовместимые изменения из разных веток, которые Git не может объединить автоматически."},{"n":29,"question":"Что такое Staging environment?","options":[{"letter":"A","text":"Production"},{"letter":"B","text":"Dev"},{"letter":"C","text":"Тестовая среда"},{"letter":"D","text":"API"},{"letter":"E","text":"UI"}],"correct":"C","explanation":"Staging environment — это тестовая среда, по конфигурации максимально приближенная к реальной production-среде, для финальной проверки перед релизом."},{"n":30,"question":"Что такое Production environment?","options":[{"letter":"A","text":"Тестовая среда"},{"letter":"B","text":"API среда"},{"letter":"C","text":"Реальная рабочая среда"},{"letter":"D","text":"UI режим"},{"letter":"E","text":"База кода"}],"correct":"C","explanation":"Production environment — это реальная рабочая среда, в которой приложением пользуются настоящие конечные пользователи."},{"n":31,"question":"Что такое Hotfix?","options":[{"letter":"A","text":"Плановое обновление"},{"letter":"B","text":"Изменение API"},{"letter":"C","text":"Срочное исправление ошибки"},{"letter":"D","text":"Обновление UI"},{"letter":"E","text":"Установка сервера"}],"correct":"C","explanation":"Hotfix — это срочное, внеплановое исправление критической ошибки, которое выпускается в production немедленно, минуя обычный цикл релизов."},{"n":32,"question":"Назначение Load balancer?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Создание UI"},{"letter":"C","text":"Распределение трафика"},{"letter":"D","text":"Удаление API"},{"letter":"E","text":"Хранение данных"}],"correct":"C","explanation":"Load balancer распределяет входящие запросы между несколькими серверами, предотвращая перегрузку одного из них и повышая общую устойчивость системы."},{"n":33,"question":"Что делает Reverse proxy?","options":[{"letter":"A","text":"Клиент"},{"letter":"B","text":"API"},{"letter":"C","text":"Перенаправляет запросы"},{"letter":"D","text":"UI"},{"letter":"E","text":"Код"}],"correct":"C","explanation":"Reverse proxy принимает входящие запросы от клиентов и перенаправляет их к нужному внутреннему серверу, скрывая структуру backend-инфраструктуры."},{"n":34,"question":"Для чего нужен SSL?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Создание API"},{"letter":"C","text":"Безопасность соединения"},{"letter":"D","text":"Создание UI"},{"letter":"E","text":"Остановка сервера"}],"correct":"C","explanation":"SSL обеспечивает безопасность соединения за счёт шифрования передаваемых между клиентом и сервером данных."},{"n":35,"question":"Что означает HTTPS?","options":[{"letter":"A","text":"HTTP"},{"letter":"B","text":"API"},{"letter":"C","text":"Безопасный протокол"},{"letter":"D","text":"UI"},{"letter":"E","text":"Код"}],"correct":"C","explanation":"HTTPS — это безопасный, зашифрованный протокол передачи данных, основанный на обычном HTTP с добавлением TLS/SSL-шифрования."},{"n":36,"question":"Что определяет Retention policy?","options":[{"letter":"A","text":"Время выполнения кода"},{"letter":"B","text":"API"},{"letter":"C","text":"Срок хранения данных"},{"letter":"D","text":"Сервер"},{"letter":"E","text":"UI"}],"correct":"C","explanation":"Retention policy определяет срок, в течение которого резервные копии данных должны храниться, прежде чем их можно безопасно удалить."},{"n":37,"question":"Что такое Snapshot backup?","options":[{"letter":"A","text":"Не полная резервная копия"},{"letter":"B","text":"Сохранение API"},{"letter":"C","text":"Состояние системы в определённый момент времени"},{"letter":"D","text":"Изменение кода"},{"letter":"E","text":"Удаление файлов"}],"correct":"C","explanation":"Snapshot backup фиксирует полное состояние системы на конкретный момент времени, позволяя позже восстановить именно это состояние."},{"n":38,"question":"Для чего нужен Failover?","options":[{"letter":"A","text":"Написание кода"},{"letter":"B","text":"Изменение UI"},{"letter":"C","text":"Переключение на резервную систему"},{"letter":"D","text":"Тестирование API"},{"letter":"E","text":"Удаление данных"}],"correct":"C","explanation":"Failover нужен для автоматического переключения нагрузки на резервную систему в случае отказа основной, чтобы минимизировать время простоя сервиса."},{"n":39,"question":"Что обеспечивает High availability?","options":[{"letter":"A","text":"Качество кода"},{"letter":"B","text":"Дизайн UI"},{"letter":"C","text":"Непрерывную работу системы"},{"letter":"D","text":"Скорость API"},{"letter":"E","text":"Размер файлов"}],"correct":"C","explanation":"High availability обеспечивает практически непрерывную, бесперебойную работу системы с минимальным временем простоя для пользователей."},{"n":40,"question":"Что такое Vertical scaling?","options":[{"letter":"A","text":"Увеличение количества серверов"},{"letter":"B","text":"Изменение API"},{"letter":"C","text":"Увеличение мощности одного сервера"},{"letter":"D","text":"Удаление кода"},{"letter":"E","text":"Изменение UI"}],"correct":"C","explanation":"Vertical scaling (вертикальное масштабирование) повышает производительность за счёт увеличения мощности (CPU, RAM) одного существующего сервера, а не добавления новых серверов."}]}]},"Java":{"subject":"Java","variants":[{"variant":1,"questions":[{"n":1,"question":"Что такое JVM?","options":[{"letter":"A","text":"Текстовый редактор для Java"},{"letter":"B","text":"Инструмент для компиляции Java-кода"},{"letter":"C","text":"Виртуальная машина Java, выполняющая байт-код"},{"letter":"D","text":"Система управления версиями"},{"letter":"E","text":"Инструмент сборки проектов"}],"correct":"C","explanation":"JVM (Java Virtual Machine) — виртуальная машина, которая выполняет скомпилированный байт-код (.class). Именно она обеспечивает принцип «Write once, run anywhere»."},{"n":2,"question":"Какой метод класса Scanner читает строку полностью?","options":[{"letter":"A","text":"readLine()"},{"letter":"B","text":"nextLine()"},{"letter":"C","text":"getString()"},{"letter":"D","text":"readString()"},{"letter":"E","text":"getLine()"}],"correct":"B","explanation":"Метод nextLine() читает всю строку целиком до символа переноса строки, включая пробелы. Метод next() остановился бы на первом пробеле."},{"n":3,"question":"Какой тип данных хранит значение true или false?","options":[{"letter":"A","text":"int"},{"letter":"B","text":"bit"},{"letter":"C","text":"boolean"},{"letter":"D","text":"flag"},{"letter":"E","text":"bool"}],"correct":"C","explanation":"Тип boolean хранит только два значения: true (истина) или false (ложь). Это единственный примитивный тип Java для логических значений."},{"n":4,"question":"Что означает автоматическое приведение типов (widening) в Java?","options":[{"letter":"A","text":"Преобразование большего типа в меньший с потерей данных"},{"letter":"B","text":"Автоматическое преобразование меньшего типа в больший без потери данных"},{"letter":"C","text":"Преобразование строки (String) в числовой тип"},{"letter":"D","text":"Создание нового пользовательского типа"},{"letter":"E","text":"Преобразование char в String"}],"correct":"B","explanation":"Расширяющее (widening) приведение происходит автоматически, когда меньший тип помещается в больший (byte → int → long → double) — данные не теряются."},{"n":5,"question":"Чему равно выражение 5 != 5?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"1"},{"letter":"D","text":"-1"},{"letter":"E","text":"null"}],"correct":"B","explanation":"Оператор != проверяет неравенство. Поскольку 5 == 5, значения равны, и выражение 5 != 5 возвращает false."},{"n":6,"question":"Какой синтаксис оператора if в Java?","options":[{"letter":"A","text":"if x > 0 { }"},{"letter":"B","text":"if (x > 0) { }"},{"letter":"C","text":"if x > 0 then { }"},{"letter":"D","text":"if [x > 0] { }"},{"letter":"E","text":"if: x > 0 { }"}],"correct":"B","explanation":"Синтаксис if в Java требует круглых скобок вокруг условия. Фигурные скобки технически необязательны для одной инструкции, но считаются хорошей практикой."},{"n":7,"question":"Какой будет результат: int x = 10; String s = (x > 5) ? \"big\" : \"small\";","options":[{"letter":"A","text":"null"},{"letter":"B","text":"small"},{"letter":"C","text":"big"},{"letter":"D","text":"true"},{"letter":"E","text":"10"}],"correct":"C","explanation":"Тернарный оператор вычисляет условие: x=10, 10 > 5 — истина, поэтому выбирается первое значение — \"big\"."},{"n":8,"question":"Что делает оператор continue внутри цикла?","options":[{"letter":"A","text":"Перезапускает цикл с начала"},{"letter":"B","text":"Завершает программу"},{"letter":"C","text":"Пропускает оставшуюся часть текущей итерации и переходит к следующей"},{"letter":"D","text":"Передаёт управление внешнему циклу"},{"letter":"E","text":"Полностью останавливает цикл"}],"correct":"C","explanation":"Оператор continue не завершает цикл, а пропускает только оставшуюся часть текущей итерации и сразу переходит к следующей проверке условия."},{"n":9,"question":"Как изменится x: int x = 10; while (x > 0) { x -= 3; }","options":[{"letter":"A","text":"x = 1"},{"letter":"B","text":"x = 3"},{"letter":"C","text":"x = -2"},{"letter":"D","text":"x = 10"},{"letter":"E","text":"x = 0"}],"correct":"C","explanation":"Цикл идёт: x=10, 7, 4, 1 (4 итерации, условие x>0 выполняется), потом x = 1−3 = −2. Теперь −2 > 0 ложь — цикл завершается, x = −2."},{"n":10,"question":"Как изменить шаг цикла for, чтобы i увеличивался на 2?","options":[{"letter":"A","text":"i * 2"},{"letter":"B","text":"i++2"},{"letter":"C","text":"i = i + 1 * 1"},{"letter":"D","text":"i += 2"},{"letter":"E","text":"step 2"}],"correct":"D","explanation":"Шаг цикла for (третья часть) управляет изменением счётчика. i += 2 увеличивает i на 2 при каждой итерации."},{"n":11,"question":"Какой метод класса Math возвращает модуль числа?","options":[{"letter":"A","text":"Math.mod()"},{"letter":"B","text":"Math.absolute()"},{"letter":"C","text":"Math.abs()"},{"letter":"D","text":"Math.value()"},{"letter":"E","text":"Math.positive()"}],"correct":"C","explanation":"Math.abs() возвращает абсолютное значение (модуль) числа, делая отрицательные числа положительными: Math.abs(−5) == 5."},{"n":12,"question":"Как получить случайное целое число от 0 до 9?","options":[{"letter":"A","text":"Math.random(10)"},{"letter":"B","text":"Math.random() * 10"},{"letter":"C","text":"(int) Math.random() % 10"},{"letter":"D","text":"(int)(Math.random() * 10)"},{"letter":"E","text":"Math.nextInt(10)"}],"correct":"D","explanation":"Math.random() возвращает double из [0.0, 1.0). Умножение на 10 даёт [0.0, 10.0), приведение (int) обрезает дробь → значения 0..9 включительно."},{"n":13,"question":"Что произойдёт при выходе за границы массива?","options":[{"letter":"A","text":"Вернётся null"},{"letter":"B","text":"Вернётся 0"},{"letter":"C","text":"Возникнет ошибка ArrayIndexOutOfBoundsException"},{"letter":"D","text":"Программа завершится без ошибки"},{"letter":"E","text":"Вернётся последний элемент"}],"correct":"C","explanation":"JVM выбрасывает ArrayIndexOutOfBoundsException при обращении к индексу, которого нет в массиве (< 0 или ≥ length). Это исключение времени выполнения."},{"n":14,"question":"Можно ли изменить размер массива после создания?","options":[{"letter":"A","text":"Да, через arr.resize()"},{"letter":"B","text":"Нет, размер массива фиксирован"},{"letter":"C","text":"Да, через Arrays.resize()"},{"letter":"D","text":"Да, просто добавив элемент"},{"letter":"E","text":"Да, начиная с Java 11"}],"correct":"B","explanation":"Массив в Java имеет фиксированный размер, заданный при создании через new. Для динамических коллекций переменного размера используют ArrayList."},{"n":15,"question":"Сколько вложенных циклов нужно для обхода двумерного массива?","options":[{"letter":"A","text":"1"},{"letter":"B","text":"2"},{"letter":"C","text":"3"},{"letter":"D","text":"Зависит от размера"},{"letter":"E","text":"4"}],"correct":"B","explanation":"Двумерный массив — это массив массивов. Для обхода всех элементов нужен внешний цикл по строкам и внутренний цикл по столбцам — итого 2 вложенных цикла."},{"n":16,"question":"Как получить длину строки s в Java?","options":[{"letter":"A","text":"s.size()"},{"letter":"B","text":"s.length()"},{"letter":"C","text":"len(s)"},{"letter":"D","text":"s.count()"},{"letter":"E","text":"String.length(s)"}],"correct":"B","explanation":"Метод length() у String возвращает количество символов. Важно: у массивов длина хранится в поле .length (без скобок), а у строк — это метод."},{"n":17,"question":"Как объединить строки \"Hello\" и \" World\"?","options":[{"letter":"A","text":"\"Hello\".add(\" World\")"},{"letter":"B","text":"\"Hello\" + \" World\" или \"Hello\".concat(\" World\")"},{"letter":"C","text":"String.join(\"Hello\", \" World\")"},{"letter":"D","text":"\"Hello\".append(\" World\")"},{"letter":"E","text":"merge(\"Hello\", \" World\")"}],"correct":"B","explanation":"Строки объединяются оператором + или методом concat(). Оба варианта возвращают новый объект String, так как строки в Java неизменяемы."},{"n":18,"question":"Какой класс реализует Set без сохранения порядка?","options":[{"letter":"A","text":"TreeSet"},{"letter":"B","text":"LinkedHashSet"},{"letter":"C","text":"HashSet"},{"letter":"D","text":"SortedSet"},{"letter":"E","text":"ArrayList"}],"correct":"C","explanation":"HashSet реализует интерфейс Set, хранит только уникальные элементы и не гарантирует какой-либо порядок. Основан на хэш-таблице."},{"n":19,"question":"Какой общий родительский интерфейс у List и Set?","options":[{"letter":"A","text":"Array"},{"letter":"B","text":"Map"},{"letter":"C","text":"Collection"},{"letter":"D","text":"Iterable"},{"letter":"E","text":"Comparable"}],"correct":"C","explanation":"Collection — корневой интерфейс иерархии коллекций. Оба интерфейса List и Set расширяют Collection, поэтому методы add(), size(), remove() доступны в обоих."},{"n":20,"question":"Что означает \"MM\" в DateTimeFormatter?","options":[{"letter":"A","text":"Год"},{"letter":"B","text":"Минуты"},{"letter":"C","text":"Месяц (двузначный)"},{"letter":"D","text":"Миллисекунды"},{"letter":"E","text":"Понедельник"}],"correct":"C","explanation":"В DateTimeFormatter: MM — месяц двумя цифрами (01–12), M — месяц без ведущего нуля, MMM — сокращённое название месяца."},{"n":21,"question":"Область видимости переменной, объявленной в методе?","options":[{"letter":"A","text":"Вся программа"},{"letter":"B","text":"В дочерних классах"},{"letter":"C","text":"Только внутри метода"},{"letter":"D","text":"Весь класс"},{"letter":"E","text":"Весь пакет"}],"correct":"C","explanation":"Локальная переменная, объявленная внутри метода, существует только в пределах этого метода и недоступна снаружи — это её область видимости (scope)."},{"n":22,"question":"Что будет, если в методе с типом int нет return?","options":[{"letter":"A","text":"Вернётся null"},{"letter":"B","text":"Ошибка компиляции"},{"letter":"C","text":"Вернётся 0"},{"letter":"D","text":"Программа аварийно завершится"},{"letter":"E","text":"Вернётся -1"}],"correct":"B","explanation":"Если метод объявлен с типом возврата int, компилятор требует возврата int-значения во всех путях выполнения. Отсутствие return приводит к ошибке компиляции."},{"n":23,"question":"С какого ключевого слова объявляется класс?","options":[{"letter":"A","text":"type"},{"letter":"B","text":"define"},{"letter":"C","text":"struct"},{"letter":"D","text":"class"},{"letter":"E","text":"object"}],"correct":"D","explanation":"Ключевое слово class начинает объявление класса в Java. По соглашению имена классов пишутся с заглавной буквы (PascalCase)."},{"n":24,"question":"Что будет, если в классе нет конструктора?","options":[{"letter":"A","text":"Нельзя создать объект"},{"letter":"B","text":"Нельзя инициализировать поля"},{"letter":"C","text":"Java автоматически добавит конструктор по умолчанию"},{"letter":"D","text":"Ошибка компиляции"},{"letter":"E","text":"Класс станет абстрактным"}],"correct":"C","explanation":"Если в классе не объявлено ни одного конструктора, компилятор автоматически добавляет конструктор по умолчанию (без параметров, с пустым телом)."},{"n":25,"question":"Может ли конструктор иметь возвращаемый тип?","options":[{"letter":"A","text":"Да, void"},{"letter":"B","text":"Да, тип класса"},{"letter":"C","text":"Нет"},{"letter":"D","text":"Да, любой примитивный тип"},{"letter":"E","text":"Да, только int"}],"correct":"C","explanation":"Конструктор — специальный элемент класса; у него нет возвращаемого типа (даже void). Его имя обязательно совпадает с именем класса."},{"n":26,"question":"Порядок модификаторов доступа (от самого закрытого к открытому)?","options":[{"letter":"A","text":"public → protected → private → default"},{"letter":"B","text":"private → default → protected → public"},{"letter":"C","text":"protected → private → public → default"},{"letter":"D","text":"default → private → public → protected"},{"letter":"E","text":"public → private → default → protected"}],"correct":"B","explanation":"Уровни доступа от самого закрытого к открытому: private (только класс) → default (пакет) → protected (пакет + подклассы) → public (везде)."},{"n":27,"question":"Сколько родительских классов может быть у класса в Java?","options":[{"letter":"A","text":"Неограниченно"},{"letter":"B","text":"Два"},{"letter":"C","text":"Один"},{"letter":"D","text":"Три"},{"letter":"E","text":"Зависит от версии"}],"correct":"C","explanation":"Java поддерживает только одиночное наследование классов (один extends). Множественное «наследование» поведения достигается через реализацию нескольких интерфейсов."},{"n":28,"question":"Основное отличие overloading и overriding?","options":[{"letter":"A","text":"Это одинаковые механизмы"},{"letter":"B","text":"Overriding — только для static"},{"letter":"C","text":"Overloading — только для конструкторов"},{"letter":"D","text":"Overloading — разные параметры в одном классе; overriding — изменение поведения метода в наследнике"},{"letter":"E","text":"Только для интерфейсов"}],"correct":"D","explanation":"Overloading — несколько методов с одинаковым именем, но разными параметрами в одном классе. Overriding — замена реализации наследуемого метода в подклассе."},{"n":29,"question":"Ключевое слово для абстрактного класса?","options":[{"letter":"A","text":"abstract"},{"letter":"B","text":"virtual"},{"letter":"C","text":"interface"},{"letter":"D","text":"base"},{"letter":"E","text":"prototype"}],"correct":"A","explanation":"Ключевое слово abstract используется как для объявления класса (abstract class), так и для методов без реализации внутри него."},{"n":30,"question":"Что такое интерфейс в Java?","options":[{"letter":"A","text":"Класс с private методами"},{"letter":"B","text":"Контракт методов, которые класс должен реализовать"},{"letter":"C","text":"Коллекция"},{"letter":"D","text":"Enum"},{"letter":"E","text":"Только static методы"}],"correct":"B","explanation":"Интерфейс в Java описывает контракт — набор методов, которые реализующий класс обязан предоставить. Это основа полиморфизма."},{"n":31,"question":"Зачем нужны интерфейсы?","options":[{"letter":"A","text":"Для констант"},{"letter":"B","text":"Для тестов"},{"letter":"C","text":"Для ускорения"},{"letter":"D","text":"Заменяют abstract класс"},{"letter":"E","text":"Для определения поведения и полиморфизма"}],"correct":"E","explanation":"Интерфейсы позволяют работать с разными объектами через единый тип, обеспечивая полиморфизм и слабую связанность кода."},{"n":32,"question":"Как объявить, что метод может выбросить исключение?","options":[{"letter":"A","text":"catch IOException"},{"letter":"B","text":"exception IOException"},{"letter":"C","text":"throws IOException"},{"letter":"D","text":"throw IOException"},{"letter":"E","text":"try IOException"}],"correct":"C","explanation":"Ключевое слово throws в сигнатуре метода указывает, какие проверяемые исключения метод может выбросить. Вызывающий код обязан их обработать."},{"n":33,"question":"Зачем переопределяют equals()?","options":[{"letter":"A","text":"Для ускорения JVM"},{"letter":"B","text":"Для массивов"},{"letter":"C","text":"Для вывода"},{"letter":"D","text":"Для сравнения объектов по содержимому"},{"letter":"E","text":"Для deep copy"}],"correct":"D","explanation":"Метод equals() по умолчанию сравнивает ссылки. Переопределяют его для сравнения объектов по содержимому полей (например, Person по имени и возрасту)."},{"n":34,"question":"Как получить значение из Map по ключу?","options":[{"letter":"A","text":"map.value(key)"},{"letter":"B","text":"map[key]"},{"letter":"C","text":"map.find(key)"},{"letter":"D","text":"map.fetch(key)"},{"letter":"E","text":"map.get(key)"}],"correct":"E","explanation":"Метод get(key) возвращает значение по ключу из Map. Если ключ не найден, возвращается null."},{"n":35,"question":"Что такое LinkedHashMap?","options":[{"letter":"A","text":"Сортирует по алфавиту"},{"letter":"B","text":"Сохраняет порядок добавления"},{"letter":"C","text":"Потокобезопасная версия"},{"letter":"D","text":"Массив"},{"letter":"E","text":"Только для String"}],"correct":"B","explanation":"LinkedHashMap расширяет HashMap, добавляя двусвязный список элементов. Благодаря ему порядок вставки сохраняется при итерации."},{"n":36,"question":"Как получить Iterator из коллекции?","options":[{"letter":"A","text":"getIterator()"},{"letter":"B","text":"iterator()"},{"letter":"C","text":"new Iterator()"},{"letter":"D","text":"Iterator.of()"},{"letter":"E","text":"iter()"}],"correct":"B","explanation":"Метод iterator() из интерфейса Iterable возвращает объект Iterator, предоставляющий методы hasNext() и next() для последовательного обхода коллекции."},{"n":37,"question":"Какой класс читает текстовый файл построчно?","options":[{"letter":"A","text":"FileReader"},{"letter":"B","text":"Scanner"},{"letter":"C","text":"BufferedReader"},{"letter":"D","text":"FileInputStream"},{"letter":"E","text":"TextReader"}],"correct":"C","explanation":"BufferedReader читает текстовые файлы эффективно благодаря буферизации. Метод readLine() возвращает строки по одной или null при достижении конца файла."},{"n":38,"question":"Можно ли использовать enum в switch?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да"},{"letter":"C","text":"Только Java 11+"},{"letter":"D","text":"Только if-else"},{"letter":"E","text":"Только числовой enum"}],"correct":"B","explanation":"Начиная с Java 5 константы enum можно использовать в switch в качестве меток case. Это делает код более читаемым и безопасным по типам."},{"n":39,"question":"Уровни логирования (от низкого к высокому)?","options":[{"letter":"A","text":"INFO, ERROR, DEBUG, WARN"},{"letter":"B","text":"LOG, PRINT, WARN, ERROR"},{"letter":"C","text":"TRACE, DEBUG, INFO, WARN, ERROR, FATAL"},{"letter":"D","text":"LOW, MED, HIGH, CRITICAL"},{"letter":"E","text":"DEBUG, INFO, ERROR"}],"correct":"C","explanation":"Стандартный порядок уровней (от наименее критичного к наиболее): TRACE → DEBUG → INFO → WARN → ERROR → FATAL. Настройка уровня фильтрует менее важные сообщения."},{"n":40,"question":"Когда лучше выполнять валидацию данных?","options":[{"letter":"A","text":"Сразу при получении данных"},{"letter":"B","text":"В конце"},{"letter":"C","text":"После обработки"},{"letter":"D","text":"Только в тестах"},{"letter":"E","text":"В finally"}],"correct":"A","explanation":"Данные нужно проверять сразу при получении (на входе метода или системы) — это принцип «fail fast». Так ошибка обнаруживается раньше и локализуется легче."}]},{"variant":2,"questions":[{"n":1,"question":"Какой файл содержит скомпилированный байт-код Java?","options":[{"letter":"A","text":".java"},{"letter":"B","text":".class"},{"letter":"C","text":".jar"},{"letter":"D","text":".exe"},{"letter":"E","text":".bin"}],"correct":"B","explanation":"Компилятор javac преобразует исходный .java-файл в .class-файл с байт-кодом. Именно .class выполняется JVM на любой поддерживаемой платформе."},{"n":2,"question":"В каких областях применяется Java?","options":[{"letter":"A","text":"Только для веб-сайтов и серверных приложений"},{"letter":"B","text":"Только для Android"},{"letter":"C","text":"В веб, мобильной и корпоративной разработке, Big Data и встроенных системах"},{"letter":"D","text":"Только для системного программирования"},{"letter":"E","text":"Только для скриптов"}],"correct":"C","explanation":"Java используется повсюду: серверная веб-разработка (Spring), Android, корпоративные системы (ERP, банки), обработка больших данных (Hadoop) и встроенные устройства."},{"n":3,"question":"Как объявляется константа в Java?","options":[{"letter":"A","text":"const int X = 5;"},{"letter":"B","text":"readonly int X = 5;"},{"letter":"C","text":"static int X = 5;"},{"letter":"D","text":"fixed int X = 5;"},{"letter":"E","text":"final int X = 5;"}],"correct":"E","explanation":"Модификатор final запрещает переприсвоение переменной после инициализации — она становится константой. По соглашению имена констант пишутся UPPER_CASE."},{"n":4,"question":"Какое значение по умолчанию у boolean-поля класса?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"0"},{"letter":"C","text":"null"},{"letter":"D","text":"false"},{"letter":"E","text":"undefined"}],"correct":"D","explanation":"Поля булевого типа в классе инициализируются значением false по умолчанию. Аналогично: int → 0, double → 0.0, объекты → null."},{"n":5,"question":"Что делает оператор ++?","options":[{"letter":"A","text":"Удваивает значение"},{"letter":"B","text":"Увеличивает на 1"},{"letter":"C","text":"Уменьшает на 1"},{"letter":"D","text":"Складывает числа"},{"letter":"E","text":"Возводит в степень"}],"correct":"B","explanation":"Оператор ++ увеличивает значение переменной на 1. Префиксная (++x) форма возвращает новое значение, постфиксная (x++) — старое."},{"n":6,"question":"Что делает блок else в конструкции if-else?","options":[{"letter":"A","text":"Повторно проверяет условие"},{"letter":"B","text":"Пропускает if"},{"letter":"C","text":"Проверяет второе условие"},{"letter":"D","text":"Завершает программу"},{"letter":"E","text":"Выполняется, если условие if ложно"}],"correct":"E","explanation":"Блок else выполняется, когда условие оператора if ложно (false), обеспечивая альтернативную ветку выполнения."},{"n":7,"question":"Обязательно ли использовать фигурные скобки, если в if только одна строка?","options":[{"letter":"A","text":"Да, всегда"},{"letter":"B","text":"Нет, не обязательно"},{"letter":"C","text":"Только для else"},{"letter":"D","text":"Только для вложенных условий"},{"letter":"E","text":"Зависит от версии Java"}],"correct":"B","explanation":"Фигурные скобки синтаксически необязательны при одной инструкции в теле if, однако их отсутствие — распространённый источник ошибок при последующих изменениях кода."},{"n":8,"question":"Что будет, если условие while всегда true и нет break?","options":[{"letter":"A","text":"Ошибка"},{"letter":"B","text":"Java остановит цикл"},{"letter":"C","text":"Выполнится 10 раз"},{"letter":"D","text":"Бесконечный цикл"},{"letter":"E","text":"Код не скомпилируется"}],"correct":"D","explanation":"Если условие while (condition) всегда true и нет break/return, цикл выполняется бесконечно. Это называется бесконечным циклом — частая причина зависания программы."},{"n":9,"question":"Как выйти из вложенного цикла с помощью метки (label)?","options":[{"letter":"A","text":"return"},{"letter":"B","text":"exit"},{"letter":"C","text":"break label"},{"letter":"D","text":"stop label"},{"letter":"E","text":"continue outer"}],"correct":"C","explanation":"Именованная метка перед циклом позволяет прервать именно тот цикл через break label; — это единственный способ выйти из нескольких вложенных циклов сразу."},{"n":10,"question":"Что произойдёт, если в for (;; ) нет условия?","options":[{"letter":"A","text":"Ошибка компиляции"},{"letter":"B","text":"Бесконечный цикл"},{"letter":"C","text":"Цикл не выполнится"},{"letter":"D","text":"Выполнится один раз"},{"letter":"E","text":"Выполнится 100 раз"}],"correct":"B","explanation":"В цикле for (;;) все три части опциональны. Отсутствующее условие трактуется как true — цикл становится бесконечным."},{"n":11,"question":"Что возвращает Math.sqrt(16)?","options":[{"letter":"A","text":"4"},{"letter":"B","text":"2.0"},{"letter":"C","text":"8.0"},{"letter":"D","text":"256.0"},{"letter":"E","text":"4.0"}],"correct":"E","explanation":"Math.sqrt(16) возвращает квадратный корень числа типа double. √16 = 4.0."},{"n":12,"question":"Что возвращает Math.min(5, 3)?","options":[{"letter":"A","text":"3"},{"letter":"B","text":"5"},{"letter":"C","text":"8"},{"letter":"D","text":"2"},{"letter":"E","text":"15"}],"correct":"A","explanation":"Math.min() возвращает меньшее из двух аргументов. Math.min(5, 3) = 3."},{"n":13,"question":"Как инициализировать массив значениями?","options":[{"letter":"A","text":"int[] arr = {new 1, 2, 3};"},{"letter":"B","text":"int[] arr = {1, 2, 3};"},{"letter":"C","text":"int[] arr = new int[]{1; 2; 3};"},{"letter":"D","text":"int[] arr = [1, 2, 3];"},{"letter":"E","text":"int arr[] = new {1, 2, 3};"}],"correct":"B","explanation":"Инициализатор массива {1, 2, 3} — краткая форма для одновременного объявления и заполнения. Компилятор сам определяет размер по количеству элементов."},{"n":14,"question":"Как объявить пустой массив String размером 3?","options":[{"letter":"A","text":"String array = new String(3);"},{"letter":"B","text":"String array[] = String[3];"},{"letter":"C","text":"String[] array = new String{3};"},{"letter":"D","text":"String[3] array = new String[];"},{"letter":"E","text":"String[] array = new String[3];"}],"correct":"E","explanation":"new String[3] создаёт массив из трёх элементов типа String, каждый из которых по умолчанию равен null."},{"n":15,"question":"Как посчитать сумму всех элементов int[][] arr?","options":[{"letter":"A","text":"arr.sum()"},{"letter":"B","text":"двойной цикл for-each"},{"letter":"C","text":"Arrays.sum(arr)"},{"letter":"D","text":"arr.total()"},{"letter":"E","text":"Math.sum(arr)"}],"correct":"B","explanation":"Для суммирования всех элементов int[][] используют двойной for-each: внешний перебирает строки (int[] row), внутренний — элементы каждой строки."},{"n":16,"question":"Как получить символ строки по индексу i?","options":[{"letter":"A","text":"s[i]"},{"letter":"B","text":"s.get(i)"},{"letter":"C","text":"s.getChar(i)"},{"letter":"D","text":"s.charAt[i]"},{"letter":"E","text":"s.charAt(i)"}],"correct":"E","explanation":"charAt(i) возвращает символ типа char по индексу i в строке. Индексация начинается с 0."},{"n":17,"question":"Можно ли изменить String после создания?","options":[{"letter":"A","text":"Да, через setChar()"},{"letter":"B","text":"Нет, он неизменяемый"},{"letter":"C","text":"Да, через индекс"},{"letter":"D","text":"Да, через методы"},{"letter":"E","text":"Да, с Java 11"}],"correct":"B","explanation":"String в Java является иммутабельным (неизменяемым) объектом. Операции вроде concat() или replace() создают новый объект, а не изменяют существующий."},{"n":18,"question":"Как получить размер коллекции?","options":[{"letter":"A","text":"length"},{"letter":"B","text":"length()"},{"letter":"C","text":"size()"},{"letter":"D","text":"count()"},{"letter":"E","text":"total()"}],"correct":"C","explanation":"В отличие от массивов (поле .length), для коллекций используется метод size(), возвращающий текущее количество элементов."},{"n":19,"question":"Как пройтись по ArrayList через for-each?","options":[{"letter":"A","text":"обычный for"},{"letter":"B","text":"for (String element : list)"},{"letter":"C","text":"foreach element in list"},{"letter":"D","text":"list.forEach(element)"},{"letter":"E","text":"while"}],"correct":"B","explanation":"Расширенный цикл for-each вида for (String element : list) последовательно перебирает все элементы коллекции без управления индексом вручную."},{"n":20,"question":"Как получить год из LocalDate?","options":[{"letter":"A","text":"getYear()"},{"letter":"B","text":"date.year"},{"letter":"C","text":"date.year()"},{"letter":"D","text":"LocalDate.getYear()"},{"letter":"E","text":"date.YEAR"}],"correct":"A","explanation":"LocalDate.getYear() возвращает год в виде int. Аналогичные методы: getMonthValue() (месяц), getDayOfMonth() (день)."},{"n":21,"question":"Как правильно вызвать метод greet()?","options":[{"letter":"A","text":"call greet()"},{"letter":"B","text":"invoke greet()"},{"letter":"C","text":"method greet()"},{"letter":"D","text":"execute greet()"},{"letter":"E","text":"greet()"}],"correct":"E","explanation":"Метод без параметров вызывается по его имени с пустыми круглыми скобками: greet();. Скобки обязательны — без них это было бы обращение к полю."},{"n":22,"question":"Что такое класс в Java?","options":[{"letter":"A","text":"Функция"},{"letter":"B","text":"Шаблон для создания объектов"},{"letter":"C","text":"Примитивный тип"},{"letter":"D","text":"Набор методов"},{"letter":"E","text":"Переменная"}],"correct":"B","explanation":"Класс — это шаблон (blueprint) для создания объектов. Он определяет набор полей (состояние) и методов (поведение) для всех своих экземпляров."},{"n":23,"question":"Что такое static поле?","options":[{"letter":"A","text":"Неизменяемое"},{"letter":"B","text":"Общее для всех объектов"},{"letter":"C","text":"Фиксированного типа"},{"letter":"D","text":"Только для чтения"},{"letter":"E","text":"Только для наследников"}],"correct":"B","explanation":"Static-поле принадлежит классу, а не конкретному объекту. Оно общее для всех экземпляров и доступно через имя класса."},{"n":24,"question":"Что делает static у метода?","options":[{"letter":"A","text":"Делает неизменяемым"},{"letter":"B","text":"Позволяет вызывать без объекта"},{"letter":"C","text":"Ограничивает доступ"},{"letter":"D","text":"Автоматически запускается"},{"letter":"E","text":"Запрещает override"}],"correct":"B","explanation":"Статический метод можно вызвать без создания объекта: ClassName.method(). Он не имеет доступа к нестатическим полям и методам (this недоступен)."},{"n":25,"question":"Что такое перегрузка конструктора?","options":[{"letter":"A","text":"Наследование"},{"letter":"B","text":"Несколько конструкторов с разными параметрами"},{"letter":"C","text":"Override"},{"letter":"D","text":"Статический вызов"},{"letter":"E","text":"Анонимный класс"}],"correct":"B","explanation":"Перегрузка конструктора — наличие нескольких конструкторов с разными списками параметров. Это позволяет создавать объект разными способами."},{"n":26,"question":"Может ли top-level класс быть private?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Нет"},{"letter":"C","text":"Да с Java 11"},{"letter":"D","text":"Только abstract"},{"letter":"E","text":"Только inner"}],"correct":"B","explanation":"Top-level классы (не вложенные) могут иметь только модификаторы public или package-private (без модификатора). Модификатор private для них недопустим."},{"n":27,"question":"Что наследует дочерний класс?","options":[{"letter":"A","text":"Только public методы"},{"letter":"B","text":"Все доступные public и protected нестатические поля и методы"},{"letter":"C","text":"Конструкторы"},{"letter":"D","text":"Всё включая private"},{"letter":"E","text":"Только поля"}],"correct":"B","explanation":"Дочерний класс наследует все public и protected нестатические поля и методы родителя. Private-члены не наследуются напрямую, но доступны через getter/setter."},{"n":28,"question":"Что такое dynamic dispatch?","options":[{"letter":"A","text":"Тип определяется на этапе компиляции"},{"letter":"B","text":"Overloading"},{"letter":"C","text":"super вызов"},{"letter":"D","text":"Компиляция в байт-код"},{"letter":"E","text":"Выбор метода во время выполнения"}],"correct":"E","explanation":"Dynamic dispatch — механизм выбора переопределённого метода во время выполнения по реальному типу объекта, а не по типу ссылки. Это основа полиморфизма."},{"n":29,"question":"Что такое абстрактный метод?","options":[{"letter":"A","text":"Без параметров"},{"letter":"B","text":"Без реализации"},{"letter":"C","text":"static"},{"letter":"D","text":"private"},{"letter":"E","text":"Всегда null"}],"correct":"B","explanation":"Абстрактный метод объявляется с ключевым словом abstract и не имеет тела. Подкласс обязан предоставить реализацию всех абстрактных методов."},{"n":30,"question":"Ключевое слово для интерфейса?","options":[{"letter":"A","text":"abstract"},{"letter":"B","text":"class"},{"letter":"C","text":"interface"},{"letter":"D","text":"contract"},{"letter":"E","text":"protocol"}],"correct":"C","explanation":"Интерфейс объявляется ключевым словом interface, а реализуется классом через ключевое слово implements."},{"n":31,"question":"Что такое exception?","options":[{"letter":"A","text":"Переменная"},{"letter":"B","text":"Событие, нарушающее выполнение программы"},{"letter":"C","text":"Метод"},{"letter":"D","text":"Оператор"},{"letter":"E","text":"Ключевое слово"}],"correct":"B","explanation":"Исключение (exception) — объект, описывающий ошибку или нештатную ситуацию. Когда оно выбрасывается, нормальный поток выполнения прерывается."},{"n":32,"question":"Как создать своё исключение?","options":[{"letter":"A","text":"Наследовать Exception или RuntimeException"},{"letter":"B","text":"implement"},{"letter":"C","text":"@Exception"},{"letter":"D","text":"exception"},{"letter":"E","text":"throws()"}],"correct":"A","explanation":"Пользовательское исключение создаётся наследованием от Exception (проверяемое, требует try-catch или throws) или RuntimeException (непроверяемое)."},{"n":33,"question":"Какой метод нужно переопределить вместе с equals()?","options":[{"letter":"A","text":"toString()"},{"letter":"B","text":"clone()"},{"letter":"C","text":"compareTo()"},{"letter":"D","text":"hashCode()"},{"letter":"E","text":"finalize()"}],"correct":"D","explanation":"Контракт Java гласит: если два объекта равны по equals(), их hashCode() должны совпадать. Нарушение этого правила ломает HashMap, HashSet и подобные структуры."},{"n":34,"question":"Что возвращает map.get(key), если ключа нет?","options":[{"letter":"A","text":"Exception"},{"letter":"B","text":"null"},{"letter":"C","text":"0"},{"letter":"D","text":"\"\""},{"letter":"E","text":"-1"}],"correct":"B","explanation":"Если ключ отсутствует в Map, метод get() возвращает null. Это важно учитывать, чтобы избежать NullPointerException при использовании результата."},{"n":35,"question":"Что такое Generics?","options":[{"letter":"A","text":"Числовые типы"},{"letter":"B","text":"Универсальный тип"},{"letter":"C","text":"Параметризация типов для безопасности"},{"letter":"D","text":"Замена наследования"},{"letter":"E","text":"Массивы"}],"correct":"C","explanation":"Generics позволяют параметризовать классы и методы типами (например, List<String>). Это обеспечивает проверку типов на этапе компиляции, а не во время выполнения."},{"n":36,"question":"Какой метод Iterator проверяет наличие следующего элемента?","options":[{"letter":"A","text":"hasElement()"},{"letter":"B","text":"isNext()"},{"letter":"C","text":"next()"},{"letter":"D","text":"peek()"},{"letter":"E","text":"hasNext()"}],"correct":"E","explanation":"Метод hasNext() итератора возвращает true, если в коллекции остались непройденные элементы. Используется в паре с next() для безопасного обхода."},{"n":37,"question":"Какой класс используется для записи в текстовый файл?","options":[{"letter":"A","text":"FileOutput"},{"letter":"B","text":"BufferedWriter или PrintWriter"},{"letter":"C","text":"Только FileWriter"},{"letter":"D","text":"TextWriter"},{"letter":"E","text":"OutputStreamWriter"}],"correct":"B","explanation":"BufferedWriter и PrintWriter используются для записи текста в файл. BufferedWriter буферизирует вывод; PrintWriter удобен благодаря методам println()."},{"n":38,"question":"Что умеет enum?","options":[{"letter":"A","text":"Может иметь поля, конструкторы и методы"},{"letter":"B","text":"Только строки"},{"letter":"C","text":"Наследует классы"},{"letter":"D","text":"Меняет тип"},{"letter":"E","text":"Только константы"}],"correct":"A","explanation":"Enum в Java — полноценный класс. Он может иметь поля (например, числовой код), конструктор и методы, расширяя возможности обычных именованных констант."},{"n":39,"question":"Какой уровень логирования для отладки?","options":[{"letter":"A","text":"INFO"},{"letter":"B","text":"DEBUG"},{"letter":"C","text":"WARN"},{"letter":"D","text":"ERROR"},{"letter":"E","text":"TRACE"}],"correct":"B","explanation":"Уровень DEBUG предназначен для подробных отладочных сообщений. В production его обычно отключают, чтобы не засорять журналы."},{"n":40,"question":"Как проверить, что строка не null и не пустая?","options":[{"letter":"A","text":"str == \"\""},{"letter":"B","text":"str.notEmpty()"},{"letter":"C","text":"str.length > 0"},{"letter":"D","text":"!str.equals(null)"},{"letter":"E","text":"str != null && !str.isEmpty()"}],"correct":"E","explanation":"Проверка str != null гарантирует отсутствие NullPointerException, а !str.isEmpty() — что строка содержит хотя бы один символ. Порядок важен из-за short-circuit &&."}]},{"variant":3,"questions":[{"n":1,"question":"Какая команда используется для компиляции Java-программы через командную строку?","options":[{"letter":"A","text":"java"},{"letter":"B","text":"javac"},{"letter":"C","text":"run"},{"letter":"D","text":"execute"},{"letter":"E","text":"compile"}],"correct":"B","explanation":"Команда javac (Java Compiler) компилирует исходный .java-файл в байт-код (.class). Для запуска уже скомпилированного кода используется команда java."},{"n":2,"question":"Что такое IDE?","options":[{"letter":"A","text":"Язык программирования"},{"letter":"B","text":"Интегрированная среда разработки"},{"letter":"C","text":"Компилятор Java"},{"letter":"D","text":"Тип данных"},{"letter":"E","text":"Система контроля версий"}],"correct":"B","explanation":"IDE (Integrated Development Environment) — интегрированная среда разработки, объединяющая редактор, компилятор, отладчик и другие инструменты в одном приложении."},{"n":3,"question":"Какой тип данных занимает 8 байт и хранит большие целые числа?","options":[{"letter":"A","text":"int"},{"letter":"B","text":"short"},{"letter":"C","text":"long"},{"letter":"D","text":"bigint"},{"letter":"E","text":"integer"}],"correct":"C","explanation":"Тип long занимает 8 байт и хранит целые числа от −2⁶³ до 2⁶³−1. Используется, когда диапазона int (4 байта) недостаточно."},{"n":4,"question":"Что такое явное приведение типов (casting) в Java?","options":[{"letter":"A","text":"Автоматическое преобразование без участия программиста"},{"letter":"B","text":"Явное преобразование типа через оператор (тип)"},{"letter":"C","text":"Создание нового объекта"},{"letter":"D","text":"Копирование значения"},{"letter":"E","text":"Объявление константы"}],"correct":"B","explanation":"Сужающее (narrowing) приведение в Java требует явного указания целевого типа в скобках: (int) myDouble. Оно может привести к потере данных."},{"n":5,"question":"Чему будет равно x после выполнения: int x = 5; x += 3;","options":[{"letter":"A","text":"5"},{"letter":"B","text":"3"},{"letter":"C","text":"8"},{"letter":"D","text":"15"},{"letter":"E","text":"2"}],"correct":"C","explanation":"Составной оператор += прибавляет правый операнд к переменной и сохраняет результат: x += 3 эквивалентно x = x + 3. При x=5 результат равен 8."},{"n":6,"question":"Как записывается вложенное условие?","options":[{"letter":"A","text":"if(a) and if(b)"},{"letter":"B","text":"if(a) { if(b) { } }"},{"letter":"C","text":"if(a && b) только так"},{"letter":"D","text":"nested if(a, b)"},{"letter":"E","text":"if(a) else if(b) только"}],"correct":"B","explanation":"Вложенное условие записывается как if внутри другого if. Внутренний блок выполняется только при истинности обоих условий."},{"n":7,"question":"Что означает else if в Java?","options":[{"letter":"A","text":"Вложенный else"},{"letter":"B","text":"Дополнительная проверка условия после else"},{"letter":"C","text":"Часть switch"},{"letter":"D","text":"Тип цикла"},{"letter":"E","text":"Аналог default"}],"correct":"B","explanation":"else if добавляет дополнительную проверку после предыдущего условия. Если первый if ложен, проверяется else if; и так далее по цепочке."},{"n":8,"question":"Как правильно записывается цикл do-while?","options":[{"letter":"A","text":"do while (x < 10) { }"},{"letter":"B","text":"do { } while (x < 10);"},{"letter":"C","text":"while { } do (x < 10);"},{"letter":"D","text":"repeat { } until (x < 10);"},{"letter":"E","text":"loop { } while (x < 10);"}],"correct":"B","explanation":"В цикле do-while тело выполняется до проверки условия, а условие стоит после do { ... } while (condition);. Это гарантирует хотя бы одно выполнение."},{"n":9,"question":"Когда do-while эффективнее while?","options":[{"letter":"A","text":"Когда условие всегда true"},{"letter":"B","text":"Когда тело должно выполниться хотя бы один раз"},{"letter":"C","text":"Когда известно количество итераций"},{"letter":"D","text":"Когда нужен бесконечный цикл"},{"letter":"E","text":"Когда сложное условие"}],"correct":"B","explanation":"do-while удобен, когда тело цикла должно сработать хотя бы один раз независимо от условия — например, при запросе ввода от пользователя."},{"n":10,"question":"Чему будет равно i после цикла: for (int i = 10; i > 0; i -= 3)","options":[{"letter":"A","text":"0"},{"letter":"B","text":"1"},{"letter":"C","text":"-2"},{"letter":"D","text":"3"},{"letter":"E","text":"10"}],"correct":"C","explanation":"Цикл for (int i=10; i>0; i-=3) идёт: 10, 7, 4, 1, −2. При i=1 условие i>0 истинно, i уменьшается до −2; теперь −2>0 ложно — цикл завершается, i=−2."},{"n":11,"question":"Какой метод Math возвращает большее из двух чисел?","options":[{"letter":"A","text":"Math.biggest()"},{"letter":"B","text":"Math.max()"},{"letter":"C","text":"Math.greater()"},{"letter":"D","text":"Math.top()"},{"letter":"E","text":"Math.large()"}],"correct":"B","explanation":"Math.max(a, b) возвращает большее из двух чисел. Для минимума используется Math.min(a, b)."},{"n":12,"question":"Что представляет Math.E?","options":[{"letter":"A","text":"π"},{"letter":"B","text":"sqrt(2)"},{"letter":"C","text":"Основание натурального логарифма e ≈ 2.718"},{"letter":"D","text":"Константа Эйлера–Маскерони"},{"letter":"E","text":"max int"}],"correct":"C","explanation":"Math.E — константа, содержащая основание натурального логарифма e ≈ 2.71828. Используется в математических расчётах вместе с Math.log()."},{"n":13,"question":"Какой индекс у последнего элемента массива длины n?","options":[{"letter":"A","text":"n"},{"letter":"B","text":"n + 1"},{"letter":"C","text":"n - 1"},{"letter":"D","text":"n / 2"},{"letter":"E","text":"0"}],"correct":"C","explanation":"Индексы массива в Java начинаются с 0. Поэтому последний элемент массива длиной n находится по индексу n−1."},{"n":14,"question":"Что выведет код: int[] a = {5, 10, 15}; System.out.println(a[1]);","options":[{"letter":"A","text":"5"},{"letter":"B","text":"15"},{"letter":"C","text":"10"},{"letter":"D","text":"0"},{"letter":"E","text":"1"}],"correct":"C","explanation":"Индексация начинается с 0: a[0]=5, a[1]=10, a[2]=15. System.out.println(a[1]) выведет 10."},{"n":15,"question":"Что такое главная диагональ квадратной матрицы?","options":[{"letter":"A","text":"Элементы arr[i][i]"},{"letter":"B","text":"Первая строка"},{"letter":"C","text":"Последний столбец"},{"letter":"D","text":"Чётные индексы"},{"letter":"E","text":"Центральная строка"}],"correct":"A","explanation":"Главная диагональ квадратной матрицы — элементы, у которых номер строки равен номеру столбца: arr[0][0], arr[1][1], arr[2][2] и т.д. (arr[i][i])."},{"n":16,"question":"Как сравнить строки по содержимому?","options":[{"letter":"A","text":"compare()"},{"letter":"B","text":"=="},{"letter":"C","text":"equals()"},{"letter":"D","text":"compareTo()"},{"letter":"E","text":"same()"}],"correct":"C","explanation":"Метод equals() сравнивает строки по содержимому. Оператор == сравнивает ссылки, что может дать неверный результат для разных объектов с одинаковым текстом."},{"n":17,"question":"Что делает s.toLowerCase()?","options":[{"letter":"A","text":"Делает строку в верхнем регистре"},{"letter":"B","text":"Делает строку в нижнем регистре"},{"letter":"C","text":"Удаляет символы"},{"letter":"D","text":"Делает первый символ маленьким"},{"letter":"E","text":"Считает символы"}],"correct":"B","explanation":"Метод toLowerCase() возвращает новую строку, где все символы преобразованы в нижний регистр. Исходная строка при этом не изменяется (String иммутабелен)."},{"n":18,"question":"Как удалить элемент из List по индексу?","options":[{"letter":"A","text":"delete"},{"letter":"B","text":"remove"},{"letter":"C","text":"erase"},{"letter":"D","text":"clear"},{"letter":"E","text":"pop"}],"correct":"B","explanation":"Метод remove(int index) удаляет элемент из List по указанному индексу. Метод remove(Object o) удаляет первое вхождение объекта."},{"n":19,"question":"Преимущество ArrayList над массивом?","options":[{"letter":"A","text":"Всегда быстрее"},{"letter":"B","text":"Динамический размер"},{"letter":"C","text":"Без указания типа"},{"letter":"D","text":"Хранит разные типы"},{"letter":"E","text":"Меньше памяти"}],"correct":"B","explanation":"ArrayList обеспечивает динамический размер в отличие от обычного массива. При добавлении элементов внутренний массив автоматически расширяется."},{"n":20,"question":"Как сравнить две даты?","options":[{"letter":"A","text":"isBefore()"},{"letter":"B","text":"<"},{"letter":"C","text":"isAfter()"},{"letter":"D","text":"before()"},{"letter":"E","text":"compare()"}],"correct":"A","explanation":"LocalDate.isBefore(otherDate) возвращает true, если дата раньше переданной. Также есть isAfter() и isEqual() для сравнения дат."},{"n":21,"question":"Что такое рекурсия?","options":[{"letter":"A","text":"Вызов из другого класса"},{"letter":"B","text":"Перегрузка"},{"letter":"C","text":"Несколько return"},{"letter":"D","text":"Метод вызывает сам себя"},{"letter":"E","text":"Наследование"}],"correct":"D","explanation":"Рекурсия — способ решения задачи, при котором метод вызывает сам себя с изменёнными аргументами. Обязательно должно быть базовое условие остановки."},{"n":22,"question":"Что такое объект в Java?","options":[{"letter":"A","text":"Шаблон"},{"letter":"B","text":"Метод"},{"letter":"C","text":"Экземпляр класса"},{"letter":"D","text":"Поле"},{"letter":"E","text":"Тип данных"}],"correct":"C","explanation":"Объект — это конкретный экземпляр класса в памяти, созданный оператором new. Один класс может породить множество объектов."},{"n":23,"question":"Что означает this?","options":[{"letter":"A","text":"Ссылка на родителя"},{"letter":"B","text":"Указатель на следующий объект"},{"letter":"C","text":"Вызов static метода"},{"letter":"D","text":"Наследование"},{"letter":"E","text":"Ссылка на текущий объект"}],"correct":"E","explanation":"Ключевое слово this — ссылка на текущий объект, для которого вызван метод или конструктор. Используется для разрешения конфликта имён и цепочки конструкторов."},{"n":24,"question":"Можно ли использовать this в static методе?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Только в конструкторе"},{"letter":"C","text":"Нет"},{"letter":"D","text":"Только для private"},{"letter":"E","text":"Да с Java 11"}],"correct":"C","explanation":"Ключевое слово this не существует в контексте статического метода, поскольку static-метод принадлежит классу, а не конкретному объекту."},{"n":25,"question":"Где должен вызываться super()?","options":[{"letter":"A","text":"Где угодно"},{"letter":"B","text":"В первой строке конструктора"},{"letter":"C","text":"В конце"},{"letter":"D","text":"После инициализации"},{"letter":"E","text":"Только в abstract"}],"correct":"B","explanation":"Вызов super() в конструкторе должен быть первой инструкцией, иначе компилятор выдаст ошибку. Он вызывает конструктор родительского класса."},{"n":26,"question":"Как называется ограничение доступа к данным?","options":[{"letter":"A","text":"Полиморфизм"},{"letter":"B","text":"Наследование"},{"letter":"C","text":"Инкапсуляция"},{"letter":"D","text":"Абстракция"},{"letter":"E","text":"Агрегация"}],"correct":"C","explanation":"Инкапсуляция — принцип ООП, ограничивающий прямой доступ к данным объекта. Поля делают private, предоставляя доступ через публичные геттеры и сеттеры."},{"n":27,"question":"Что делает super.method()?","options":[{"letter":"A","text":"Создаёт новый объект"},{"letter":"B","text":"Вызывает метод родителя"},{"letter":"C","text":"Удаляет метод"},{"letter":"D","text":"Игнорирует полиморфизм"},{"letter":"E","text":"Ошибка"}],"correct":"B","explanation":"Вызов super.method() явно обращается к реализации метода в родительском классе, даже если метод переопределён в текущем."},{"n":28,"question":"Что выполнится: Animal a = new Dog(); a.speak();","options":[{"letter":"A","text":"Animal.speak()"},{"letter":"B","text":"Dog.speak()"},{"letter":"C","text":"Ошибка компиляции"},{"letter":"D","text":"Runtime error"},{"letter":"E","text":"Object метод"}],"correct":"B","explanation":"Благодаря полиморфизму вызывается метод speak() реального объекта (Dog), несмотря на то что ссылка объявлена типом Animal. Это dynamic dispatch."},{"n":29,"question":"Что должен сделать наследник abstract класса?","options":[{"letter":"A","text":"Ничего"},{"letter":"B","text":"Реализовать все abstract методы или тоже быть abstract"},{"letter":"C","text":"Добавить поля"},{"letter":"D","text":"Вызвать super()"},{"letter":"E","text":"Сделать методы static"}],"correct":"B","explanation":"Конкретный подкласс должен реализовать все абстрактные методы родителя, иначе он сам обязан быть объявлен как abstract."},{"n":30,"question":"Какое ключевое слово для реализации интерфейса?","options":[{"letter":"A","text":"extends"},{"letter":"B","text":"implements"},{"letter":"C","text":"uses"},{"letter":"D","text":"with"},{"letter":"E","text":"inherits"}],"correct":"B","explanation":"Ключевое слово implements используется классом для реализации одного или нескольких интерфейсов: class Dog implements Animal."},{"n":31,"question":"Какая конструкция обрабатывает исключения?","options":[{"letter":"A","text":"if-else"},{"letter":"B","text":"try-catch"},{"letter":"C","text":"switch"},{"letter":"D","text":"while"},{"letter":"E","text":"for"}],"correct":"B","explanation":"Конструкция try { } catch (Exception e) { } перехватывает исключения: код в try выполняется, а при выброске исключения управление переходит в соответствующий catch."},{"n":32,"question":"Что такое stack trace?","options":[{"letter":"A","text":"Список классов"},{"letter":"B","text":"Последовательность вызовов методов при ошибке"},{"letter":"C","text":"Все исключения"},{"letter":"D","text":"Структура данных"},{"letter":"E","text":"Порядок загрузки"}],"correct":"B","explanation":"Stack trace — это список вызовов методов от точки возникновения исключения до текущего места. Он помогает найти источник ошибки при отладке."},{"n":33,"question":"Что такое hashCode()?","options":[{"letter":"A","text":"Случайное число"},{"letter":"B","text":"Хэш-код объекта"},{"letter":"C","text":"Уникальный ID"},{"letter":"D","text":"Версия"},{"letter":"E","text":"Адрес памяти"}],"correct":"B","explanation":"hashCode() возвращает целое число — хэш-код объекта. Он используется в хэш-таблицах (HashMap, HashSet) для быстрого поиска объектов."},{"n":34,"question":"Какой класс Map не гарантирует порядок?","options":[{"letter":"A","text":"TreeMap"},{"letter":"B","text":"LinkedHashMap"},{"letter":"C","text":"HashMap"},{"letter":"D","text":"SortedMap"},{"letter":"E","text":"ArrayMap"}],"correct":"C","explanation":"HashMap не гарантирует никакого порядка элементов. Для сохранения порядка вставки используют LinkedHashMap, для сортировки — TreeMap."},{"n":35,"question":"Как объявить список строк?","options":[{"letter":"A","text":"List list = new ArrayList(String);"},{"letter":"B","text":"ArrayList list = List.of();"},{"letter":"C","text":"List list = new ArrayList(String);"},{"letter":"D","text":"List list = new ArrayList<>();"},{"letter":"E","text":"List list = new ArrayList();"}],"correct":"D","explanation":"List<String> объявляет список строк. Параметр типа <String> указывается в угловых скобках и ограничивает допустимые элементы."},{"n":36,"question":"Как безопасно удалить элемент при итерации?","options":[{"letter":"A","text":"remove()"},{"letter":"B","text":"iterator.remove()"},{"letter":"C","text":"Копия"},{"letter":"D","text":"for-each + remove"},{"letter":"E","text":"Нельзя"}],"correct":"B","explanation":"Удаление элементов коллекции во время обычной итерации вызывает ConcurrentModificationException. Безопасный способ — использовать iterator.remove()."},{"n":37,"question":"Для чего java.nio?","options":[{"letter":"A","text":"I/O и работа с файлами/буферами"},{"letter":"B","text":"Ошибки"},{"letter":"C","text":"UI"},{"letter":"D","text":"Потоки"},{"letter":"E","text":"Только сеть"}],"correct":"A","explanation":"Пакет java.nio (New I/O) предоставляет неблокирующий I/O, работу с буферами, каналами и файловой системой через классы Files, Path, Paths и другие."},{"n":38,"question":"Что такое unit-тестирование?","options":[{"letter":"A","text":"Всё приложение"},{"letter":"B","text":"Отдельные методы/классы"},{"letter":"C","text":"UI"},{"letter":"D","text":"Нагрузка"},{"letter":"E","text":"Сеть"}],"correct":"B","explanation":"Unit-тестирование проверяет отдельные методы или классы в изоляции от остальной системы. Цель — убедиться, что каждый модуль работает правильно сам по себе."},{"n":39,"question":"Что делает assertNull(object) в JUnit?","options":[{"letter":"A","text":"Удаляет объект"},{"letter":"B","text":"Проверяет что не null"},{"letter":"C","text":"Создаёт null"},{"letter":"D","text":"Проверяет что null"},{"letter":"E","text":"Бросает исключение"}],"correct":"D","explanation":"assertNull(object) проверяет, что переданный объект равен null. Если объект не null, тест считается проваленным."},{"n":40,"question":"Что такое рефакторинг?","options":[{"letter":"A","text":"Переписать код"},{"letter":"B","text":"Улучшение структуры без изменения поведения"},{"letter":"C","text":"Только оптимизация"},{"letter":"D","text":"Добавление функций"},{"letter":"E","text":"Тестирование"}],"correct":"B","explanation":"Рефакторинг — улучшение внутренней структуры кода (читаемость, устранение дублирования, упрощение логики) без изменения внешнего поведения программы."}]},{"variant":4,"questions":[{"n":1,"question":"Какая команда используется для запуска скомпилированной Java-программы?","options":[{"letter":"A","text":"java"},{"letter":"B","text":"javac"},{"letter":"C","text":"jrun"},{"letter":"D","text":"start"},{"letter":"E","text":"execute"}],"correct":"A","explanation":"Команда java запускает уже скомпилированный байт-код (.class) с помощью JVM. Команда javac — это компилятор исходного кода в байт-код."},{"n":2,"question":"Какое расширение у исходного файла Java?","options":[{"letter":"A","text":".java"},{"letter":"B","text":".class"},{"letter":"C","text":".jv"},{"letter":"D","text":".src"},{"letter":"E","text":".code"}],"correct":"A","explanation":"Исходный код Java сохраняется в файлах с расширением .java. Компилятор javac преобразует их в .class-файлы с байт-кодом."},{"n":3,"question":"Как правильно объявить переменную типа int со значением 10?","options":[{"letter":"A","text":"int = 10;"},{"letter":"B","text":"int x = 10;"},{"letter":"C","text":"integer x = 10;"},{"letter":"D","text":"x int = 10;"},{"letter":"E","text":"var int x = 10;"}],"correct":"B","explanation":"Объявление переменной включает тип, имя и необязательное начальное значение: int x = 10;. Это объявляет целочисленную переменную x со значением 10."},{"n":4,"question":"Какой оператор выполняет деление с остатком?","options":[{"letter":"A","text":"/"},{"letter":"B","text":"//"},{"letter":"C","text":"%"},{"letter":"D","text":"mod"},{"letter":"E","text":"div"}],"correct":"C","explanation":"Оператор % (остаток от деления, modulo) возвращает остаток от целочисленного деления: 10 % 3 = 1. Часто используется для проверки чётности числа."},{"n":5,"question":"Чему равно выражение true && false?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"1"},{"letter":"D","text":"0"},{"letter":"E","text":"null"}],"correct":"B","explanation":"Логический оператор && возвращает true только если оба операнда истинны. true && false = false, поскольку второй операнд ложен."},{"n":6,"question":"Какой оператор используется для выбора одного из нескольких вариантов?","options":[{"letter":"A","text":"select"},{"letter":"B","text":"choose"},{"letter":"C","text":"switch"},{"letter":"D","text":"case"},{"letter":"E","text":"when"}],"correct":"C","explanation":"Оператор switch позволяет выбрать одну из нескольких ветвей выполнения в зависимости от значения выражения. Удобная альтернатива цепочке if-else if."},{"n":7,"question":"Какое ключевое слово завершает обработку case в switch?","options":[{"letter":"A","text":"stop"},{"letter":"B","text":"end"},{"letter":"C","text":"break"},{"letter":"D","text":"exit"},{"letter":"E","text":"return"}],"correct":"C","explanation":"Ключевое слово break в case завершает обработку данного case и выходит из switch. Без break выполнение «проваливается» в следующий case (fall-through)."},{"n":8,"question":"Сколько раз выполнится тело цикла: int x = 5; while (x > 10) { x++; }","options":[{"letter":"A","text":"1"},{"letter":"B","text":"5"},{"letter":"C","text":"0"},{"letter":"D","text":"10"},{"letter":"E","text":"бесконечно"}],"correct":"C","explanation":"Условие x > 10 для x=5 сразу ложно, поэтому тело цикла while не выполнится ни разу. Цикл выполняется 0 раз."},{"n":9,"question":"Какой правильный синтаксис цикла for в Java?","options":[{"letter":"A","text":"for (x < 10) { }"},{"letter":"B","text":"for (int i = 0; i < 10; i++) { }"},{"letter":"C","text":"for int i = 0; i < 10; i++ { }"},{"letter":"D","text":"for (i in 0..10) { }"},{"letter":"E","text":"for i = 0 to 10 { }"}],"correct":"B","explanation":"Синтаксис цикла for: for (инициализация; условие; шаг) { тело }. Все три части разделяются точкой с запятой."},{"n":10,"question":"Можно ли объявить несколько переменных в инициализации for?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да, например: for (int i = 0, j = 10; i < j; i++, j--)"},{"letter":"C","text":"Только для массивов"},{"letter":"D","text":"Нельзя одного типа"},{"letter":"E","text":"Только в Java 11+"}],"correct":"B","explanation":"В инициализирующей части цикла for можно объявить несколько переменных одного типа через запятую, а также указать несколько выражений в шаге."},{"n":11,"question":"Что возвращает Math.pow(2, 10)?","options":[{"letter":"A","text":"20"},{"letter":"B","text":"12"},{"letter":"C","text":"1024.0"},{"letter":"D","text":"2.0"},{"letter":"E","text":"512.0"}],"correct":"C","explanation":"Math.pow(base, exp) возводит base в степень exp и возвращает результат типа double. Math.pow(2, 10) = 1024.0."},{"n":12,"question":"Что возвращает Math.abs(-7)?","options":[{"letter":"A","text":"-7"},{"letter":"B","text":"0"},{"letter":"C","text":"7"},{"letter":"D","text":"49"},{"letter":"E","text":"-1"}],"correct":"C","explanation":"Math.abs(x) возвращает абсолютное значение числа. Math.abs(−7) = 7."},{"n":13,"question":"Какое значение по умолчанию у элементов int[]?","options":[{"letter":"A","text":"null"},{"letter":"B","text":"1"},{"letter":"C","text":"-1"},{"letter":"D","text":"0"},{"letter":"E","text":"случайное"}],"correct":"D","explanation":"При создании int[] все элементы инициализируются нулём (0) по умолчанию. Для boolean — false, для ссылочных типов — null."},{"n":14,"question":"Как объявить двумерный массив 3×4?","options":[{"letter":"A","text":"int[3,4] arr;"},{"letter":"B","text":"int arr[3][4];"},{"letter":"C","text":"int[][] arr = new int[3][4];"},{"letter":"D","text":"int[3][4] arr = new int;"},{"letter":"E","text":"int[][] arr = new int{3, 4};"}],"correct":"C","explanation":"Двумерный массив 3×4 объявляется как int[][] arr = new int[3][4]: 3 строки, 4 столбца, всего 12 элементов."},{"n":15,"question":"Как создать \"рваный\" (jagged) массив?","options":[{"letter":"A","text":"int[][] a = new int[3,2,4];"},{"letter":"B","text":"Создать строки разной длины вручную"},{"letter":"C","text":"int[][] a = new int[3][];"},{"letter":"D","text":"Невозможно"},{"letter":"E","text":"Только фиксированный"}],"correct":"B","explanation":"«Рваный» (jagged) массив — двумерный массив, строки которого имеют разную длину. Сначала создаётся массив строк, затем каждая строка задаётся отдельно."},{"n":16,"question":"Что делает s.toUpperCase()?","options":[{"letter":"A","text":"Делает маленькие буквы"},{"letter":"B","text":"Возвращает длину"},{"letter":"C","text":"Делает все буквы заглавными"},{"letter":"D","text":"Только первый символ"},{"letter":"E","text":"Убирает пробелы"}],"correct":"C","explanation":"Метод toUpperCase() возвращает новую строку, где все символы переведены в верхний регистр. Исходная строка не изменяется."},{"n":17,"question":"Как проверить, что строка начинается с \"Hello\"?","options":[{"letter":"A","text":"startsWith()"},{"letter":"B","text":"beginsWith()"},{"letter":"C","text":"starts()"},{"letter":"D","text":"firstChar()"},{"letter":"E","text":"indexOf == 0"}],"correct":"A","explanation":"Метод startsWith(prefix) возвращает true, если строка начинается с указанного префикса. Аналогично endsWith() проверяет окончание."},{"n":18,"question":"Как проверить наличие элемента в коллекции?","options":[{"letter":"A","text":"has"},{"letter":"B","text":"find"},{"letter":"C","text":"includes"},{"letter":"D","text":"contains"},{"letter":"E","text":"exists"}],"correct":"D","explanation":"Метод contains(element) возвращает true, если коллекция содержит указанный элемент. Использует equals() для сравнения."},{"n":19,"question":"Какой класс используется для даты и времени в современной Java?","options":[{"letter":"A","text":"Date"},{"letter":"B","text":"Calendar"},{"letter":"C","text":"LocalDate"},{"letter":"D","text":"TimeStamp"},{"letter":"E","text":"DateTime"}],"correct":"C","explanation":"LocalDate из пакета java.time (Java 8+) — предпочтительный класс для работы с датами без времени. Старый java.util.Date устарел."},{"n":20,"question":"Что делает LocalDate.of(2024, 1, 15)?","options":[{"letter":"A","text":"Текущая дата"},{"letter":"B","text":"Создаёт 15 января 2024"},{"letter":"C","text":"Добавляет 15 дней"},{"letter":"D","text":"День недели"},{"letter":"E","text":"Меняет время"}],"correct":"B","explanation":"LocalDate.of(год, месяц, день) создаёт объект даты для указанного дня. LocalDate.of(2024, 1, 15) — 15 января 2024 года."},{"n":21,"question":"Как передаются объекты в методы в Java?","options":[{"letter":"A","text":"через ref"},{"letter":"B","text":"нельзя"},{"letter":"C","text":"через указатели"},{"letter":"D","text":"pointer"},{"letter":"E","text":"передаётся ссылка по значению"}],"correct":"E","explanation":"В Java объекты передаются в методы по значению ссылки: метод получает копию ссылки на тот же объект, а не сам объект или его копию."},{"n":22,"question":"Как создать объект Dog?","options":[{"letter":"A","text":"create Dog"},{"letter":"B","text":"Dog d;"},{"letter":"C","text":"Dog d = new Dog();"},{"letter":"D","text":"new Dog d;"},{"letter":"E","text":"Dog.create()"}],"correct":"C","explanation":"Для создания объекта класса используется оператор new: Dog d = new Dog(); Это выделяет память и вызывает конструктор."},{"n":23,"question":"Зачем this в конструкторе?","options":[{"letter":"A","text":"Вызов родителя"},{"letter":"B","text":"Доступ к другому объекту"},{"letter":"C","text":"Создание объекта"},{"letter":"D","text":"Вызов static"},{"letter":"E","text":"Различать поле и параметр"}],"correct":"E","explanation":"В конструкторе this.field используется для различения одноимённых параметра и поля класса: this.name = name присваивает параметр name полю name."},{"n":24,"question":"Что такое конструктор?","options":[{"letter":"A","text":"Метод, вызываемый при создании объекта"},{"letter":"B","text":"static метод"},{"letter":"C","text":"Удаляет объект"},{"letter":"D","text":"void метод"},{"letter":"E","text":"Наследуемый"}],"correct":"A","explanation":"Конструктор — это специальный метод, автоматически вызываемый при создании объекта через new. Он инициализирует состояние нового объекта."},{"n":25,"question":"Как инициализировать поля в конструкторе?","options":[{"letter":"A","text":"Через setter"},{"letter":"B","text":"final"},{"letter":"C","text":"static"},{"letter":"D","text":"this.field = value"},{"letter":"E","text":"Нельзя"}],"correct":"D","explanation":"Внутри конструктора поля инициализируются присваиванием через this: this.field = value; Это стандартный способ задания начального состояния объекта."},{"n":26,"question":"Может ли наследник обращаться к private полю родителя напрямую?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Через super"},{"letter":"C","text":"Нет"},{"letter":"D","text":"Если в одном пакете"},{"letter":"E","text":"Через this"}],"correct":"C","explanation":"Модификатор private делает поле или метод недоступным за пределами класса, в котором оно объявлено. Подклассы не могут обратиться к нему напрямую."},{"n":27,"question":"Какой базовый класс у всех классов в Java?","options":[{"letter":"A","text":"Base"},{"letter":"B","text":"Root"},{"letter":"C","text":"Object"},{"letter":"D","text":"Class"},{"letter":"E","text":"Main"}],"correct":"C","explanation":"Object — неявный суперкласс всех классов в Java. Он предоставляет методы equals(), hashCode(), toString(), getClass() и другие."},{"n":28,"question":"Можно ли override static метод?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Да в пакете"},{"letter":"C","text":"Нет (method hiding)"},{"letter":"D","text":"Только public"},{"letter":"E","text":"С Java 11"}],"correct":"C","explanation":"В полиморфизме переопределённый метод вызывается по реальному типу объекта во время выполнения. Метод с модификатором final переопределить нельзя."},{"n":29,"question":"Может ли abstract класс иметь обычные методы?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да"},{"letter":"C","text":"Только без полей"},{"letter":"D","text":"Только static"},{"letter":"E","text":"Только конструкторы"}],"correct":"B","explanation":"Абстрактные классы обеспечивают частичную реализацию и не могут быть инстанциированы напрямую. Для создания объектов нужен конкретный (не abstract) подкласс."},{"n":30,"question":"Может ли класс реализовывать несколько интерфейсов?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да"},{"letter":"C","text":"Только Java 11"},{"letter":"D","text":"Только в пакете"},{"letter":"E","text":"Только два"}],"correct":"B","explanation":"Все методы, объявленные в интерфейсе без модификатора (до Java 8), неявно являются public abstract. Начиная с Java 8, интерфейсы могут содержать default-методы."},{"n":31,"question":"Что делает finally?","options":[{"letter":"A","text":"Только при ошибке"},{"letter":"B","text":"Только при нормальном завершении"},{"letter":"C","text":"Всегда выполняется"},{"letter":"D","text":"Бросает исключение"},{"letter":"E","text":"Останавливает программу"}],"correct":"C","explanation":"Оператор throw явно выбрасывает исключение: throw new IOException(\"message\");. Управление немедленно передаётся в ближайший совместимый catch-блок."},{"n":32,"question":"Можно ли обрабатывать несколько исключений в одном catch?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да через |"},{"letter":"C","text":"Только Java 11"},{"letter":"D","text":"Только если один класс"},{"letter":"E","text":"Нет"}],"correct":"B","explanation":"NullPointerException возникает при обращении к членам объекта через ссылку, равную null: вызов метода, обращение к полю и т.п."},{"n":33,"question":"Если a.equals(b) == true, что должно быть?","options":[{"letter":"A","text":"a == b"},{"letter":"B","text":"hashCode одинаковый"},{"letter":"C","text":"toString одинаковый"},{"letter":"D","text":"null"},{"letter":"E","text":"ничего"}],"correct":"B","explanation":"При переопределении toString() обычно возвращают строку вида \"ClassName{field1=value1, field2=value2}\", описывающую состояние объекта."},{"n":34,"question":"Какой Map сортирует ключи?","options":[{"letter":"A","text":"HashMap"},{"letter":"B","text":"LinkedHashMap"},{"letter":"C","text":"TreeMap"},{"letter":"D","text":"SortedHashMap"},{"letter":"E","text":"OrderedMap"}],"correct":"C","explanation":"Метод containsKey(key) возвращает true, если указанный ключ присутствует в Map. Аналогично containsValue(value) проверяет значение."},{"n":35,"question":"Что означает <T> в generics?","options":[{"letter":"A","text":"String"},{"letter":"B","text":"Тип параметра"},{"letter":"C","text":"Только числа"},{"letter":"D","text":"Text"},{"letter":"E","text":"Object"}],"correct":"B","explanation":"Главное преимущество Generics — перенос проверки типов с времени выполнения на время компиляции, что исключает ClassCastException в runtime."},{"n":36,"question":"Что произойдёт при изменении коллекции во время for-each?","options":[{"letter":"A","text":"ArrayIndexOutOfBounds"},{"letter":"B","text":"ConcurrentModificationException"},{"letter":"C","text":"IllegalState"},{"letter":"D","text":"IteratorException"},{"letter":"E","text":"ModificationException"}],"correct":"B","explanation":"Optional — обёртка, явно выражающая возможное отсутствие значения. Это вынуждает явно обрабатывать «пустой» случай, снижая риск NullPointerException."},{"n":37,"question":"Как создать Path?","options":[{"letter":"A","text":"new Path"},{"letter":"B","text":"Paths.get()"},{"letter":"C","text":"Path.of() или Paths.get()"},{"letter":"D","text":"File.path"},{"letter":"E","text":"File.toPath"}],"correct":"C","explanation":"Files.readAllLines(path) из java.nio.file читает все строки файла и возвращает List<String>. Удобно для небольших текстовых файлов."},{"n":38,"question":"Для чего JUnit?","options":[{"letter":"A","text":"Компиляция"},{"letter":"B","text":"Тестирование"},{"letter":"C","text":"Зависимости"},{"letter":"D","text":"UI"},{"letter":"E","text":"Деплой"}],"correct":"B","explanation":"Аннотация @Test из JUnit 5 помечает метод как тестовый. JUnit автоматически находит и запускает все методы с этой аннотацией."},{"n":39,"question":"Какая аннотация выполняется перед каждым тестом?","options":[{"letter":"A","text":"@Before"},{"letter":"B","text":"@Init"},{"letter":"C","text":"@BeforeEach"},{"letter":"D","text":"@Setup"},{"letter":"E","text":"@PreTest"}],"correct":"C","explanation":"Code coverage — процент строк (или ветвей) кода, выполняемых при прогоне тестов. Высокое покрытие снижает риск незамеченных ошибок."},{"n":40,"question":"Что делает break в цикле?","options":[{"letter":"A","text":"Пропускает итерацию"},{"letter":"B","text":"Полностью выходит"},{"letter":"C","text":"Увеличивает счётчик"},{"letter":"D","text":"Перезапускает"},{"letter":"E","text":"Создаёт цикл"}],"correct":"B","explanation":"Коллекция (Collection) — это объект-контейнер, хранящий группу элементов. Java Collections Framework включает List, Set, Queue, Map и их реализации."}]},{"variant":5,"questions":[{"n":1,"question":"Что входит в состав JDK?","options":[{"letter":"A","text":"Только JVM"},{"letter":"B","text":"Только компилятор javac"},{"letter":"C","text":"JVM, компилятор javac и инструменты разработки"},{"letter":"D","text":"Только текстовый редактор"},{"letter":"E","text":"Только стандартные библиотеки"}],"correct":"C","explanation":"Класс System содержит стандартные потоки ввода-вывода: System.in (консольный ввод), System.out (стандартный вывод), System.err (вывод ошибок)."},{"n":2,"question":"Что делает System.out.println()?","options":[{"letter":"A","text":"Читает данные с клавиатуры"},{"letter":"B","text":"Выводит данные в консоль и переводит строку"},{"letter":"C","text":"Компилирует программу"},{"letter":"D","text":"Открывает диалог"},{"letter":"E","text":"Записывает в файл"}],"correct":"B","explanation":"System.out.println() выводит значение и добавляет перенос строки. System.out.print() выводит без переноса строки."},{"n":3,"question":"Что произойдёт при попытке изменить final переменную?","options":[{"letter":"A","text":"Значение изменится"},{"letter":"B","text":"Будет предупреждение"},{"letter":"C","text":"Ошибка компиляции"},{"letter":"D","text":"Исключение"},{"letter":"E","text":"Значение станет null"}],"correct":"C","explanation":"Тип double занимает 8 байт и хранит числа с плавающей точкой двойной точности в соответствии со стандартом IEEE 754."},{"n":4,"question":"Чему равно 10 / 3 (целочисленное деление)?","options":[{"letter":"A","text":"3.33"},{"letter":"B","text":"4"},{"letter":"C","text":"3"},{"letter":"D","text":"3.0"},{"letter":"E","text":"0"}],"correct":"C","explanation":"Оператор == для чисел сравнивает значения (3 == 3 → true). Для объектов == сравнивает ссылки; для содержательного сравнения нужен equals()."},{"n":5,"question":"Какой оператор проверяет \"меньше или равно\"?","options":[{"letter":"A","text":">="},{"letter":"B","text":"<"},{"letter":"C","text":"<="},{"letter":"D","text":"=<"},{"letter":"E","text":"!>"}],"correct":"C","explanation":"Оператор <= возвращает true, если левый операнд меньше или равен правому: 3 <= 5 → true, 5 <= 5 → true."},{"n":6,"question":"Что будет, если в case нет break?","options":[{"letter":"A","text":"Программа завершится"},{"letter":"B","text":"Игнорируется"},{"letter":"C","text":"Ошибка"},{"letter":"D","text":"Выполнится default"},{"letter":"E","text":"Переход к следующему case (fall-through)"}],"correct":"E","explanation":"В switch без break управление «проваливается» в следующий case (fall-through). Это иногда используется намеренно, но чаще является ошибкой."},{"n":7,"question":"Что выведет код: if (false) System.out.println(\"A\"); else System.out.println(\"B\");","options":[{"letter":"A","text":"A"},{"letter":"B","text":"AB"},{"letter":"C","text":"B"},{"letter":"D","text":"null"},{"letter":"E","text":"ничего"}],"correct":"C","explanation":"Условие if (false) всегда ложно, поэтому блок if не выполняется. Выполняется блок else: печатается 'B'."},{"n":8,"question":"Что выведет программа: int i = 0; do { i++; } while (i < 0); System.out.println(i);","options":[{"letter":"A","text":"1"},{"letter":"B","text":"0"},{"letter":"C","text":"-1"},{"letter":"D","text":"ничего"},{"letter":"E","text":"бесконечный цикл"}],"correct":"A","explanation":"do-while выполняет тело один раз до проверки условия. i начинается с 0, тело i++ делает i=1, условие i<0 ложно — цикл завершается. i=1."},{"n":9,"question":"Какая часть for выполняется один раз перед началом?","options":[{"letter":"A","text":"Инициализация"},{"letter":"B","text":"Тело"},{"letter":"C","text":"Шаг"},{"letter":"D","text":"Условие"},{"letter":"E","text":"Все"}],"correct":"A","explanation":"В цикле for инициализирующая часть (например int i=0) выполняется ровно один раз перед первой итерацией."},{"n":10,"question":"Как называется переменная счётчика цикла?","options":[{"letter":"A","text":"counter"},{"letter":"B","text":"index"},{"letter":"C","text":"flag"},{"letter":"D","text":"pointer"},{"letter":"E","text":"accumulator"}],"correct":"A","explanation":"Переменная-счётчик цикла традиционно называется counter, index, i, j или k. Имя counter явно описывает назначение переменной."},{"n":11,"question":"Какой метод округляет число до ближайшего целого?","options":[{"letter":"A","text":"truncate"},{"letter":"B","text":"fix"},{"letter":"C","text":"round"},{"letter":"D","text":"ceil"},{"letter":"E","text":"floor"}],"correct":"C","explanation":"Math.round(x) округляет число до ближайшего целого: значения ≥ .5 округляются вверх. Возвращает long (для double) или int (для float)."},{"n":12,"question":"Как вычислить натуральный логарифм в Java?","options":[{"letter":"A","text":"Math.ln()"},{"letter":"B","text":"Math.log()"},{"letter":"C","text":"Math.log10()"},{"letter":"D","text":"Math.natural()"},{"letter":"E","text":"Math.ln10()"}],"correct":"B","explanation":"Math.log(x) вычисляет натуральный логарифм (по основанию e). Для десятичного логарифма используют Math.log10(x)."},{"n":13,"question":"Какой цикл удобнее для обхода массива?","options":[{"letter":"A","text":"while"},{"letter":"B","text":"do-while"},{"letter":"C","text":"for или for-each"},{"letter":"D","text":"switch"},{"letter":"E","text":"только for"}],"correct":"C","explanation":"Цикл for (индексный) или for-each удобны для обхода массива. for-each не позволяет менять элементы, но проще для чтения."},{"n":14,"question":"Как обратиться к элементу [2 строка, 3 столбец]?","options":[{"letter":"A","text":"arr[3][2]"},{"letter":"B","text":"arr[1][2]"},{"letter":"C","text":"arr[2][3]"},{"letter":"D","text":"arr[2][1]"},{"letter":"E","text":"arr[3][1]"}],"correct":"B","explanation":"Индексы начинаются с 0. Строка 2 — это arr[1], столбец 3 — это arr[...][2]. Элемент «2-я строка, 3-й столбец» — arr[1][2]."},{"n":15,"question":"Чему равно arr[0][0] в int[2][3]?","options":[{"letter":"A","text":"1"},{"letter":"B","text":"0"},{"letter":"C","text":"null"},{"letter":"D","text":"-1"},{"letter":"E","text":"ошибка"}],"correct":"B","explanation":"По умолчанию все элементы int[][] инициализируются нулём, поэтому arr[0][0] в new int[2][3] равен 0."},{"n":16,"question":"Что делает s.trim()?","options":[{"letter":"A","text":"Удаляет все пробелы"},{"letter":"B","text":"Удаляет пробелы в начале и конце"},{"letter":"C","text":"Укорачивает строку"},{"letter":"D","text":"Делит строку"},{"letter":"E","text":"Делает lowercase"}],"correct":"B","explanation":"Метод trim() удаляет пробельные символы (пробелы, табуляцию, переносы строк) с начала и конца строки. Пробелы внутри строки не затрагиваются."},{"n":17,"question":"Как заменить все \"a\" на \"b\"?","options":[{"letter":"A","text":"change"},{"letter":"B","text":"set"},{"letter":"C","text":"replace"},{"letter":"D","text":"swap"},{"letter":"E","text":"String.replace"}],"correct":"C","explanation":"Метод replace(old, new) заменяет все вхождения подстроки old на new и возвращает новую строку. String — иммутабелен, оригинал не изменяется."},{"n":18,"question":"Что будет, если добавить дубликат в HashSet?","options":[{"letter":"A","text":"Ошибка"},{"letter":"B","text":"Добавится дважды"},{"letter":"C","text":"Не добавится"},{"letter":"D","text":"Заменит"},{"letter":"E","text":"Превратится в List"}],"correct":"C","explanation":"HashSet не допускает дублирующихся элементов. При попытке добавить уже существующий элемент метод add() возвращает false и коллекция не изменяется."},{"n":19,"question":"Как получить текущую дату?","options":[{"letter":"A","text":"new Date()"},{"letter":"B","text":"System.getDate()"},{"letter":"C","text":"Date.today()"},{"letter":"D","text":"Calendar.getDate()"},{"letter":"E","text":"LocalDate.now()"}],"correct":"E","explanation":"LocalDate.now() возвращает текущую дату без времени, используя системные часы. LocalDateTime.now() возвращает дату и время."},{"n":20,"question":"Что такое метод?","options":[{"letter":"A","text":"Тип данных"},{"letter":"B","text":"Именованный блок кода"},{"letter":"C","text":"Переменная"},{"letter":"D","text":"Ключевое слово"},{"letter":"E","text":"Exception"}],"correct":"B","explanation":"Метод — именованный блок кода, выполняющий определённую задачу. Он может принимать параметры и возвращать значение."},{"n":21,"question":"Что вернёт add(3,5)?","options":[{"letter":"A","text":"\"35\""},{"letter":"B","text":"8"},{"letter":"C","text":"5"},{"letter":"D","text":"3"},{"letter":"E","text":"0"}],"correct":"B","explanation":"Если метод add(int a, int b) возвращает int и тело — return a + b, то add(3, 5) вернёт 3 + 5 = 8."},{"n":22,"question":"Что такое инкапсуляция?","options":[{"letter":"A","text":"Связь классов"},{"letter":"B","text":"Несколько объектов"},{"letter":"C","text":"Наследование"},{"letter":"D","text":"Объединение данных и методов + ограничение доступа"},{"letter":"E","text":"Многопоточность"}],"correct":"D","explanation":"Инкапсуляция объединяет данные (поля) и методы работы с ними в одном классе, ограничивая внешний доступ к внутреннему состоянию через private."},{"n":23,"question":"Что делает this при вызове конструктора?","options":[{"letter":"A","text":"Вызывает другой конструктор текущего класса"},{"letter":"B","text":"Создаёт объект"},{"letter":"C","text":"Вызывает родителя"},{"letter":"D","text":"Копирует объект"},{"letter":"E","text":"Вызывает main"}],"correct":"A","explanation":"Вызов this() внутри конструктора — это вызов другого конструктора этого же класса. Должен быть первой строкой и позволяет переиспользовать логику."},{"n":24,"question":"Отличие конструктора от метода?","options":[{"letter":"A","text":"static"},{"letter":"B","text":"Имя = имя класса, нет return"},{"letter":"C","text":"Вызывается вручную"},{"letter":"D","text":"Нет параметров"},{"letter":"E","text":"Вызывается в конце программы"}],"correct":"B","explanation":"Конструктор отличается от метода: имя совпадает с именем класса, нет возвращаемого типа. Вызывается автоматически при new, а не явно."},{"n":25,"question":"Что делает private?","options":[{"letter":"A","text":"Доступ всем"},{"letter":"B","text":"Только внутри класса"},{"letter":"C","text":"Доступ наследникам"},{"letter":"D","text":"Доступ в пакете"},{"letter":"E","text":"Запрещает наследование"}],"correct":"B","explanation":"Модификатор private ограничивает область видимости только текущим классом. Это основа инкапсуляции."},{"n":26,"question":"Что такое accessor method?","options":[{"letter":"A","text":"static"},{"letter":"B","text":"конструктор"},{"letter":"C","text":"getter/setter"},{"letter":"D","text":"abstract"},{"letter":"E","text":"final"}],"correct":"C","explanation":"Accessor methods — геттеры (get) и сеттеры (set). Геттер читает значение private-поля, сеттер — задаёт его с возможной валидацией."},{"n":27,"question":"Что означает IS-A?","options":[{"letter":"A","text":"Класс содержит другой"},{"letter":"B","text":"Равенство"},{"letter":"C","text":"Интерфейс"},{"letter":"D","text":"Наследник — это тип родителя"},{"letter":"E","text":"Один пакет"}],"correct":"D","explanation":"Отношение IS-A описывает наследование: «Собака — это Животное» означает, что Dog extends Animal. Подкласс может использоваться везде, где ожидается суперкласс."},{"n":28,"question":"Можно ли override static?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Нет"},{"letter":"C","text":"Да в пакете"},{"letter":"D","text":"Только public"},{"letter":"E","text":"С Java 11"}],"correct":"B","explanation":"Статические методы принадлежат классу, а не объекту. Переопределение (override) — механизм объектов, поэтому static-методы переопределить нельзя (только скрыть)."},{"n":29,"question":"Можно ли создать объект abstract класса?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Да с Java 11"},{"letter":"C","text":"Через reflection"},{"letter":"D","text":"Если нет abstract методов"},{"letter":"E","text":"Нет"}],"correct":"E","explanation":"Абстрактный класс не может быть инстанциирован напрямую — new AbstractClass() вызовет ошибку компиляции. Объекты создаются только из конкретных подклассов."},{"n":30,"question":"Дефолтный доступ методов интерфейса?","options":[{"letter":"A","text":"private"},{"letter":"B","text":"abstract"},{"letter":"C","text":"public"},{"letter":"D","text":"package"},{"letter":"E","text":"protected"}],"correct":"C","explanation":"Все методы интерфейса без явного модификатора доступа неявно public. Начиная с Java 9, интерфейсы могут содержать private-методы."},{"n":31,"question":"Как выбросить исключение вручную?","options":[{"letter":"A","text":"catch"},{"letter":"B","text":"except"},{"letter":"C","text":"throw"},{"letter":"D","text":"raise"},{"letter":"E","text":"error"}],"correct":"C","explanation":"Оператор throw выбрасывает исключение вручную: throw new IllegalArgumentException(\"msg\");. Выполнение текущего метода немедленно прерывается."},{"n":32,"question":"Какое исключение при null?","options":[{"letter":"A","text":"NullPointerException"},{"letter":"B","text":"NullReferenceException"},{"letter":"C","text":"ArithmeticException"},{"letter":"D","text":"IllegalState"},{"letter":"E","text":"ClassCast"}],"correct":"A","explanation":"NullPointerException происходит при обращении к методу или полю через ссылку null: например, string.length() если string == null."},{"n":33,"question":"Как правильно override toString()?","options":[{"letter":"A","text":"return name"},{"letter":"B","text":"форматированная строка"},{"letter":"C","text":"return this"},{"letter":"D","text":"return class"},{"letter":"E","text":"return hash"}],"correct":"B","explanation":"При переопределении toString() возвращается строка, описывающая объект. Она автоматически вызывается при System.out.println(obj) и конкатенации со строкой."},{"n":34,"question":"Как проверить наличие ключа в Map?","options":[{"letter":"A","text":"containsKey"},{"letter":"B","text":"has"},{"letter":"C","text":"exists"},{"letter":"D","text":"find"},{"letter":"E","text":"includes"}],"correct":"A","explanation":"Метод containsKey(key) проверяет наличие ключа в Map без извлечения значения. Эффективен для HashMap: O(1) в среднем."},{"n":35,"question":"Главное преимущество Generics?","options":[{"letter":"A","text":"Быстрее"},{"letter":"B","text":"Проверка типов на этапе компиляции"},{"letter":"C","text":"Меньше памяти"},{"letter":"D","text":"Без wrapper"},{"letter":"E","text":"Автоконвертация"}],"correct":"B","explanation":"Generics добавляют проверку типов на этапе компиляции: List<String> не позволит добавить Integer, предотвращая ClassCastException во время выполнения."},{"n":36,"question":"Для чего Optional?","options":[{"letter":"A","text":"Работа с null безопасно"},{"letter":"B","text":"Хранение null"},{"letter":"C","text":"Коллекция"},{"letter":"D","text":"Замена if"},{"letter":"E","text":"Замена try"}],"correct":"A","explanation":"Optional появился в Java 8 для явного выражения возможного отсутствия результата. Методы orElse(), ifPresent(), map() позволяют работать с ним безопасно."},{"n":37,"question":"Что делает Files.readAllLines()?","options":[{"letter":"A","text":"Читает первую строку"},{"letter":"B","text":"Создаёт файл"},{"letter":"C","text":"Считает строки"},{"letter":"D","text":"Читает байты"},{"letter":"E","text":"Читает все строки в List"}],"correct":"E","explanation":"Files.readAllLines(path) из java.nio.file.Files читает все строки файла за одно обращение и возвращает List<String>."},{"n":38,"question":"Какая аннотация для теста JUnit 5?","options":[{"letter":"A","text":"@TestAfter"},{"letter":"B","text":"@Test"},{"letter":"C","text":"@UnitTest"},{"letter":"D","text":"@RunTest"},{"letter":"E","text":"@TestMethod"}],"correct":"B","explanation":"Аннотация @Test (JUnit 5) помечает публичный метод как тест. Фреймворк JUnit находит и выполняет все такие методы автоматически."},{"n":39,"question":"Что такое code coverage?","options":[{"letter":"A","text":"Кол-во тестов"},{"letter":"B","text":"Качество"},{"letter":"C","text":"% кода, покрытого тестами"},{"letter":"D","text":"Время"},{"letter":"E","text":"Ошибки"}],"correct":"C","explanation":"Code coverage (покрытие кода) — метрика, показывающая, какой процент кода выполнялся во время тестирования. Высокое покрытие снижает вероятность скрытых ошибок."},{"n":40,"question":"Что такое коллекция?","options":[{"letter":"A","text":"Файл"},{"letter":"B","text":"Сортировка"},{"letter":"C","text":"Тип данных"},{"letter":"D","text":"Потоки"},{"letter":"E","text":"Объект для хранения группы элементов"}],"correct":"E","explanation":"Коллекция — объект для хранения группы элементов. Java Collections Framework включает List (упорядоченный), Set (уникальные), Queue и Map."}]},{"variant":6,"questions":[{"n":1,"question":"Какое ключевое слово обязательно присутствует в точке входа Java-программы?","options":[{"letter":"A","text":"start"},{"letter":"B","text":"begin"},{"letter":"C","text":"main"},{"letter":"D","text":"run"},{"letter":"E","text":"init"}],"correct":"C","explanation":"Метод main — точка входа в Java-программу. Его подпись строго фиксирована: public static void main(String[] args). JVM ищет именно этот метод для старта."},{"n":2,"question":"Как называется файл байт-кода Java?","options":[{"letter":"A","text":"Program.java"},{"letter":"B","text":"Program.class"},{"letter":"C","text":"Program.jar"},{"letter":"D","text":"Program.bin"},{"letter":"E","text":"Program.exe"}],"correct":"B","explanation":"После компиляции .java-файла с именем Program получается файл Program.class, содержащий байт-код, который выполняет JVM."},{"n":3,"question":"Какой тип данных в Java НЕ является примитивным?","options":[{"letter":"A","text":"int"},{"letter":"B","text":"double"},{"letter":"C","text":"String"},{"letter":"D","text":"boolean"},{"letter":"E","text":"char"}],"correct":"C","explanation":"String — это не примитивный тип, а класс из пакета java.lang. Примитивные типы: byte, short, int, long, float, double, char, boolean."},{"n":4,"question":"Какой оператор используется для логического И (AND)?","options":[{"letter":"A","text":"&"},{"letter":"B","text":"|"},{"letter":"C","text":"&&"},{"letter":"D","text":"AND"},{"letter":"E","text":"and"}],"correct":"C","explanation":"Оператор && (логическое И) возвращает true только если оба операнда истинны. Имеет свойство короткого замыкания: если первый операнд false, второй не вычисляется."},{"n":5,"question":"Чему равно 7 % 2?","options":[{"letter":"A","text":"3"},{"letter":"B","text":"1"},{"letter":"C","text":"3.5"},{"letter":"D","text":"0"},{"letter":"E","text":"2"}],"correct":"B","explanation":"Оператор % возвращает остаток от деления: 7 % 2 = 1, так как 7 = 2 × 3 + 1."},{"n":6,"question":"Что делает блок default в операторе switch?","options":[{"letter":"A","text":"Устанавливает значение по умолчанию"},{"letter":"B","text":"Выполняется, если ни один case не подошёл"},{"letter":"C","text":"Завершает программу"},{"letter":"D","text":"Пропускает все case"},{"letter":"E","text":"Обязательный элемент"}],"correct":"B","explanation":"Блок default в switch выполняется, если ни одна из меток case не совпала со значением выражения. Аналог else в цепочке if-else if."},{"n":7,"question":"В каком порядке проверяются условия в цепочке else if?","options":[{"letter":"A","text":"Сверху вниз, выполняется первое истинное"},{"letter":"B","text":"Снизу вверх"},{"letter":"C","text":"Все условия проверяются одновременно"},{"letter":"D","text":"В случайном порядке"},{"letter":"E","text":"Только первое и последнее"}],"correct":"A","explanation":"Условия в цепочке if-else if проверяются последовательно сверху вниз. Выполняется блок первого истинного условия; остальные пропускаются."},{"n":8,"question":"Какой будет результат выполнения кода: for (int i = 0; i < 5; i++) { if (i == 3) break; System.out.print(i); }","options":[{"letter":"A","text":"01234"},{"letter":"B","text":"0123"},{"letter":"C","text":"012"},{"letter":"D","text":"01235"},{"letter":"E","text":"12345"}],"correct":"C","explanation":"Цикл выполняется для i=0,1,2,3,4. При i==3 срабатывает break — цикл прерывается. До этого выводятся i=0,1,2. Результат: \"012\"."},{"n":9,"question":"Сколько раз выполнится тело цикла: for (int i = 0; i < 5; i++) { }","options":[{"letter":"A","text":"4"},{"letter":"B","text":"5"},{"letter":"C","text":"6"},{"letter":"D","text":"0"},{"letter":"E","text":"Бесконечно"}],"correct":"B","explanation":"Цикл for (int i=0; i<5; i++) выполняется при i=0,1,2,3,4 — ровно 5 итераций."},{"n":10,"question":"Что выведет код: for (int i = 5; i >= 1; i--) System.out.print(i + \" \");","options":[{"letter":"A","text":"1 2 3 4 5"},{"letter":"B","text":"5 4 3 2 1"},{"letter":"C","text":"5 4 3 2 1 0"},{"letter":"D","text":"1 2 3 4 5 6"},{"letter":"E","text":"Ничего"}],"correct":"B","explanation":"Цикл for (int i=5; i>=1; i--) выводит i=5, 4, 3, 2, 1 — обратный отсчёт с шагом −1."},{"n":11,"question":"Что возвращает Math.floor(3.9)?","options":[{"letter":"A","text":"4.0"},{"letter":"B","text":"3.0"},{"letter":"C","text":"3.9"},{"letter":"D","text":"4"},{"letter":"E","text":"3"}],"correct":"B","explanation":"Math.floor(x) округляет до наибольшего целого, не превышающего x. Math.floor(3.9) = 3.0. Аналог — Math.ceil() округляет вверх."},{"n":12,"question":"Что возвращает Math.pow(3, 0)?","options":[{"letter":"A","text":"3.0"},{"letter":"B","text":"0.0"},{"letter":"C","text":"1.0"},{"letter":"D","text":"0"},{"letter":"E","text":"Ошибка"}],"correct":"C","explanation":"Любое число в степени 0 равно 1. Math.pow(3, 0) = 1.0 (возвращает double)."},{"n":13,"question":"Как скопировать массив arr1 в arr2?","options":[{"letter":"A","text":"arr2 = Arrays.copyOf(arr1, arr1.length);"},{"letter":"B","text":"arr2 = arr1;"},{"letter":"C","text":"arr2.copy(arr1);"},{"letter":"D","text":"copy(arr1, arr2);"},{"letter":"E","text":"System.copy(arr1, arr2);"}],"correct":"A","explanation":"Arrays.copyOf(original, length) создаёт новый массив, копируя указанное количество элементов. Это предпочтительнее arr2 = arr1, которое копирует только ссылку."},{"n":14,"question":"Как получить количество строк в двумерном массиве arr?","options":[{"letter":"A","text":"arr.rows"},{"letter":"B","text":"arr[0].length"},{"letter":"C","text":"arr.length"},{"letter":"D","text":"arr.size()"},{"letter":"E","text":"arr.rows()"}],"correct":"C","explanation":"arr.length в двумерном массиве возвращает количество строк (размер внешнего массива). Длина отдельной строки i — это arr[i].length."},{"n":15,"question":"Как транспонировать матрицу (поменять строки и столбцы)?","options":[{"letter":"A","text":"Arrays.transpose(arr)"},{"letter":"B","text":"Создать новый массив: result[j][i] = arr[i][j]"},{"letter":"C","text":"arr.transpose()"},{"letter":"D","text":"Matrix.flip(arr)"},{"letter":"E","text":"Arrays.swap(arr)"}],"correct":"B","explanation":"Транспонирование матрицы меняет строки и столбцы местами: result[j][i] = arr[i][j]. Размерность результата становится M×N → N×M."},{"n":16,"question":"Как проверить, что строка s содержит подстроку \"abc\"?","options":[{"letter":"A","text":"s.has(\"abc\")"},{"letter":"B","text":"s.includes(\"abc\")"},{"letter":"C","text":"s.find(\"abc\")"},{"letter":"D","text":"s.contains(\"abc\")"},{"letter":"E","text":"String.contains(s, \"abc\")"}],"correct":"D","explanation":"Метод contains(substring) возвращает true, если строка содержит указанную подстроку. Регистрочувствителен."},{"n":17,"question":"Какой результат выражения \"hello\".equals(\"Hello\")?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"1"},{"letter":"D","text":"-1"},{"letter":"E","text":"null"}],"correct":"B","explanation":"Метод equals() регистрочувствителен: \"hello\" и \"Hello\" — разные строки. Для нечувствительного сравнения используют equalsIgnoreCase()."},{"n":18,"question":"Как импортировать ArrayList?","options":[{"letter":"A","text":"import java.collections.ArrayList;"},{"letter":"B","text":"import ArrayList;"},{"letter":"C","text":"import java.list.ArrayList;"},{"letter":"D","text":"import java.array.ArrayList;"},{"letter":"E","text":"import java.util.ArrayList;"}],"correct":"E","explanation":"Для использования ArrayList необходимо импортировать: import java.util.ArrayList;. Можно также написать import java.util.*;"},{"n":19,"question":"Как получить текущую дату и время?","options":[{"letter":"A","text":"LocalDate.now()"},{"letter":"B","text":"new Time()"},{"letter":"C","text":"DateTime.now()"},{"letter":"D","text":"LocalDateTime.now()"},{"letter":"E","text":"TimeDate.current()"}],"correct":"D","explanation":"LocalDateTime.now() возвращает текущую дату и время (без временной зоны). LocalDate.now() — только дата, LocalTime.now() — только время."},{"n":20,"question":"Как объявить метод, возвращающий int?","options":[{"letter":"A","text":"void myMethod() { return 5; }"},{"letter":"B","text":"myMethod() int { return 5; }"},{"letter":"C","text":"method int myMethod() { }"},{"letter":"D","text":"return int myMethod() { }"},{"letter":"E","text":"int myMethod() { return 5; }"}],"correct":"E","explanation":"Метод, возвращающий int, объявляется с типом возврата int перед именем: int myMethod() { return 5; }. Ключевое слово return обязательно."},{"n":21,"question":"Какой модификатор позволяет вызывать метод без создания объекта?","options":[{"letter":"A","text":"public"},{"letter":"B","text":"void"},{"letter":"C","text":"static"},{"letter":"D","text":"final"},{"letter":"E","text":"abstract"}],"correct":"C","explanation":"Модификатор static позволяет вызывать метод через имя класса без создания объекта: ClassName.method(). Самый известный пример — Math.abs()."},{"n":22,"question":"Что такое поле класса (field)?","options":[{"letter":"A","text":"Метод класса"},{"letter":"B","text":"Переменная уровня класса, описывающая состояние объекта"},{"letter":"C","text":"Конструктор"},{"letter":"D","text":"Тип возвращаемого значения"},{"letter":"E","text":"Вложенный класс"}],"correct":"B","explanation":"Поле класса (field/attribute) — переменная, объявленная на уровне класса. Она описывает состояние объекта и существует всё время жизни объекта."},{"n":23,"question":"Что такое getter?","options":[{"letter":"A","text":"Метод удаления поля"},{"letter":"B","text":"Метод получения значения private поля"},{"letter":"C","text":"Метод создания объекта"},{"letter":"D","text":"Конструктор"},{"letter":"E","text":"Метод изменения значения"}],"correct":"B","explanation":"Геттер (getter) — public-метод, возвращающий значение private-поля: getName() возвращает поле name. Это часть инкапсуляции."},{"n":24,"question":"Что такое конструктор по умолчанию (default constructor)?","options":[{"letter":"A","text":"Конструктор с параметрами"},{"letter":"B","text":"Параметрless конструктор, автоматически создаваемый компилятором"},{"letter":"C","text":"Конструктор для наследования"},{"letter":"D","text":"Конструктор с final параметрами"},{"letter":"E","text":"Всегда private"}],"correct":"B","explanation":"Конструктор по умолчанию (default constructor) — это конструктор без параметров. Компилятор автоматически его добавляет, если в классе нет ни одного явного конструктора."},{"n":25,"question":"Что делает модификатор public?","options":[{"letter":"A","text":"Доступен везде"},{"letter":"B","text":"Только в пакете"},{"letter":"C","text":"Только в классе"},{"letter":"D","text":"Только в наследниках"},{"letter":"E","text":"Запрещает override"}],"correct":"A","explanation":"Модификатор public делает элемент доступным из любого класса в любом пакете. Это наиболее «открытый» уровень доступа."},{"n":26,"question":"Какое ключевое слово используется для наследования?","options":[{"letter":"A","text":"inherits"},{"letter":"B","text":"implements"},{"letter":"C","text":"extends"},{"letter":"D","text":"uses"},{"letter":"E","text":"from"}],"correct":"C","explanation":"Ключевое слово extends применяется для наследования класса: class Dog extends Animal. Подкласс наследует доступные поля и методы родителя."},{"n":27,"question":"Что такое многоуровневое наследование?","options":[{"letter":"A","text":"Несколько родителей"},{"letter":"B","text":"Цепочка A → B → C"},{"letter":"C","text":"Интерфейсы"},{"letter":"D","text":"Только static"},{"letter":"E","text":"Только пакеты"}],"correct":"B","explanation":"Многоуровневое наследование — цепочка, где B наследует A, а C наследует B: A → B → C. В Java ограничений на глубину цепочки нет."},{"n":28,"question":"Можно ли переопределить метод с модификатором final?","options":[{"letter":"A","text":"Да"},{"letter":"B","text":"Только в наследнике"},{"letter":"C","text":"Нет"},{"letter":"D","text":"Только в пакете"},{"letter":"E","text":"Только private"}],"correct":"C","explanation":"Метод с модификатором final нельзя переопределить (override) в подклассе — это гарантирует неизменность поведения."},{"n":29,"question":"В чём основное отличие abstract класса от интерфейса?","options":[{"letter":"A","text":"Нет различий"},{"letter":"B","text":"abstract может иметь поля и конструкторы"},{"letter":"C","text":"Интерфейс нельзя реализовать"},{"letter":"D","text":"abstract не поддерживает наследование"},{"letter":"E","text":"Интерфейс быстрее"}],"correct":"B","explanation":"Абстрактный класс может иметь поля, конструкторы и конкретные методы. Интерфейс (до Java 8) содержит только абстрактные методы и константы."},{"n":30,"question":"Что такое default-метод в интерфейсе (Java 8+)?","options":[{"letter":"A","text":"Без реализации"},{"letter":"B","text":"Для тестов"},{"letter":"C","text":"Статический метод"},{"letter":"D","text":"Автоматический abstract"},{"letter":"E","text":"Метод с реализацией"}],"correct":"E","explanation":"Default-метод (Java 8+) в интерфейсе имеет реализацию по умолчанию с ключевым словом default. Реализующие классы могут его переопределить или использовать as-is."},{"n":31,"question":"Что такое checked exception?","options":[{"letter":"A","text":"Необрабатываемые ошибки"},{"letter":"B","text":"Только числа"},{"letter":"C","text":"Требуют обработки или throws"},{"letter":"D","text":"Только static"},{"letter":"E","text":"Ошибки JVM"}],"correct":"C","explanation":"Проверяемые (checked) исключения (наследники Exception, но не RuntimeException) обязательны для обработки: компилятор требует try-catch или throws в сигнатуре."},{"n":32,"question":"Для чего используется try-with-resources?","options":[{"letter":"A","text":"Несколько try"},{"letter":"B","text":"Игнор ошибок"},{"letter":"C","text":"Удаление ошибок"},{"letter":"D","text":"Автоматическое закрытие ресурсов"},{"letter":"E","text":"Управление пулом"}],"correct":"D","explanation":"try-with-resources (Java 7+) автоматически закрывает ресурсы (файлы, потоки, соединения), реализующие AutoCloseable, после блока try — аналог finally {resource.close()}."},{"n":33,"question":"Для чего используется оператор instanceof?","options":[{"letter":"A","text":"Создание объекта"},{"letter":"B","text":"Проверка типа"},{"letter":"C","text":"Сравнение"},{"letter":"D","text":"Получение класса"},{"letter":"E","text":"Преобразование"}],"correct":"B","explanation":"Оператор instanceof проверяет, является ли объект экземпляром указанного типа: if (animal instanceof Dog) возвращает true, если animal — объект Dog или его подкласса."},{"n":34,"question":"Как получить все ключи Map?","options":[{"letter":"A","text":"map.keys()"},{"letter":"B","text":"map.allKeys()"},{"letter":"C","text":"map.getKeys()"},{"letter":"D","text":"map.keySet()"},{"letter":"E","text":"map.listKeys()"}],"correct":"D","explanation":"Метод keySet() возвращает Set всех ключей Map. Для перебора всех пар используют entrySet(), для значений — values()."},{"n":35,"question":"Что такое type erasure в Generics?","options":[{"letter":"A","text":"Удаление классов"},{"letter":"B","text":"Удаление информации о типах после компиляции"},{"letter":"C","text":"Преобразование в массив"},{"letter":"D","text":"Ошибка"},{"letter":"E","text":"Приведение к Object"}],"correct":"B","explanation":"Type erasure — механизм компилятора Java, при котором параметры типа Generics удаляются из байт-кода после компиляции, обеспечивая обратную совместимость."},{"n":36,"question":"Как создать непустой Optional?","options":[{"letter":"A","text":"Optional.empty(\"value\")"},{"letter":"B","text":"Optional.create(\"value\")"},{"letter":"C","text":"new Optional(\"value\")"},{"letter":"D","text":"Optional.of(\"value\")"},{"letter":"E","text":"Optional.wrap(\"value\")"}],"correct":"D","explanation":"Optional.of(value) создаёт Optional с непустым значением. Если value == null, будет выброшен NullPointerException (используйте Optional.ofNullable() для null-safe варианта)."},{"n":37,"question":"Какое исключение возникает при работе с файлами?","options":[{"letter":"A","text":"FileException"},{"letter":"B","text":"IOException"},{"letter":"C","text":"FileNotFoundException"},{"letter":"D","text":"StreamException"},{"letter":"E","text":"PathException"}],"correct":"B","explanation":"IOException — это проверяемое исключение, базовый класс для ошибок ввода-вывода: FileNotFoundException, SocketException и другие являются его подклассами."},{"n":38,"question":"Что делает assertEquals(expected, actual)?","options":[{"letter":"A","text":"Проверяет равенство объектов"},{"letter":"B","text":"Бросает исключение"},{"letter":"C","text":"Присваивает значение"},{"letter":"D","text":"Проверяет соответствие ожидаемого и фактического"},{"letter":"E","text":"Сравнивает строки"}],"correct":"D","explanation":"assertEquals(expected, actual) в JUnit проверяет, что ожидаемое значение совпадает с фактическим. При несовпадении тест помечается как проваленный."},{"n":39,"question":"Какой уровень логирования используется для критических ошибок?","options":[{"letter":"A","text":"WARN"},{"letter":"B","text":"DEBUG"},{"letter":"C","text":"ERROR"},{"letter":"D","text":"INFO"},{"letter":"E","text":"TRACE"}],"correct":"C","explanation":"Уровень ERROR указывает на серьёзные ошибки, при которых часть функциональности не работает. FATAL — критические ошибки, после которых программа не может продолжаться."},{"n":40,"question":"Какой принцип ООП отвечает за скрытие данных?","options":[{"letter":"A","text":"Модули"},{"letter":"B","text":"Инкапсуляция"},{"letter":"C","text":"Наследование"},{"letter":"D","text":"Пакеты"},{"letter":"E","text":"Автоматическое создание"}],"correct":"B","explanation":"Инкапсуляция — принцип ООП, скрывающий внутреннее состояние объекта и предоставляющий доступ к нему только через публичные методы (геттеры/сеттеры)."}]},{"variant":7,"questions":[{"n":1,"question":"Как правильно объявить метод main в Java?","options":[{"letter":"A","text":"public void main(String args)"},{"letter":"B","text":"public static void main(String[] args)"},{"letter":"C","text":"static main(String[] args)"},{"letter":"D","text":"void main()"},{"letter":"E","text":"public main(String[] args)"}],"correct":"B","explanation":"Сигнатура метода main строго фиксирована: public static void main(String[] args). JVM ищет именно этот метод как точку входа при запуске программы."},{"n":2,"question":"Какой тип данных используется для хранения целых чисел?","options":[{"letter":"A","text":"double"},{"letter":"B","text":"float"},{"letter":"C","text":"int"},{"letter":"D","text":"char"},{"letter":"E","text":"boolean"}],"correct":"C","explanation":"Тип int — основной целочисленный тип Java: 4 байта, диапазон от −2³¹ до 2³¹−1 (≈ ±2 млрд). Самый часто используемый числовой тип."},{"n":3,"question":"Сколько байт занимает тип byte?","options":[{"letter":"A","text":"1"},{"letter":"B","text":"2"},{"letter":"C","text":"4"},{"letter":"D","text":"8"},{"letter":"E","text":"16"}],"correct":"A","explanation":"Тип byte занимает 1 байт (8 бит) и хранит значения от −128 до 127. Самый компактный целочисленный примитивный тип."},{"n":4,"question":"Какой оператор используется для логического ИЛИ (OR)?","options":[{"letter":"A","text":"|"},{"letter":"B","text":"OR"},{"letter":"C","text":"||"},{"letter":"D","text":"or"},{"letter":"E","text":"^"}],"correct":"C","explanation":"Оператор || (логическое ИЛИ) возвращает true, если хотя бы один из операндов истинен. Имеет короткое замыкание: если первый true, второй не вычисляется."},{"n":5,"question":"Чему равно выражение !true || false?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"null"},{"letter":"D","text":"1"},{"letter":"E","text":"0"}],"correct":"B","explanation":"!true = false; false || false = false. Выражение !true || false равно false || false = false."},{"n":6,"question":"Чему будет равно x после выполнения: int x = 0; if (5 > 3) x = 1; else x = 2;","options":[{"letter":"A","text":"0"},{"letter":"B","text":"1"},{"letter":"C","text":"2"},{"letter":"D","text":"3"},{"letter":"E","text":"5"}],"correct":"B","explanation":"Условие 5 > 3 истинно, поэтому выполняется x = 1. Блок else пропускается. Результат: x = 1."},{"n":7,"question":"Какой цикл проверяет условие перед каждой итерацией?","options":[{"letter":"A","text":"do-while"},{"letter":"B","text":"while"},{"letter":"C","text":"for"},{"letter":"D","text":"foreach"},{"letter":"E","text":"loop"}],"correct":"B","explanation":"Цикл while проверяет условие перед каждой итерацией. Если условие ложно сразу, тело не выполняется. Цикл do-while проверяет условие после первой итерации."},{"n":8,"question":"Какой будет результат выполнения кода: for (int i = 0; i < 5; i++) { if (i == 2) continue; System.out.print(i); }","options":[{"letter":"A","text":"01234"},{"letter":"B","text":"0134"},{"letter":"C","text":"012"},{"letter":"D","text":"1234"},{"letter":"E","text":"0234"}],"correct":"B","explanation":"Цикл выводит i=0,1,3,4 (при i==2 continue пропускает вывод). Результат: \"0134\"."},{"n":9,"question":"Что делает расширенный цикл for (for-each)?","options":[{"letter":"A","text":"Повторяет цикл заданное число раз"},{"letter":"B","text":"Перебирает все элементы массива или коллекции"},{"letter":"C","text":"Выполняет цикл в обратном порядке"},{"letter":"D","text":"Пропускает чётные элементы"},{"letter":"E","text":"Создаёт новый массив"}],"correct":"B","explanation":"Расширенный цикл for-each (for (int x : arr)) автоматически перебирает все элементы массива или коллекции без управления индексом вручную."},{"n":10,"question":"Как посчитать сумму чисел от 1 до 100 с помощью for?","options":[{"letter":"A","text":"for (i = 1; i <= 100; i++) sum = i;"},{"letter":"B","text":"for (int i = 1; i <= 100; i++) sum += i;"},{"letter":"C","text":"for (i = 0; i < 100; i++) sum += i;"},{"letter":"D","text":"for (i = 1; i < 100; i++) sum += i;"},{"letter":"E","text":"for (int i = 100; i > 0; i++) sum += i;"}],"correct":"B","explanation":"Для суммирования чисел от 1 до 100 инициализируем sum=0, запускаем for с i от 1 до 100 включительно (i<=100) и на каждом шаге делаем sum += i."},{"n":11,"question":"Что возвращает Math.ceil(3.1)?","options":[{"letter":"A","text":"4.0"},{"letter":"B","text":"3.0"},{"letter":"C","text":"3.1"},{"letter":"D","text":"3"},{"letter":"E","text":"4"}],"correct":"A","explanation":"Math.ceil(x) округляет до наименьшего целого, не меньшего x (округление вверх). Math.ceil(3.1) = 4.0."},{"n":12,"question":"Как объявить массив целых чисел?","options":[{"letter":"A","text":"int array(5);"},{"letter":"B","text":"int[] array = new int[5];"},{"letter":"C","text":"array int[5];"},{"letter":"D","text":"int array = new[5];"},{"letter":"E","text":"int[] array(5);"}],"correct":"B","explanation":"Массив объявляется с указанием типа, квадратных скобок и размера: int[] array = new int[5]; Создаёт массив из 5 нулей."},{"n":13,"question":"Какой метод сортирует массив?","options":[{"letter":"A","text":"arr.sort()"},{"letter":"B","text":"Arrays.sort(arr)"},{"letter":"C","text":"Sort.array(arr)"},{"letter":"D","text":"arr.order()"},{"letter":"E","text":"Arrays.order(arr)"}],"correct":"B","explanation":"Arrays.sort(arr) из пакета java.util.Arrays сортирует массив примитивов или объектов (реализующих Comparable) в естественном порядке возрастания."},{"n":14,"question":"Как получить количество столбцов в i-й строке двумерного массива?","options":[{"letter":"A","text":"arr.length"},{"letter":"B","text":"arr.cols"},{"letter":"C","text":"arr[i].length"},{"letter":"D","text":"arr[0].size()"},{"letter":"E","text":"arr.columns()"}],"correct":"C","explanation":"arr[i].length возвращает длину строки i двумерного массива. В «рваном» (jagged) массиве строки могут иметь разную длину."},{"n":15,"question":"Что выведет код: int[][] a = {{1,2},{3,4}}; System.out.println(a[1][0]);","options":[{"letter":"A","text":"1"},{"letter":"B","text":"2"},{"letter":"C","text":"3"},{"letter":"D","text":"4"},{"letter":"E","text":"0"}],"correct":"C","explanation":"Двумерный массив индексируется как arr[строка][столбец]. a[1][0]: строка 1 = {3, 4}, индекс 0 = 3."},{"n":16,"question":"Что возвращает s.indexOf(\"abc\")?","options":[{"letter":"A","text":"true или false"},{"letter":"B","text":"Первый индекс или -1"},{"letter":"C","text":"Подстроку"},{"letter":"D","text":"Количество"},{"letter":"E","text":"Последний индекс"}],"correct":"B","explanation":"indexOf(str) возвращает индекс первого вхождения подстроки или −1, если подстрока не найдена. Регистрочувствителен."},{"n":17,"question":"Какой класс реализует интерфейс List?","options":[{"letter":"A","text":"Только LinkedList"},{"letter":"B","text":"ArrayList"},{"letter":"C","text":"HashSet"},{"letter":"D","text":"TreeMap"},{"letter":"E","text":"HashMap"}],"correct":"B","explanation":"ArrayList — наиболее используемая реализация интерфейса List, основанная на динамическом массиве с автоматическим расширением."},{"n":18,"question":"Как полностью очистить коллекцию?","options":[{"letter":"A","text":"empty()"},{"letter":"B","text":"delete()"},{"letter":"C","text":"clear()"},{"letter":"D","text":"removeAll()"},{"letter":"E","text":"reset()"}],"correct":"C","explanation":"Метод clear() удаляет все элементы из коллекции, оставляя её пустой. size() после clear() вернёт 0."},{"n":19,"question":"Как получить день недели из LocalDate?","options":[{"letter":"A","text":"getDay()"},{"letter":"B","text":"dayOfWeek()"},{"letter":"C","text":"getDayOfWeek()"},{"letter":"D","text":"getWeekDay()"},{"letter":"E","text":"weekDay()"}],"correct":"C","explanation":"getDayOfWeek() возвращает объект DayOfWeek (MONDAY, TUESDAY, ...). Для числового значения дня используют getDayOfMonth()."},{"n":20,"question":"Что такое перегрузка методов (overloading)?","options":[{"letter":"A","text":"Наследование метода"},{"letter":"B","text":"Методы с одинаковым именем, но разными параметрами"},{"letter":"C","text":"Изменение байт-кода"},{"letter":"D","text":"Переопределение метода"},{"letter":"E","text":"Использование без импорта"}],"correct":"B","explanation":"Перегрузка (overloading) — несколько методов с одинаковым именем, но разными параметрами в одном классе. Компилятор выбирает нужный по аргументам вызова."},{"n":21,"question":"Какое ключевое слово возвращает значение из метода?","options":[{"letter":"A","text":"give"},{"letter":"B","text":"send"},{"letter":"C","text":"return"},{"letter":"D","text":"output"},{"letter":"E","text":"result"}],"correct":"C","explanation":"Ключевое слово return завершает метод и возвращает значение вызывающему коду. В методе void используют просто return; без значения."},{"n":22,"question":"Как обратиться к полю name объекта dog?","options":[{"letter":"A","text":"dog::name"},{"letter":"B","text":"dog->name"},{"letter":"C","text":"dog.name"},{"letter":"D","text":"dog[name]"},{"letter":"E","text":"Dog.name"}],"correct":"C","explanation":"К полю name объекта dog можно обратиться через точку: dog.name. Если поле private, нужен геттер: dog.getName()."},{"n":23,"question":"Что такое setter?","options":[{"letter":"A","text":"Чтение поля"},{"letter":"B","text":"Изменение значения private поля"},{"letter":"C","text":"Конструктор"},{"letter":"D","text":"static метод"},{"letter":"E","text":"toString"}],"correct":"B","explanation":"Сеттер (setter) — метод, изменяющий значение private-поля: setName(String name) { this.name = name; }. Может включать валидацию данных."},{"n":24,"question":"Что произойдёт, если есть только конструктор с параметрами?","options":[{"letter":"A","text":"Добавится default"},{"letter":"B","text":"Ошибка"},{"letter":"C","text":"Класс станет abstract"},{"letter":"D","text":"Нельзя создать объект без аргументов"},{"letter":"E","text":"Игнорируется"}],"correct":"D","explanation":"Если в классе определён только конструктор с параметрами, компилятор не добавляет дефолтный. Попытка вызвать new MyClass() без аргументов вызовет ошибку компиляции."},{"n":25,"question":"Что делает protected?","options":[{"letter":"A","text":"Запрещает наследование"},{"letter":"B","text":"Только внутри класса"},{"letter":"C","text":"Доступ в пакете и у наследников"},{"letter":"D","text":"Только static"},{"letter":"E","text":"Как private"}],"correct":"C","explanation":"Модификатор protected делает член доступным внутри пакета и для всех подклассов (в любом пакете). Это промежуточный уровень между default и public."},{"n":26,"question":"Что такое наследование?","options":[{"letter":"A","text":"Копирование класса"},{"letter":"B","text":"Использование свойств и методов родителя"},{"letter":"C","text":"Интерфейс"},{"letter":"D","text":"static методы"},{"letter":"E","text":"Изменение типа"}],"correct":"B","explanation":"Наследование (inheritance) позволяет новому классу (подклассу) использовать поля и методы существующего класса (суперкласса), добавляя или изменяя функциональность."},{"n":27,"question":"Что такое полиморфизм?","options":[{"letter":"A","text":"Много объектов"},{"letter":"B","text":"Несколько наследований"},{"letter":"C","text":"Работа через общий интерфейс"},{"letter":"D","text":"Overloading"},{"letter":"E","text":"Автоматическое создание"}],"correct":"C","explanation":"Полиморфизм позволяет обращаться к объектам разных классов через общий интерфейс или тип суперкласса. Конкретный вызываемый метод определяется во время выполнения."},{"n":28,"question":"Правила overriding:","options":[{"letter":"A","text":"Можно менять параметры"},{"letter":"B","text":"Любой return"},{"letter":"C","text":"Имя и параметры совпадают, доступ не уже"},{"letter":"D","text":"Должен быть static"},{"letter":"E","text":"Конструктор"}],"correct":"C","explanation":"При переопределении (override) метод подкласса должен иметь то же имя и список параметров. Модификатор доступа можно расширить (private → public), но не сузить."},{"n":29,"question":"Может ли abstract класс иметь конструктор?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"Да, вызывается через super()"},{"letter":"C","text":"Только без abstract"},{"letter":"D","text":"Только private"},{"letter":"E","text":"Нет"}],"correct":"B","explanation":"Абстрактный класс может иметь конструктор — он вызывается через super() из конструктора подкласса для инициализации родительских полей."},{"n":30,"question":"Могут ли интерфейсы иметь поля?","options":[{"letter":"A","text":"Нет"},{"letter":"B","text":"private"},{"letter":"C","text":"Любые"},{"letter":"D","text":"Только public static final"},{"letter":"E","text":"Только static"}],"correct":"D","explanation":"Поля в интерфейсе неявно являются public static final — то есть это публичные константы, разделяемые всеми реализующими классами."},{"n":31,"question":"Что такое unchecked exception?","options":[{"letter":"A","text":"Необрабатываемые"},{"letter":"B","text":"RuntimeException и его наследники"},{"letter":"C","text":"Только JVM"},{"letter":"D","text":"Только потоки"},{"letter":"E","text":"Только интерфейсы"}],"correct":"B","explanation":"Непроверяемые (unchecked) исключения — подклассы RuntimeException. Компилятор не требует их обязательной обработки, хотя это рекомендуется."},{"n":32,"question":"Какой метод возвращает строковое представление объекта?","options":[{"letter":"A","text":"getString()"},{"letter":"B","text":"describe()"},{"letter":"C","text":"print()"},{"letter":"D","text":"toString()"},{"letter":"E","text":"format()"}],"correct":"D","explanation":"toString() автоматически вызывается JVM при конкатенации объекта со строкой или передаче в println(). Возвращает строковое представление объекта."},{"n":33,"question":"Когда автоматически вызывается toString()?","options":[{"letter":"A","text":"Только вручную"},{"letter":"B","text":"Только debug"},{"letter":"C","text":"При println или конкатенации"},{"letter":"D","text":"Через reflection"},{"letter":"E","text":"Только с @Override"}],"correct":"C","explanation":"toString() вызывается неявно при System.out.println(obj) или конкатенации: \"Object: \" + obj эквивалентно \"Object: \" + obj.toString()."},{"n":34,"question":"Как получить все значения Map?","options":[{"letter":"A","text":"map.values"},{"letter":"B","text":"map.values()"},{"letter":"C","text":"map.getValues()"},{"letter":"D","text":"map.allValues()"},{"letter":"E","text":"map.valueSet()"}],"correct":"B","explanation":"values() возвращает Collection всех значений Map. Порядок элементов зависит от реализации (HashMap — произвольный, LinkedHashMap — порядок вставки)."},{"n":35,"question":"Для чего используется wildcard (?) в Generics?","options":[{"letter":"A","text":"Только String"},{"letter":"B","text":"Неизвестный тип"},{"letter":"C","text":"Только null"},{"letter":"D","text":"Только примитивы"},{"letter":"E","text":"Object"}],"correct":"B","explanation":"Wildcard (?) обозначает неизвестный тип: List<?> может хранить список любого типа. ? extends T — ограничение сверху, ? super T — ограничение снизу."},{"n":36,"question":"Как создать пустой Optional?","options":[{"letter":"A","text":"Optional.of(null)"},{"letter":"B","text":"new Optional()"},{"letter":"C","text":"Optional.empty()"},{"letter":"D","text":"Optional.none()"},{"letter":"E","text":"Optional.null()"}],"correct":"C","explanation":"Optional.empty() создаёт пустой Optional без значения. isPresent() вернёт false, get() выбросит NoSuchElementException."},{"n":37,"question":"Для чего используется enum?","options":[{"letter":"A","text":"Списки"},{"letter":"B","text":"Набор констант"},{"letter":"C","text":"Коллекции"},{"letter":"D","text":"Замена классов"},{"letter":"E","text":"Только числа"}],"correct":"B","explanation":"Enum используется для объявления набора именованных констант: enum Day { MONDAY, TUESDAY, ... } Тип-безопасная замена строковых или целочисленных констант."},{"n":38,"question":"Что делает assertTrue(condition)?","options":[{"letter":"A","text":"Вывод"},{"letter":"B","text":"Проверка true"},{"letter":"C","text":"Установка true"},{"letter":"D","text":"Всегда true"},{"letter":"E","text":"Завершает"}],"correct":"B","explanation":"assertTrue(condition) проверяет, что условие истинно (true). Если condition == false, тест считается проваленным."},{"n":39,"question":"Что такое mock-объект?","options":[{"letter":"A","text":"Реальный объект"},{"letter":"B","text":"Имитация объекта"},{"letter":"C","text":"Пустой класс"},{"letter":"D","text":"Конфиг"},{"letter":"E","text":"Аннотация"}],"correct":"B","explanation":"Mock-объект — имитация реального объекта, возвращающая заранее запрограммированные ответы. Позволяет тестировать класс изолированно от его зависимостей."},{"n":40,"question":"Для чего нужен try-catch?","options":[{"letter":"A","text":"Исправление ошибок"},{"letter":"B","text":"Обработка исключений"},{"letter":"C","text":"Ускорение"},{"letter":"D","text":"Потоки"},{"letter":"E","text":"Удаление ошибок"}],"correct":"B","explanation":"try-catch — основной механизм обработки исключений: код в try выполняется, при исключении управление передаётся в соответствующий блок catch."}]},{"variant":8,"questions":[{"n":1,"question":"Для чего используется класс Scanner в языке Java?","options":[{"letter":"A","text":"Для чтения данных из консоли или других источников"},{"letter":"B","text":"Для вывода данных на экран"},{"letter":"C","text":"Для проверки файлов на вирусы"},{"letter":"D","text":"Для компиляции программ"},{"letter":"E","text":"Для работы с графикой"}],"correct":"A","explanation":"Scanner используется для чтения данных из консоли (System.in), файлов, строк и других источников. Пример: Scanner sc = new Scanner(System.in)."},{"n":2,"question":"Какой тип данных хранит числа с плавающей точкой двойной точности?","options":[{"letter":"A","text":"float"},{"letter":"B","text":"double"},{"letter":"C","text":"int"},{"letter":"D","text":"long"},{"letter":"E","text":"decimal"}],"correct":"B","explanation":"double — 8-байтовый тип с плавающей точкой двойной точности. float — 4 байта, одинарная точность. В Java литералы по умолчанию — double."},{"n":3,"question":"Как объявить переменную типа float со значением 3.14?","options":[{"letter":"A","text":"float x = 3.14;"},{"letter":"B","text":"float x = 3.14f;"},{"letter":"C","text":"float x = 3.14d;"},{"letter":"D","text":"float x = (float)3;"},{"letter":"E","text":"float x = \"3.14\";"}],"correct":"B","explanation":"Литерал с плавающей точкой без суффикса — double. Суффикс f (или F) делает его float: 3.14f. Без суффикса float x = 3.14 вызовет ошибку компиляции."},{"n":4,"question":"Какой оператор используется для логического отрицания (NOT)?","options":[{"letter":"A","text":"!"},{"letter":"B","text":"~"},{"letter":"C","text":"NOT"},{"letter":"D","text":"-"},{"letter":"E","text":"!="}],"correct":"A","explanation":"Оператор ! (логическое НЕ) инвертирует булево значение: !true = false, !false = true."},{"n":5,"question":"Чему равно выражение 2 * 3 + 4 / 2?","options":[{"letter":"A","text":"5"},{"letter":"B","text":"7"},{"letter":"C","text":"8"},{"letter":"D","text":"10"},{"letter":"E","text":"4"}],"correct":"C","explanation":"Приоритет операторов: * и / выполняются раньше + и -. 2*3=6, 4/2=2, 6+2=8."},{"n":6,"question":"С каким из следующих типов оператор switch в Java не может работать?","options":[{"letter":"A","text":"int"},{"letter":"B","text":"String"},{"letter":"C","text":"char"},{"letter":"D","text":"double"},{"letter":"E","text":"byte"}],"correct":"D","explanation":"Switch в Java работает с byte, short, char, int, String, enum и их обёртками. double и float не поддерживаются, так как сравнение значений с плавающей точкой ненадёжно."},{"n":7,"question":"Какой цикл обязательно выполняется хотя бы один раз?","options":[{"letter":"A","text":"while"},{"letter":"B","text":"do-while"},{"letter":"C","text":"for"},{"letter":"D","text":"foreach"},{"letter":"E","text":"repeat"}],"correct":"B","explanation":"Цикл do-while проверяет условие после выполнения тела, поэтому тело всегда выполняется хотя бы один раз — даже если условие изначально ложно."},{"n":8,"question":"Как называется цикл, условие которого проверяется после выполнения тела?","options":[{"letter":"A","text":"Цикл с предусловием"},{"letter":"B","text":"Вложенный цикл"},{"letter":"C","text":"Цикл со счётчиком"},{"letter":"D","text":"Бесконечный цикл"},{"letter":"E","text":"Цикл с постусловием"}],"correct":"E","explanation":"Цикл с постусловием (do-while) проверяет условие после итерации. Цикл с предусловием (while) — до. Первый гарантирует хотя бы одно выполнение."},{"n":9,"question":"Как правильно записать for-each для массива int[] arr?","options":[{"letter":"A","text":"for (arr : int x) { }"},{"letter":"B","text":"for (int x : arr) { }"},{"letter":"C","text":"foreach (int x in arr) { }"},{"letter":"D","text":"for each x in arr { }"},{"letter":"E","text":"for (x of arr) { }"}],"correct":"B","explanation":"For-each для массива записывается как for (int x : arr) { } — перебирает все элементы массива arr, присваивая каждый переменной x."},{"n":10,"question":"Чем цикл for отличается от цикла while?","options":[{"letter":"A","text":"for работает быстрее, чем while"},{"letter":"B","text":"for используется только с массивами"},{"letter":"C","text":"В while нет условия"},{"letter":"D","text":"for объединяет инициализацию, условие и шаг в одной строке"},{"letter":"E","text":"Цикл while нельзя остановить через break"}],"correct":"D","explanation":"Цикл for объединяет инициализацию (int i=0), условие (i<10) и шаг (i++) в одной строке. while требует их написать вручную в разных местах."},{"n":11,"question":"Какая константа класса Math содержит число π?","options":[{"letter":"A","text":"Math.PI_VALUE"},{"letter":"B","text":"Math.pi"},{"letter":"C","text":"Math.PI"},{"letter":"D","text":"Math.CONST_PI"},{"letter":"E","text":"Pi.value"}],"correct":"C","explanation":"Math.PI — константа типа double, содержащая π ≈ 3.14159265358979. Math.E — число Эйлера, Math.PI — число π."},{"n":12,"question":"Какой индекс имеет первый элемент массива в Java?","options":[{"letter":"A","text":"1"},{"letter":"B","text":"0"},{"letter":"C","text":"-1"},{"letter":"D","text":"Зависит от размера"},{"letter":"E","text":"Определяется при создании"}],"correct":"B","explanation":"Индексация массивов в Java начинается с 0. Первый элемент: arr[0], последний: arr[arr.length - 1]."},{"n":13,"question":"Что такое массив в программировании?","options":[{"letter":"A","text":"Отдельная переменная для хранения одного значения"},{"letter":"B","text":"Упорядоченный набор элементов одного типа, доступных по индексу"},{"letter":"C","text":"Список, состоящий из элементов разных типов"},{"letter":"D","text":"Специальный метод языка программирования Java для хранения данных"},{"letter":"E","text":"Альтернативное название класса в объектно-ориентированном подходе"}],"correct":"B","explanation":"Массив — упорядоченная структура данных, хранящая фиксированное число элементов одного типа. Доступ к элементам осуществляется по целочисленному индексу."},{"n":14,"question":"Как можно инициализировать двумерный массив размером 2×2 со значениями?","options":[{"letter":"A","text":"int[][] a = {{1, 2}, {3, 4}};"},{"letter":"B","text":"int[]a = {{1,24};"},{"letter":"C","text":"int[][] a = {1, 2, 3, 4};"},{"letter":"D","text":"int[][] a = new int[]{1,2,3,4};"},{"letter":"E","text":"int[][] a = [{1,2},{3,4}];"}],"correct":"A","explanation":"Двумерный массив инициализируется вложенными фигурными скобками: {{1, 2}, {3, 4}}. Первая строка — {1,2}, вторая — {3,4}."},{"n":15,"question":"Как найти наибольший элемент в двумерном массиве?","options":[{"letter":"A","text":"Использовать Arrays.max(arr)"},{"letter":"B","text":"Сравнить все элементы вложенными циклами"},{"letter":"C","text":"Вызвать arr.max()"},{"letter":"D","text":"Использовать Collections.max(arr)"},{"letter":"E","text":"Использовать Math.max(arr)"}],"correct":"B","explanation":"Для нахождения максимума двумерного массива сравниваем каждый элемент с текущим максимумом через вложенные циклы."},{"n":16,"question":"Как разделить строку \"a,b,c\" по разделителю \",\"?","options":[{"letter":"A","text":"s.split[\",\"]"},{"letter":"B","text":"s.separate(\",\")"},{"letter":"C","text":"String.split(s, \",\")"},{"letter":"D","text":"s.divide(\",\")"},{"letter":"E","text":"s.split(\",\")"}],"correct":"E","explanation":"Метод split(delimiter) разбивает строку по разделителю и возвращает String[]. \"a,b,c\".split(\",\") → {\"a\", \"b\", \"c\"}."},{"n":17,"question":"Как добавить элемент в ArrayList?","options":[{"letter":"A","text":"list.insert(element)"},{"letter":"B","text":"list.put(element)"},{"letter":"C","text":"list.push(element)"},{"letter":"D","text":"list.append(element)"},{"letter":"E","text":"list.add(element)"}],"correct":"E","explanation":"Метод add(element) добавляет элемент в конец ArrayList и возвращает true. add(index, element) — вставляет в указанную позицию."},{"n":18,"question":"Что такое обобщённый тип (generics) в коллекциях? Например List?","options":[{"letter":"A","text":"Список, автоматически форматирующий строки"},{"letter":"B","text":"Ограничение коллекции определённым типом"},{"letter":"C","text":"Класс, работающий только со строками"},{"letter":"D","text":"Массив с автоматически увеличивающимся размером"},{"letter":"E","text":"Аналог массива String[]"}],"correct":"B","explanation":"Generics (обобщения) ограничивают коллекцию элементами одного типа: List<String> принимает только String. Это исключает ошибки приведения типов в runtime."},{"n":19,"question":"В каком пакете находятся классы даты в Java 8+?","options":[{"letter":"A","text":"java.util"},{"letter":"B","text":"java.date"},{"letter":"C","text":"java.time"},{"letter":"D","text":"java.calendar"},{"letter":"E","text":"java.datetime"}],"correct":"C","explanation":"Классы LocalDate, LocalTime, LocalDateTime и другие находятся в пакете java.time, появившемся в Java 8. Старый java.util.Date считается устаревшим."},{"n":20,"question":"Что означает тип возврата void?","options":[{"letter":"A","text":"Возвращает null"},{"letter":"B","text":"Возвращает 0"},{"letter":"C","text":"Ничего не возвращает"},{"letter":"D","text":"Возвращает boolean"},{"letter":"E","text":"Возвращает пустую строку"}],"correct":"C","explanation":"Тип возврата void означает, что метод не возвращает никакого значения. Попытка вернуть значение из void-метода вызовет ошибку компиляции."},{"n":21,"question":"Могут ли два перегруженных (overloaded) метода отличаться только типом возвращаемого значения?","options":[{"letter":"A","text":"Да, это разрешено"},{"letter":"B","text":"Нет, перегрузка определяется только списком параметров"},{"letter":"C","text":"Да, в версии Java 11+"},{"letter":"D","text":"Только если параметры тоже отличаются"},{"letter":"E","text":"Только для примитивных типов возврата"}],"correct":"B","explanation":"Перегруженные методы отличаются списком параметров (количество, типы, порядок). Тип возвращаемого значения не является частью сигнатуры — различия по нему недостаточно."},{"n":22,"question":"Что такое метод класса (instance method)?","options":[{"letter":"A","text":"Функция, объявленная вне класса и не связанная с объектами"},{"letter":"B","text":"Метод, вызываемый через объект и работающий с его состоянием (данными)"},{"letter":"C","text":"Статическая функция, принадлежащая самому классу"},{"letter":"D","text":"Специальный метод, используемый только для создания объектов"},{"letter":"E","text":"Вложенный класс, находящийся внутри другого класса"}],"correct":"B","explanation":"Instance method вызывается через объект (d.bark()), имеет доступ к полям объекта через this и работает с конкретным экземпляром класса."},{"n":23,"question":"Как называется соглашение об именовании геттеров и сеттеров в Java?","options":[{"letter":"A","text":"CamelCase"},{"letter":"B","text":"JavaBeans (get/set + имя поля с заглавной буквы)"},{"letter":"C","text":"snake_case"},{"letter":"D","text":"PascalCase"},{"letter":"E","text":"Hungarian notation"}],"correct":"B","explanation":"JavaBeans — соглашение именования: getter возвращает значение как getName() или isActive(), setter устанавливает как setName(String name)."},{"n":24,"question":"Как вызвать конструктор родительского класса?","options":[{"letter":"A","text":"parent()"},{"letter":"B","text":"base()"},{"letter":"C","text":"super()"},{"letter":"D","text":"this()"},{"letter":"E","text":"super.new()"}],"correct":"C","explanation":"super() вызывает конструктор родительского класса и должен быть первой строкой конструктора подкласса. Позволяет передать аргументы в родительский конструктор."},{"n":25,"question":"Если не указан никакой модификатор, какой используется по умолчанию (by default)?","options":[{"letter":"A","text":"private"},{"letter":"B","text":"public"},{"letter":"C","text":"protected"},{"letter":"D","text":"package-private (доступ только в пределах пакета)"},{"letter":"E","text":"final"}],"correct":"D","explanation":"Package-private (без модификатора) — доступ только в пределах текущего пакета. Это менее открытый уровень, чем protected, но более открытый, чем private."},{"n":26,"question":"Как называется класс, от которого наследуются?","options":[{"letter":"A","text":"Дочерний класс"},{"letter":"B","text":"Производный класс"},{"letter":"C","text":"Родительский класс"},{"letter":"D","text":"Интерфейс"},{"letter":"E","text":"Абстрактный класс"}],"correct":"C","explanation":"Родительский класс (superclass, parent class, base class) — класс, от которого наследуют. Дочерний класс (subclass, child class) — класс, который наследует."},{"n":27,"question":"Что такое переопределение метода (overriding)?","options":[{"letter":"A","text":"Создание нового метода в классе"},{"letter":"B","text":"Замена реализации унаследованного метода в производном классе"},{"letter":"C","text":"Вызов метода родительского класса"},{"letter":"D","text":"Создание метода с другим именем"},{"letter":"E","text":"Перегрузка метода (overloading)"}],"correct":"B","explanation":"Переопределение (overriding) — замена реализации унаследованного метода в подклассе. Сигнатура должна совпадать, аннотация @Override помогает обнаружить ошибки."},{"n":28,"question":"Что такое downcasting в полиморфизме?","options":[{"letter":"A","text":"Преобразование между различными числовыми примитивными типами данных"},{"letter":"B","text":"Явное приведение ссылки суперкласса к типу производного класса: (Dog) animal"},{"letter":"C","text":"Автоматическое преобразование меньшего типа к большему без потери данных"},{"letter":"D","text":"Механизм наследования, позволяющий классу иметь несколько родителей"},{"letter":"E","text":"Преобразование строкового (String) значения в числовой тип данных"}],"correct":"B","explanation":"Downcasting — явное приведение ссылки суперкласса к подклассу: (Dog) animal. Может вызвать ClassCastException при несовпадении реального типа."},{"n":29,"question":"Может ли класс в Java одновременно быть abstract и final?","options":[{"letter":"A","text":"Да, если в классе нет ни одного абстрактного метода и он полностью реализован"},{"letter":"B","text":"Нет, это невозможно: abstract требует наследования, а final запрещает наследование"},{"letter":"C","text":"Да, начиная с Java 11 для повышения безопасности кода такая комбинация разрешена"},{"letter":"D","text":"Да, но только если в классе нет полей и он используется как утилитный класс"},{"letter":"E","text":"Да, это разрешено только для классов, реализующих интерфейсы без методов"}],"correct":"B","explanation":"abstract означает «требует реализации», final — «запрещает изменение». Эти понятия противоречивы: abstract-метод нужно переопределить, а final-класс нельзя наследовать."},{"n":30,"question":"Наследуется ли интерфейс от другого интерфейса?","options":[{"letter":"A","text":"Нет, интерфейсы не наследуются"},{"letter":"B","text":"Да, через extends: interface B extends A"},{"letter":"C","text":"Только через implements"},{"letter":"D","text":"Только в Java 11+"},{"letter":"E","text":"Только один интерфейс"}],"correct":"B","explanation":"Интерфейс может расширять другой интерфейс через extends: interface B extends A. При этом B наследует все абстрактные методы A."},{"n":31,"question":"Что происходит при возникновении необработанного исключения?","options":[{"letter":"A","text":"Программа продолжает работу"},{"letter":"B","text":"JVM перезапускает программу"},{"letter":"C","text":"Программа выводит стек вызовов (stack trace) и аварийно завершает работу"},{"letter":"D","text":"Исключение игнорируется"},{"letter":"E","text":"Программа зависает"}],"correct":"C","explanation":"Необработанное исключение «пузырится» вверх по стеку вызовов. Если ни один метод его не перехватывает, JVM выводит stack trace и завершает программу."},{"n":32,"question":"Что возвращает метод toString() по умолчанию, если он не переопределён (overriding)?","options":[{"letter":"A","text":"Только простое имя класса без дополнительной информации об объекте"},{"letter":"B","text":"Значение null, если у объекта нет переопределённого метода"},{"letter":"C","text":"Имя класса + \"@\" + шестнадцатеричный хэш-код объекта"},{"letter":"D","text":"Строку \"Object\" независимо от типа объекта"},{"letter":"E","text":"Список всех полей объекта в формате ключ-значение"}],"correct":"C","explanation":"По умолчанию (без переопределения) toString() возвращает строку вида «ClassName@hexHashCode». Переопределение позволяет получить осмысленное представление объекта."},{"n":33,"question":"Что такое Map в Java?","options":[{"letter":"A","text":"Графическая модель для отображения данных в виде схем и диаграмм"},{"letter":"B","text":"Специальный вид массива фиксированной длины для хранения однотипных данных"},{"letter":"C","text":"Упорядоченный список элементов, к которым можно обращаться только по индексам"},{"letter":"D","text":"Ассоциативная структура данных, хранящая пары ключ-значение"},{"letter":"E","text":"Метод, используемый в потоках Stream API для преобразования и отображения данных"}],"correct":"D","explanation":"Map — интерфейс для хранения пар ключ–значение. Каждый ключ уникален. Реализации: HashMap, LinkedHashMap, TreeMap."},{"n":34,"question":"Что делает метод map.getOrDefault(key, defaultValue)?","options":[{"letter":"A","text":"Добавляет новый ключ в Map и сохраняет для него значение по умолчанию, даже если ключ уже существует"},{"letter":"B","text":"Возвращает значение по ключу, а если ключ не найден — возвращает значение defaultValue"},{"letter":"C","text":"Проверяет наличие ключа в Map и, если он найден, изменяет его значение на defaultValue"},{"letter":"D","text":"Устанавливает одно общее значение по умолчанию сразу для всех элементов Map"},{"letter":"E","text":"Удаляет указанный ключ из Map и возвращает связанное с ним значение"}],"correct":"B","explanation":"getOrDefault(key, defaultValue) возвращает значение по ключу, если он существует, или defaultValue в противном случае. Удобная альтернатива проверке на null."},{"n":35,"question":"Что означает <? extends Number> в Java Generics?","options":[{"letter":"A","text":"Тип должен строго соответствовать классу Number без возможности использования наследников"},{"letter":"B","text":"Тип может быть любым без ограничений (строки, даты или пользовательские классы)"},{"letter":"C","text":"Тип должен быть классом Number или любым его производным классом (подклассом)"},{"letter":"D","text":"Это выражение используется только для примитивных типов данных, таких как int, double и float"},{"letter":"E","text":"Это специальный синтаксис, запрещающий использование Generics и отключающий проверку типов"}],"correct":"C","explanation":"? extends Number (верхняя граница wildcard) принимает Number и любой его подкласс: Integer, Double, Long и т.д. Гарантирует, что элемент является Number."},{"n":36,"question":"Если Optional пустой, как получить значение или значение по умолчанию?","options":[{"letter":"A","text":"optional.orElse(defaultValue)"},{"letter":"B","text":"optional.get()"},{"letter":"C","text":"optional.getOrDefault(defaulValue)"},{"letter":"D","text":"optional.value(defaultValue)"},{"letter":"E","text":"optional.or(defaultValue)"}],"correct":"A","explanation":"optional.orElse(defaultValue) возвращает значение Optional, если оно есть, или defaultValue — если Optional пустой. Это безопасная альтернатива get()."},{"n":37,"question":"Как объявить перечисление (enum) дней недели?","options":[{"letter":"A","text":"class Day { MON, TUE, WED }"},{"letter":"B","text":"enum Day { MONDAY, TUESDAY, WEDNESDAY }"},{"letter":"C","text":"enum Day = { MONDAY, TUESDAY }"},{"letter":"D","text":"@Enum Day { MONDAY }"},{"letter":"E","text":"interface Day { MONDAY, TUESDAY }"}],"correct":"B","explanation":"Enum дней недели объявляется как enum Day { MONDAY, TUESDAY, WEDNESDAY, ... } Каждая константа — неявно public static final экземпляр этого enum."},{"n":38,"question":"Что означает зелёный результат в JUnit?","options":[{"letter":"A","text":"Тест был пропущен"},{"letter":"B","text":"Есть предупреждение"},{"letter":"C","text":"Тест выполняется"},{"letter":"D","text":"Тест успешно пройден (PASS)"},{"letter":"E","text":"Не компилируется"}],"correct":"D","explanation":"Зелёный результат в JUnit означает, что все тесты прошли успешно (PASS). Красный — что хотя бы один тест провалился (FAIL) или выбросил исключение (ERROR)."},{"n":39,"question":"Что такое регрессионное тестирование?","options":[{"letter":"A","text":"Проверка скорости работы системы при максимальной нагрузке пользователей"},{"letter":"B","text":"Повторное тестирование, чтобы убедиться, что старый функционал не был сломан после изменений"},{"letter":"C","text":"Тестирование системы только на реальных данных в производственной среде (production)"},{"letter":"D","text":"Тестирование только новых функций перед выпуском версии"},{"letter":"E","text":"Проверка совместимости внешних библиотек и внешних модулей системы"}],"correct":"B","explanation":"Регрессионное тестирование — повторный прогон тестов после изменений кода. Цель — убедиться, что новые правки не сломали существующую функциональность."},{"n":40,"question":"Что такое HashMap?","options":[{"letter":"A","text":"Список отсортированных элементов"},{"letter":"B","text":"Список только для чисел"},{"letter":"C","text":"Очередь элементов FIFO (первый вошёл — первый вышел)"},{"letter":"D","text":"Массив фиксированной длины"},{"letter":"E","text":"Структура данных, хранящая пары ключ-значение"}],"correct":"E","explanation":"HashMap — реализация Map, основанная на хэш-таблице. Хранит пары ключ–значение, обеспечивает среднее время O(1) для get() и put(). Не гарантирует порядок."}]},{"variant":9,"questions":[{"n":1,"question":"Из какого пакета импортируется класс Scanner?","options":[{"letter":"A","text":"java.io"},{"letter":"B","text":"java.util"},{"letter":"C","text":"java.lang"},{"letter":"D","text":"java.scan"},{"letter":"E","text":"java.input"}],"correct":"B","explanation":"Класс Scanner находится в пакете java.util. Для его использования нужно написать import java.util.Scanner; в начале файла."},{"n":2,"question":"Какой тип данных хранит один символ в Java?","options":[{"letter":"A","text":"String"},{"letter":"B","text":"byte"},{"letter":"C","text":"char"},{"letter":"D","text":"text"},{"letter":"E","text":"letter"}],"correct":"C","explanation":"Тип char занимает 2 байта и хранит один символ Unicode: char c = 'A'; Используются одинарные кавычки (в отличие от строк с двойными)."},{"n":3,"question":"Какое из следующих имён является корректным именем переменной в Java?","options":[{"letter":"A","text":"1count"},{"letter":"B","text":"my-var"},{"letter":"C","text":"myVar"},{"letter":"D","text":"class"},{"letter":"E","text":"int"}],"correct":"C","explanation":"Имена переменных в Java могут начинаться с буквы, $ или _; не могут начинаться с цифры и не должны совпадать с ключевыми словами. myVar — корректное имя."},{"n":4,"question":"Чему равно значение выражения 5 == 5?","options":[{"letter":"A","text":"true"},{"letter":"B","text":"false"},{"letter":"C","text":"1"},{"letter":"D","text":"0"},{"letter":"E","text":"null"}],"correct":"A","explanation":"Оператор == для чисел проверяет равенство значений. 5 == 5 → true."},{"n":5,"question":"Что делает оператор --?","options":[{"letter":"A","text":"Делит на 2"},{"letter":"B","text":"Уменьшает значение на 1"},{"letter":"C","text":"Увеличивает значение на 1"},{"letter":"D","text":"Возводит в отрицательную степень"},{"letter":"E","text":"Сравнивает два значения"}],"correct":"B","explanation":"Оператор -- уменьшает значение переменной на 1. Постфиксная (x--) форма возвращает старое значение, префиксная (--x) — новое."},{"n":6,"question":"Что такое тернарный оператор в Java?","options":[{"letter":"A","text":"Краткая форма if-else: условие ? значение1 : значение2"},{"letter":"B","text":"Оператор из трёх переменных"},{"letter":"C","text":"Оператор для трёх условий"},{"letter":"D","text":"Оператор побитового сдвига"},{"letter":"E","text":"Специальный оператор switch"}],"correct":"A","explanation":"Тернарный оператор: условие ? значение_если_true : значение_если_false. Компактная замена простой конструкции if-else для присваивания или возврата значения."},{"n":7,"question":"Что делает оператор break внутри цикла?","options":[{"letter":"A","text":"Пропускает текущую итерацию"},{"letter":"B","text":"Переходит к следующему циклу"},{"letter":"C","text":"Перезапускает цикл"},{"letter":"D","text":"Немедленно завершает цикл"},{"letter":"E","text":"Завершает программу"}],"correct":"D","explanation":"Оператор break немедленно завершает текущий цикл (for, while, do-while) или оператор switch и передаёт управление первой инструкции после него."},{"n":8,"question":"Какой синтаксис цикла while в Java?","options":[{"letter":"A","text":"while x < 10 { }"},{"letter":"B","text":"while (x < 10) { }"},{"letter":"C","text":"while [x < 10] { }"},{"letter":"D","text":"while: x < 10 { }"},{"letter":"E","text":"while (x < 10)"}],"correct":"B","explanation":"Синтаксис цикла while: while (условие) { тело }. Условие проверяется перед каждой итерацией; при false тело не выполняется."},{"n":9,"question":"Какой будет результат: int sum = 0; for (int i = 1; i <= 3; i++) sum += i;?","options":[{"letter":"A","text":"3"},{"letter":"B","text":"5"},{"letter":"C","text":"6"},{"letter":"D","text":"9"},{"letter":"E","text":"1"}],"correct":"C","explanation":"Цикл for (int i=1; i<=3; i++) sum += i выполняется для i=1,2,3. 0+1+2+3 = 6."},{"n":10,"question":"Какой будет результат: for (int i = 0; i < 3; i++) { for (int j = 0; j < 2; j++) { System.out.print(\"*\"); } }?","options":[{"letter":"A","text":"**"},{"letter":"B","text":"***"},{"letter":"C","text":"******"},{"letter":"D","text":"****"},{"letter":"E","text":"*****"}],"correct":"C","explanation":"Внешний цикл (i=0,1,2 → 3 итерации) × внутренний (j=0,1 → 2 итерации) = 6 итераций, каждая выводит \"*\". Результат: \"******\"."},{"n":11,"question":"Что возвращает Math.random()?","options":[{"letter":"A","text":"Случайное целое число без дробной части"},{"letter":"B","text":"Случайное число типа double в диапазоне от 0.0 до 1.0"},{"letter":"C","text":"Случайное число в диапазоне от 1 до 100"},{"letter":"D","text":"Одно из случайных значений true или false"},{"letter":"E","text":"Случайный символ из таблицы Unicode"}],"correct":"B","explanation":"Math.random() возвращает double из диапазона [0.0, 1.0) — случайное число, включая 0.0, но не включая 1.0."},{"n":12,"question":"Как получить длину массива arr в Java?","options":[{"letter":"A","text":"arr.size()"},{"letter":"B","text":"arr.length()"},{"letter":"C","text":"arr.length"},{"letter":"D","text":"len(arr)"},{"letter":"E","text":"arr.count()"}],"correct":"C","explanation":"arr.length — публичное финальное поле массива, хранящее его длину. Не метод — скобки не нужны (в отличие от String.length())."},{"n":13,"question":"Как найти наибольший элемент в массиве int[] arr?","options":[{"letter":"A","text":"Использовать несуществующий метод Arrays.max(arr)"},{"letter":"B","text":"Просмотреть все элементы массива циклом и сравнивать с текущим максимумом"},{"letter":"C","text":"Напрямую вызвать метод arr.max()"},{"letter":"D","text":"Применить Math.max(arr) ко всему массиву сразу"},{"letter":"E","text":"Применить Collections.max(arr) к обычному массиву int"}],"correct":"B","explanation":"Стандартный алгоритм поиска максимума: инициализировать max первым элементом, затем пройти цикл и обновлять max при нахождении большего."},{"n":14,"question":"Что такое ступенчатый (jagged) массив в Java?","options":[{"letter":"A","text":"Массив с отрицательными индексами"},{"letter":"B","text":"Двумерный массив, строки которого имеют разную длину"},{"letter":"C","text":"Массив, состоящий из нечётных чисел"},{"letter":"D","text":"Массив с пустыми элементами"},{"letter":"E","text":"Специальный вид двумерного массива только для строк (String)"}],"correct":"B","explanation":"Ступенчатый (jagged) массив — двумерный массив, строки которого имеют разную длину. Создаётся ручной инициализацией каждой строки: int[][] a = new int[3][];"},{"n":15,"question":"Сколько элементов содержит массив int[][] arr = new int[3][4]?","options":[{"letter":"A","text":"7"},{"letter":"B","text":"3"},{"letter":"C","text":"4"},{"letter":"D","text":"12"},{"letter":"E","text":"34"}],"correct":"D","explanation":"Массив new int[3][4] содержит 3 строки по 4 элемента = 12 элементов суммарно."},{"n":16,"question":"Что делает метод s.substring(2, 5)?","options":[{"letter":"A","text":"Удаляет символы с 2 по 5"},{"letter":"B","text":"Возвращает подстроку с индекса 2 по 4 (5 не включается)"},{"letter":"C","text":"Возвращает подстроку с 2 по 5 включительно"},{"letter":"D","text":"Заменяет символы с 2 по 5"},{"letter":"E","text":"Возвращает длину строки"}],"correct":"B","explanation":"substring(start, end) возвращает подстроку с индекса start (включительно) по end (не включительно). s.substring(2,5) — символы с индексами 2, 3, 4."},{"n":17,"question":"В чём разница между Set и List?","options":[{"letter":"A","text":"Set хранит элементы по порядку"},{"letter":"B","text":"Set работает медленнее"},{"letter":"C","text":"List не поддерживает перебор элементов"},{"letter":"D","text":"Set не хранит повторяющиеся элементы"},{"letter":"E","text":"List неупорядочен"}],"correct":"D","explanation":"Set не хранит дубликаты — попытка добавить повторяющийся элемент игнорируется. List допускает дубликаты и сохраняет порядок вставки."},{"n":18,"question":"Как получить элемент из List по индексу?","options":[{"letter":"A","text":"list[0]"},{"letter":"B","text":"list.fetch(0)"},{"letter":"C","text":"list.element(0)"},{"letter":"D","text":"list.item(0)"},{"letter":"E","text":"list.get(0)"}],"correct":"E","explanation":"Метод get(index) в List возвращает элемент по индексу. list.get(0) возвращает первый элемент."},{"n":19,"question":"Как преобразовать дату в формат \"dd.MM.yyyy\"?","options":[{"letter":"A","text":"date.toString(\"dd.MM.yyyy\")"},{"letter":"B","text":"date.format(DateTimeFormatter.ofPattern(\"dd.MM.yyyy\"))"},{"letter":"C","text":"DateFormat.format(date, \"dd.MM.yyyy\")"},{"letter":"D","text":"date.toFormat(\"dd.MM.yyyy\")"},{"letter":"E","text":"String.format(date, \"dd.MM.yyyy\")"}],"correct":"B","explanation":"date.format(DateTimeFormatter.ofPattern(\"dd.MM.yyyy\")) форматирует LocalDate в строку по указанному шаблону: dd — день, MM — месяц, yyyy — год."},{"n":20,"question":"Что такое параметры метода?","options":[{"letter":"A","text":"Возвращаемые значения"},{"letter":"B","text":"Переменные, передаваемые в метод"},{"letter":"C","text":"Внутренние переменные"},{"letter":"D","text":"Поля класса"},{"letter":"E","text":"Названия других методов"}],"correct":"B","explanation":"Параметры метода — переменные, объявленные в его сигнатуре: void foo(int x, String s). Они получают значения при вызове метода (аргументы)."},{"n":21,"question":"Что такое аргументы метода?","options":[{"letter":"A","text":"То же самое, что параметры метода"},{"letter":"B","text":"Тип возвращаемого значения"},{"letter":"C","text":"Переменные внутри метода"},{"letter":"D","text":"Имена параметров в объявлении"},{"letter":"E","text":"Конкретные значения, передаваемые при вызове метода"}],"correct":"E","explanation":"Аргументы — конкретные значения, передаваемые при вызове метода: foo(42, \"hello\"). Параметры (x, s) — переменные в объявлении, аргументы — фактические значения."},{"n":22,"question":"Сколько объектов можно создать на основе одного класса?","options":[{"letter":"A","text":"Только один"},{"letter":"B","text":"Не больше 10"},{"letter":"C","text":"В любом количестве"},{"letter":"D","text":"Только два"},{"letter":"E","text":"Зависит от JVM"}],"correct":"C","explanation":"На основе одного класса можно создать сколько угодно объектов через оператор new. Каждый объект имеет собственный набор значений полей."},{"n":23,"question":"Может ли класс иметь несколько конструкторов?","options":[{"letter":"A","text":"Нет, только один"},{"letter":"B","text":"Да, через перегрузку конструкторов (overloading)"},{"letter":"C","text":"Только в абстрактных классах"},{"letter":"D","text":"Только в версии Java 11+"},{"letter":"E","text":"Только два конструктора"}],"correct":"B","explanation":"Перегрузка конструкторов позволяет создавать объект разными способами: с параметрами или без. Компилятор выбирает нужный конструктор по переданным аргументам."},{"n":24,"question":"Что означает цепочка конструкторов (constructor chaining)?","options":[{"letter":"A","text":"Вызов конструктора после создания объекта"},{"letter":"B","text":"Вызов одного конструктора из другого через this() или super()"},{"letter":"C","text":"Последовательное создание нескольких объектов"},{"letter":"D","text":"Наследование конструкторов"},{"letter":"E","text":"Перегрузка конструкторов"}],"correct":"B","explanation":"Цепочка конструкторов позволяет одному конструктору делегировать инициализацию другому: this() вызывает другой конструктор класса, super() — конструктор родителя."},{"n":25,"question":"Почему поля класса следует делать private?","options":[{"letter":"A","text":"Для ускорения работы программы"},{"letter":"B","text":"Для инкапсуляции и защиты данных"},{"letter":"C","text":"Для наследования"},{"letter":"D","text":"Для использования в статических методах"},{"letter":"E","text":"Для сериализации объектов"}],"correct":"B","explanation":"Поля private недоступны снаружи класса, что защищает данные объекта от некорректного изменения. Это ключевой принцип инкапсуляции."},{"n":26,"question":"Какое ключевое слово используется для обращения к методам и конструкторам родительского класса?","options":[{"letter":"A","text":"parent"},{"letter":"B","text":"base"},{"letter":"C","text":"super"},{"letter":"D","text":"this"},{"letter":"E","text":"extends"}],"correct":"C","explanation":"Ключевое слово super используется для обращения к конструктору родителя (super()), к его полям (super.field) и методам (super.method())."},{"n":27,"question":"Какую аннотацию рекомендуется использовать при переопределении метода?","options":[{"letter":"A","text":"@Overload"},{"letter":"B","text":"@Override"},{"letter":"C","text":"@Extend"},{"letter":"D","text":"@Super"},{"letter":"E","text":"@Redefine"}],"correct":"B","explanation":"Аннотация @Override сообщает компилятору, что метод переопределяет метод суперкласса. Если метод с такой подписью не найден в родителе — ошибка компиляции."},{"n":28,"question":"Что такое абстрактный класс в Java?","options":[{"letter":"A","text":"Полностью пустой класс без полей, методов и логики"},{"letter":"B","text":"Класс, объект которого нельзя создать напрямую и который может содержать абстрактные методы"},{"letter":"C","text":"Класс, состоящий только из static-методов и не имеющий состояния объекта"},{"letter":"D","text":"Класс без конструкторов, используемый только как шаблон данных"},{"letter":"E","text":"Класс, который обязан реализовать хотя бы один интерфейс перед использованием"}],"correct":"B","explanation":"Абстрактный класс — это класс, помеченный abstract, который нельзя инстанциировать напрямую. Он может содержать как абстрактные, так и конкретные методы."},{"n":29,"question":"Где должен быть объявлен абстрактный метод?","options":[{"letter":"A","text":"Только в абстрактном классе или интерфейсе"},{"letter":"B","text":"В любом классе"},{"letter":"C","text":"Только в интерфейсе"},{"letter":"D","text":"В final классе"},{"letter":"E","text":"В классе с implements"}],"correct":"A","explanation":"Абстрактный метод не имеет реализации и должен быть объявлен только в abstract-классе или интерфейсе. Конкретный подкласс обязан его реализовать."},{"n":30,"question":"Можно ли напрямую создать объект интерфейса в Java?","options":[{"letter":"A","text":"Да, интерфейс можно напрямую создать через new"},{"letter":"B","text":"Нет, но можно реализовать через анонимный класс или лямбда-выражение"},{"letter":"C","text":"Да, если есть только default методы"},{"letter":"D","text":"Да, начиная с Java 11"},{"letter":"E","text":"Да, через рефлексию"}],"correct":"B","explanation":"Напрямую создать объект интерфейса нельзя (interface не имеет конструктора), но можно через анонимный класс: Animal a = new Animal() { ... };"},{"n":31,"question":"Какое исключение возникает при делении числа на ноль?","options":[{"letter":"A","text":"NullPointerException"},{"letter":"B","text":"ArrayIndexOutOfBoundsException"},{"letter":"C","text":"NumberFormatException"},{"letter":"D","text":"ArithmeticException"},{"letter":"E","text":"ClassCastException"}],"correct":"D","explanation":"ArithmeticException возникает при арифметической ошибке, наиболее часто — при целочисленном делении на ноль: int x = 5 / 0;"},{"n":32,"question":"Что делает метод equals() по умолчанию (default)?","options":[{"letter":"A","text":"Сравнивает поля объектов"},{"letter":"B","text":"Сравнивает ссылки (то же самое, что оператор ==)"},{"letter":"C","text":"Сравнивает хэш-коды"},{"letter":"D","text":"Сравнивает типы объектов"},{"letter":"E","text":"Всегда возвращает true"}],"correct":"B","explanation":"По умолчанию equals() (унаследованный от Object) сравнивает ссылки, как оператор ==. Переопределяют его для сравнения по содержимому полей."},{"n":33,"question":"Как добавить пару ключ-значение в HashMap?","options":[{"letter":"A","text":"map.add(key, value)"},{"letter":"B","text":"map.insert(key, value)"},{"letter":"C","text":"map.put(key, value)"},{"letter":"D","text":"map.set(key, value)"},{"letter":"E","text":"map.push(key, value)"}],"correct":"C","explanation":"Метод put(key, value) добавляет или обновляет пару ключ–значение в HashMap. Если ключ уже существует, старое значение заменяется новым."},{"n":34,"question":"Как перебрать все пары ключ-значение в Map?","options":[{"letter":"A","text":"for (key : map)"},{"letter":"B","text":"for (Map.Entry<K,V> entry : map.entrySet())"},{"letter":"C","text":"for (map.keys()) each"},{"letter":"D","text":"map.forEach(key)"},{"letter":"E","text":"while (map.hasNext())"}],"correct":"B","explanation":"entrySet() возвращает Set<Map.Entry<K,V>>, позволяя одновременно обращаться к ключу и значению через entry.getKey() и entry.getValue()."},{"n":35,"question":"Для чего используется Iterator в Java?","options":[{"letter":"A","text":"Для автоматической сортировки элементов коллекции"},{"letter":"B","text":"Для последовательного перебора элементов коллекции"},{"letter":"C","text":"Для хранения элементов коллекции в памяти"},{"letter":"D","text":"Для создания новых коллекций данных"},{"letter":"E","text":"Для выполнения математических операций со списками"}],"correct":"B","explanation":"Iterator позволяет последовательно перебирать элементы коллекции через hasNext() и next(). Универсальный способ обхода любой Collection."},{"n":36,"question":"Для чего используется метод Optional.isPresent()?","options":[{"letter":"A","text":"Для получения значения"},{"letter":"B","text":"Для проверки типа"},{"letter":"C","text":"Для преобразования в строку"},{"letter":"D","text":"Для проверки наличия значения (true/false)"},{"letter":"E","text":"Для удаления значения"}],"correct":"D","explanation":"Optional.isPresent() возвращает true, если Optional содержит значение. Аналог: isEmpty() возвращает true, если Optional пустой (Java 11+)."},{"n":37,"question":"Как получить все значения enum?","options":[{"letter":"A","text":"Day.all()"},{"letter":"B","text":"Day.list()"},{"letter":"C","text":"Day.values()"},{"letter":"D","text":"Day.getAll()"},{"letter":"E","text":"Enum.values(Day.class)"}],"correct":"C","explanation":"Day.values() возвращает массив всех констант enum в порядке их объявления. Удобно для итерации по всем значениям перечисления."},{"n":38,"question":"Для чего используется логирование (logging) в программировании?","options":[{"letter":"A","text":"Для автоматического исправления ошибок в коде во время выполнения"},{"letter":"B","text":"Для записи событий и сообщений о работе программы в журнал для последующего анализа"},{"letter":"C","text":"Для ускорения работы программы за счёт оптимизации кода"},{"letter":"D","text":"Для замены процесса компиляции исходного кода приложения"},{"letter":"E","text":"Для устранения всех ошибок программы без участия разработчика"}],"correct":"B","explanation":"Логирование записывает события (запросы, ошибки, действия пользователей) в журнал. Это незаменимо при диагностике проблем в production-среде."},{"n":39,"question":"Что такое валидация входных данных?","options":[{"letter":"A","text":"Форматирование данных перед отображением пользователю"},{"letter":"B","text":"Преобразование одного типа данных в другой"},{"letter":"C","text":"Шифрование данных для защиты от несанкционированного доступа"},{"letter":"D","text":"Проверка корректности данных перед их использованием в программе"},{"letter":"E","text":"Сохранение данных в файл или базу данных"}],"correct":"D","explanation":"Валидация входных данных — проверка их корректности (тип, диапазон, формат) перед использованием. Предотвращает ошибки и уязвимости безопасности."},{"n":40,"question":"Что означает assertFalse(condition) в JUnit?","options":[{"letter":"A","text":"Проверяет, что условие истинно (true)"},{"letter":"B","text":"Если true — выбрасывает исключение"},{"letter":"C","text":"Устанавливает значение false"},{"letter":"D","text":"Если false — пропускает тест"},{"letter":"E","text":"Проверяет, что условие ложно (false); если true, тест не проходит"}],"correct":"E","explanation":"assertFalse(condition) в JUnit проверяет, что условие ложно (false). Если condition == true, тест считается проваленным."}]}]}};
